import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    const modelId = "gemini-2.5-flash-image"; // Optimized for speed and vision

    const prompt = `
      You are an expert Clinical Pharmacist AI assistant called PharmGni.

      Task:
      1. Perform OCR on the provided image of medication bags, prescriptions, or pill bottles.
      2. Identify all medication names, ingredients, dosages, and frequencies.
      3. Analyze the list for Drug-Drug Interactions (DDI), Duplicate Therapies, and Beers Criteria risks based on the patient context provided below.
      4. Prioritize "Red Flags" (Contraindications, Serious Interactions) and "Yellow Flags" (Monitoring needed, Elderly caution).

      Patient Context:
      ${patientContext}

      Output strictly in JSON format matching this schema:
      {
        "medications": [
          { "name": "Brand Name", "ingredient": "Generic Name", "dosage": "e.g. 5mg", "frequency": "e.g. 1T qd", "category": "Drug Class" }
        ],
        "alerts": [
          {
            "level": "RED" | "YELLOW" | "GREEN",
            "title": "Short alert title",
            "reason": "Clinical reasoning (e.g. Mechanism of action overlap)",
            "action": "Specific recommendation for the pharmacist (e.g. Stop Drug A)",
            "drugsInvolved": ["Drug A", "Drug B"]
          }
        ],
        "summary": "A 3-sentence summary of the overall medication safety status."
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64Image } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as AnalysisResult;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    // Return a fallback mock if API fails for demo purposes
    return {
      medications: [],
      alerts: [],
      summary: "AI analysis failed. Please retry.",
    };
  }
};

