interface LicenseVerifyResult {
  score: number;
  passed: boolean;
  logs: string[];
}

export class LicenseVerifier {
  private PASSING_SCORE = 80;

  public calculateScore(ocrText: string, userName: string, userBirth: string): LicenseVerifyResult {
    let score = 0;
    const logs: string[] = [];

    // 1. Normalize
    const cleanText = ocrText.replace(/\s/g, '').replace(/\n/g, '');

    // 2. Logic 1: Name Check
    if (cleanText.includes(userName.replace(/\s/g, ''))) {
      score += 30;
      logs.push(`이름 일치 (+30): ${userName}`);
    }

    // 3. Logic 2: Birth Check
    if (cleanText.includes(userBirth)) {
      score += 30;
      logs.push(`생년월일 일치 (+30): ${userBirth}`);
    }

    // 4. Logic 3: 'Han-Yaksa' Negative Lookbehind
    // JS/TS supports lookbehind in modern environments.
    if (cleanText.includes("한약사")) {
        score -= 100;
        logs.push("경고: '한약사' 키워드 감지 (-100)");
    }

    // 5. Logic 4: Pure Pharmacist Check
    // Regex: look for '약사' not preceded by '한'
    // Since JS lookbehind might vary, we can implement logically or use regex if supported
    try {
        const purePharmacistPattern = /(?<!한)약사/;
        if (purePharmacistPattern.test(cleanText)) {
            score += 50;
            logs.push("유효 키워드 '약사' 감지 (+50)");
        } else {
             // Fallback logic if regex not supported or not found, but "약사" exists
             if (cleanText.includes("약사") && !cleanText.includes("한약사")) {
                 score += 50;
                 logs.push("유효 키워드 '약사' 감지 (+50) - Fallback Logic");
             } else {
                 logs.push("유효 키워드 '약사' 미감지 (0)");
             }
        }
    } catch (e) {
        // Fallback for older browsers
        if (cleanText.indexOf("약사") !== -1 && cleanText.indexOf("한약사") === -1) {
            score += 50;
             logs.push("유효 키워드 '약사' 감지 (+50) - Legacy Support");
        }
    }

    // 6. Extra: Ministry
    if (cleanText.includes("보건복지부장관")) {
        score += 10;
        logs.push("발급기관 확인 (+10)");
    }

    return {
        score,
        passed: score >= this.PASSING_SCORE,
        logs
    };
  }
}

export const verifyLicenseImage = async (file: File, name: string, birth: string): Promise<LicenseVerifyResult> => {
    // In a real app, we would send this to the OCR endpoint.
    // For this demo, we will simulate the OCR result based on the file name or random
    // to allow the user to test the logic.

    return new Promise((resolve) => {
        setTimeout(() => {
            const verifier = new LicenseVerifier();
            // Simulating OCR text output
            // If the user uploads anything, let's assume it's a valid license for the demo
            // unless they named it "hanyaksa.png"

            let mockOcrText = `
                약사면허증
                성명: ${name}
                생년월일: ${birth}
                위 사람은 약사법에 따라 약사 면허를 받았음을 증명합니다.
                보건복지부장관
            `;

            if (file.name.includes("fail")) {
                 mockOcrText = `운전면허증 성명: ${name}`;
            } else if (file.name.includes("hanyaksa")) {
                 mockOcrText = `한약사면허증 성명: ${name} 생년월일: ${birth}`;
            }

            resolve(verifier.calculateScore(mockOcrText, name, birth));
        }, 1500);
    });
};

import React, { useState } from 'react';
import { verifyLicenseImage } from '../services/licenseService';
import { Camera, CheckCircle, AlertTriangle, Upload, User, Calendar } from 'lucide-react';

interface LicenseVerificationProps {
  onVerified: () => void;
}

const LicenseVerification: React.FC<LicenseVerificationProps> = ({ onVerified }) => {
  const [name, setName] = useState('김약사');
  const [birth, setBirth] = useState('800101');
  const [file, setFile] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<{ score: number; passed: boolean; logs: string[] } | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setResult(null);
    }
  };

  const handleVerify = async () => {
    if (!file || !name || !birth) return;
    setIsAnalyzing(true);
    try {
      const verifyResult = await verifyLicenseImage(file, name, birth);
      setResult(verifyResult);
      if (verifyResult.passed) {
        setTimeout(() => {
            onVerified();
        }, 3000); // Wait a bit to show success before redirecting
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-50 p-4">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden">
        <div className="bg-teal-600 p-6 text-white text-center">
          <h1 className="text-2xl font-bold mb-2">PharmGni</h1>
          <p className="text-teal-100 text-sm">약사 면허 인증 (Security Gate)</p>
        </div>

        <div className="p-6 space-y-6">
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">성명 (실명)</label>
              <div className="relative">
                <User className="absolute left-3 top-3 text-slate-400 w-5 h-5" />
                <input 
                  type="text" 
                  value={name} 
                  onChange={(e) => setName(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-teal-500 focus:outline-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">생년월일 (YYMMDD)</label>
              <div className="relative">
                <Calendar className="absolute left-3 top-3 text-slate-400 w-5 h-5" />
                <input 
                  type="text" 
                  value={birth} 
                  onChange={(e) => setBirth(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-teal-500 focus:outline-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">면허증 촬영/업로드</label>
              <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:bg-slate-50 transition-colors relative cursor-pointer">
                <input type="file" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" accept="image/*" />
                {file ? (
                   <div className="text-teal-600 font-medium flex items-center justify-center gap-2">
                     <CheckCircle className="w-5 h-5" /> {file.name}
                   </div>
                ) : (
                   <div className="text-slate-500 flex flex-col items-center">
                     <Camera className="w-8 h-8 mb-2 text-slate-400" />
                     <span>클릭하여 면허증 사진 업로드</span>
                   </div>
                )}
              </div>
            </div>
          </div>

          <button 
            onClick={handleVerify}
            disabled={isAnalyzing || !file}
            className={`w-full py-3 rounded-xl font-bold text-white transition-all shadow-md
              ${isAnalyzing || !file ? 'bg-slate-400' : 'bg-teal-600 hover:bg-teal-700 active:scale-95'}
            `}
          >
            {isAnalyzing ? 'AI 분석 및 검증 중...' : '인증 시작'}
          </button>

          {result && (
            <div className={`rounded-xl p-4 border ${result.passed ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
              <div className="flex items-center justify-between mb-3">
                <span className="font-bold text-slate-800">검증 점수</span>
                <span className={`text-2xl font-black ${result.passed ? 'text-green-600' : 'text-red-600'}`}>
                  {result.score}점
                </span>
              </div>
              <div className="space-y-1 text-sm">
                {result.logs.map((log, idx) => (
                  <div key={idx} className="flex items-start gap-2 text-slate-600">
                    <span className="mt-1 w-1.5 h-1.5 rounded-full bg-slate-400 flex-shrink-0"></span>
                    {log}
                  </div>
                ))}
              </div>
              <div className="mt-4 pt-3 border-t border-dashed border-slate-300 font-medium text-center">
                 {result.passed ? (
                   <span className="text-green-700">인증 성공! 대시보드로 이동합니다.</span>
                 ) : (
                   <span className="text-red-700">인증 실패. 정보를 다시 확인해주세요.</span>
                 )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LicenseVerification;

