interface DrugScannerProps {
  onAnalysisComplete: (result: AnalysisResult) => void;
  patient: Patient;
}

const DrugScanner: React.FC<DrugScannerProps> = ({ onAnalysisComplete, patient }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [preview, setPreview] = useState<string | null>(null);
  const [showOptions, setShowOptions] = useState(false);

  const galleryInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setShowOptions(false);

    // Show Preview
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreview(reader.result as string);
    };
    reader.readAsDataURL(file);

    // Process
    setIsProcessing(true);

    // Prepare context for AI
    const patientContext = `
      Name: ${patient.name}, Age: ${patient.age}, Gender: ${patient.gender}
      Conditions: ${patient.conditions.join(', ')}
      eGFR: ${patient.eGFR || 'Unknown'}
    `;

    try {
      const base64Data = await new Promise<string>((resolve) => {
          const r = new FileReader();
          r.readAsDataURL(file);
          r.onload = () => resolve((r.result as string).split(',')[1]);
      });

      const result = await analyzeMedicalImage(base64Data, patientContext);
      onAnalysisComplete(result);

    } catch (error) {
      console.error("Analysis failed", error);
      alert("AI Analysis failed. Please check your API key.");
    } finally {
      setIsProcessing(false);
    }
  };

  const triggerUpload = (type: 'camera' | 'gallery') => {
    if (type === 'camera') {
      cameraInputRef.current?.click();
    } else {
      galleryInputRef.current?.click();
    }
  };

  return (
    <div className="mt-4 bg-white rounded-xl shadow-sm border border-slate-200 p-5 relative">
      <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
        <Camera className="w-4 h-4 text-teal-600" />
        Snap & Solve (약물 보따리 스캔)
      </h3>

      <div 
        className={`relative aspect-video rounded-lg border-2 border-dashed border-slate-300 bg-slate-50 flex flex-col items-center justify-center overflow-hidden transition-colors ${!isProcessing && 'hover:bg-slate-100 hover:border-teal-400 cursor-pointer'}`}
        onClick={() => !isProcessing && setShowOptions(true)}
      >
        {preview ? (
            <img src={preview} alt="Scan preview" className="absolute inset-0 w-full h-full object-cover opacity-50" />
        ) : null}

        <div className="relative z-10 flex flex-col items-center">
            {isProcessing ? (
                <>
                    <Loader2 className="w-8 h-8 text-teal-600 animate-spin mb-2" />
                    <span className="text-xs font-semibold text-teal-700">Gemini Analyzing...</span>
                </>
            ) : (
                <>
                    <div className="flex gap-2 mb-2">
                        <div className="bg-white p-2 rounded-full shadow-sm">
                            <CameraIcon className="w-5 h-5 text-teal-600" />
                        </div>
                        <div className="bg-white p-2 rounded-full shadow-sm">
                            <ImageIcon className="w-5 h-5 text-slate-400" />
                        </div>
                    </div>
                    <span className="text-xs text-slate-500 font-medium">촬영 혹은 사진 업로드</span>
                    <span className="text-[10px] text-slate-400 mt-1">(처방전, 약봉투, 약통 등)</span>
                </>
            )}
        </div>
      </div>

      {/* Choice Overaly/Popover */}
      {showOptions && !isProcessing && (
          <div className="absolute inset-0 z-20 bg-white/90 backdrop-blur-sm rounded-xl p-5 flex flex-col justify-center animate-in fade-in zoom-in duration-200">
              <p className="text-sm font-bold text-center text-slate-800 mb-4">입력 방식 선택</p>
              <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={(e) => { e.stopPropagation(); triggerUpload('camera'); }}
                    className="flex flex-col items-center justify-center gap-2 p-4 bg-teal-50 border border-teal-100 rounded-xl hover:bg-teal-100 transition-colors group"
                  >
                      <CameraIcon className="w-6 h-6 text-teal-600 group-hover:scale-110 transition-transform" />
                      <span className="text-xs font-bold text-teal-700">직접 촬영</span>
                  </button>
                  <button 
                    onClick={(e) => { e.stopPropagation(); triggerUpload('gallery'); }}
                    className="flex flex-col items-center justify-center gap-2 p-4 bg-slate-50 border border-slate-100 rounded-xl hover:bg-slate-100 transition-colors group"
                  >
                      <Upload className="w-6 h-6 text-slate-600 group-hover:scale-110 transition-transform" />
                      <span className="text-xs font-bold text-slate-700">갤러리 업로드</span>
                  </button>
              </div>
              <button 
                onClick={(e) => { e.stopPropagation(); setShowOptions(false); }}
                className="mt-4 text-xs font-medium text-slate-400 hover:text-slate-600 underline underline-offset-4"
              >
                  취소
              </button>
          </div>
      )}

      {/* Hidden Inputs */}
      <input 
          type="file" 
          ref={galleryInputRef} 
          className="hidden" 
          accept="image/*"
          onChange={handleFileChange}
      />
      <input 
          type="file" 
          ref={cameraInputRef} 
          className="hidden" 
          accept="image/*"
          capture="environment"
          onChange={handleFileChange}
      />

      <p className="text-[10px] text-slate-400 mt-2 text-center">
         * 개인정보 보호를 위해 이미지는 서버에 저장되지 않습니다.
