// 이 파일은 1.2GB의 데이터를 경량화(상위 빈도수 1,000개 수준)하여 
// 프론트엔드에 포함시킨 "핵심 임상 룰셋"을 시뮬레이션합니다.

export interface CompactRule {
  drugA: string;
  drugB: string;
  severity: 'CRITICAL' | 'WARNING';
  reason: string;
}

// 실제 개발 시에는 이 부분을 1.2GB DB에서 추출한 JSON 파일로 대체합니다.
const COMPACT_DUR_RULES: CompactRule[] = [
  {
    drugA: "Clopidogrel",
    drugB: "Omeprazole",
    severity: "WARNING",
    reason: "Omeprazole이 Clopidogrel의 대사를 방해하여 항혈전 효과를 감소시킵니다."
  },
  {
    drugA: "Warfarin",
    drugB: "NSAIDs",
    severity: "CRITICAL",
    reason: "출혈 위험이 급격히 증가합니다. 병용 금기 대상입니다."
  },
  {
      drugA: "Aspirin",
      drugB: "Ibuprofen",
      severity: "WARNING",
      reason: "아스피린의 항혈소판 작용을 저해할 수 있습니다."
  }
];

export const checkLocalDUR = (medications: string[]): CompactRule[] => {
  const detectedRules: CompactRule[] = [];

  // 단순 문자열 매칭 기반의 1차 검색 (실제는 약물 코드 매칭 권장)
  for (const rule of COMPACT_DUR_RULES) {
    const hasA = medications.some(m => m.toLowerCase().includes(rule.drugA.toLowerCase()));
    const hasB = medications.some(m => m.toLowerCase().includes(rule.drugB.toLowerCase()));

    if (hasA && hasB) {
      detectedRules.push(rule);
    }
  }

  return detectedRules;
};

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel } from "../types";
import { checkLocalDUR } from "./durEngine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    const modelId = "gemini-3-pro-preview"; // 복잡한 임상 추론을 위해 Pro 모델 사용 권장

    // 1단계: OCR을 통해 약물 리스트만 먼저 추출하는 내부 단계 (또는 통합 프롬프트)
    // 여기서는 AI에게 로컬 DB 지침을 함께 줍니다.

    const prompt = `
      You are an expert Clinical Pharmacist AI assistant called PharmGni.

      Task:
      1. Perform OCR on the provided image to identify all medications (Name, Ingredient, Dosage).
      2. Analyze the list for Drug-Drug Interactions (DDI) using your internal medical knowledge AND the provided local DUR rules.

      Patient Context:
      ${patientContext}

      Instructions:
      - If you find any of the following interactions from our local high-priority database, prioritize them in the 'alerts' section.
      - Ensure you provide clinical reasoning and specific actions.

      Output strictly in JSON format matching this schema:
      {
        "medications": [
          { "name": "Brand Name", "ingredient": "Generic Name", "dosage": "e.g. 5mg", "frequency": "e.g. 1T qd", "category": "Drug Class" }
        ],
        "alerts": [
          {
            "level": "RED" | "YELLOW" | "GREEN",
            "title": "Short alert title",
            "reason": "Clinical reasoning",
            "action": "Specific recommendation",
            "drugsInvolved": ["Drug A", "Drug B"],
            "isVerifiedByLocalDB": boolean
          }
        ],
        "summary": "Overall summary."
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64Image } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      const parsed = JSON.parse(response.text) as AnalysisResult;

      // 2단계: 결과에 로컬 DUR 엔진 결과가 빠졌는지 재검증 (Double Check)
      const drugNames = parsed.medications.map(m => m.name);
      const localAlerts = checkLocalDUR(drugNames);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => a.title.includes(local.drugA) && a.title.includes(local.drugB));
          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB} 상호작용`,
                  reason: local.reason,
                  action: "로컬 데이터베이스에 의해 확인된 위험입니다. 처방 조정을 고려하십시오.",
                  drugsInvolved: [local.drugA, local.drugB]
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: "AI 분석 중 오류가 발생했습니다.",
    };
  }
};

