import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel, Language } from "../types";
import { checkLocalDUR } from "./durEngine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string,
  language: Language
): Promise<AnalysisResult> => {
  try {
    const modelId = "gemini-3-pro-preview";

    const langMap: Record<Language, string> = {
      ko: "Korean (한국어)",
      en: "English",
      ja: "Japanese (日本語)"
    };

    const targetLang = langMap[language];

    const prompt = `
      System Instruction:
      You are Dr. PharmGni, a Board-Certified Geriatric Pharmacotherapy Specialist (BCGP). 
      Your expertise lies in optimizing medication use for older adults (65+).

      Your Goal:
      Analyze the provided medication image and patient context to identify potential risks, focusing strictly on:
      1. **2023 AGS Beers Criteria®**: Identify Potentially Inappropriate Medications (PIMs) for older adults.
      2. **DUR (Drug Utilization Review)**: Flag absolute contraindications and serious drug-drug interactions.
      3. **Supplement Interactions**: Identify interactions between prescribed drugs and common health functional foods (e.g., Red Ginseng, Omega-3, Probiotics) if inferred or listed.

      Patient Context:
      ${patientContext}

      Analysis Steps:
      1. **OCR**: Extract all visible medication names (Brand/Generic), dosages, and frequencies from the image.
      2. **Risk Assessment**:
         - Check if the patient's age triggers **Beers Criteria** warnings (e.g., Benzodiazepines, Anticholinergics, long-term PPIs).
         - Check for **Renal Dosing** adjustments based on eGFR (if provided).
         - Check for **Drug-Supplement** interactions (e.g., Warfarin + Red Ginseng/Omega-3 bleeding risk).
      3. **Local Rules**: Integrate the provided local DUR rules if applicable.

      Output Format:
      Return a strictly valid JSON object matching the schema below. 
      **IMPORTANT: All textual explanations (title, reason, action, summary, category) MUST be written in ${targetLang}.** 
      Medication names should be kept as they appear or standard English names.

      JSON Schema:
      {
        "medications": [
          { "name": "Brand Name", "ingredient": "Generic Name", "dosage": "e.g. 5mg", "frequency": "e.g. 1T qd", "category": "Drug Class (in ${targetLang})" }
        ],
        "alerts": [
          {
            "level": "RED" | "YELLOW" | "GREEN",
            "title": "Short Alert Title (in ${targetLang})",
            "reason": "Detailed clinical reasoning citing guidelines (in ${targetLang})",
            "action": "Specific recommendation (in ${targetLang})",
            "drugsInvolved": ["Drug A", "Drug B"],
            "isVerifiedByLocalDB": boolean
          }
        ],
        "summary": "A professional clinical summary tailored for a pharmacist (in ${targetLang})."
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64Image } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      let parsed: AnalysisResult;
      try {
        parsed = JSON.parse(response.text) as AnalysisResult;
      } catch (e) {
        console.error("JSON Parsing Error", e);
        throw new Error("Invalid JSON response from AI");
      }

      // Runtime safety checks
      if (!parsed.medications) parsed.medications = [];
      if (!parsed.alerts) parsed.alerts = [];
      if (!parsed.summary) parsed.summary = language === 'en' ? "No summary provided." : language === 'ja' ? "要約なし" : "요약 정보가 없습니다.";

      // Local DUR Check with Language
      const drugNames = parsed.medications.map(m => m.name || m.ingredient || "");
      const localAlerts = checkLocalDUR(drugNames, language);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => 
            (a.title && (a.title.includes(local.drugA) || a.title.includes(local.drugB)))
          );

          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB || (language === 'en' ? 'Caution' : language === 'ja' ? '注意' : '주의')} `,
                  reason: local.reason,
                  action: language === 'en' ? "Consult local guidelines." : language === 'ja' ? "地域のガイドラインを参照してください。" : "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
                  drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
                  isVerifiedByLocalDB: true 
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: language === 'en' ? "Error during AI analysis." : language === 'ja' ? "AI分析中にエラーが発生しました。" : "AI 분석 중 오류가 발생했습니다.",
    };
  }
};

