import React, { useRef, useState, useEffect } from 'react';
import { Camera, Image as ImageIcon, Loader2, Upload, CameraIcon, X, Zap } from 'lucide-react';
import { analyzeMedicalImage } from '../services/geminiService';
import { AnalysisResult, Patient, Language } from '../types';
import { TRANSLATIONS } from '../utils/translations';

interface DrugScannerProps {
  onAnalysisComplete: (result: AnalysisResult) => void;
  patient: Patient;
  language: Language;
}

const DrugScanner: React.FC<DrugScannerProps> = ({ onAnalysisComplete, patient, language }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [preview, setPreview] = useState<string | null>(null);
  const [showOptions, setShowOptions] = useState(false);
  const [showCamera, setShowCamera] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[language];

  // 갤러리 업로드 처리
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setShowOptions(false);
    processImage(file);
  };

  // 이미지 분석 통합 처리
  const processImage = async (fileOrBlob: File | Blob) => {
    // Show Preview
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreview(reader.result as string);
    };
    reader.readAsDataURL(fileOrBlob);

    setIsProcessing(true);

    const patientContext = `
      Name: ${patient.name}, Age: ${patient.age}, Gender: ${patient.gender}
      Conditions: ${patient.conditions.join(', ')}
      eGFR: ${patient.eGFR || 'Unknown'}
    `;

    try {
      const base64Data = await new Promise<string>((resolve) => {
          const r = new FileReader();
          r.readAsDataURL(fileOrBlob);
          r.onload = () => resolve((r.result as string).split(',')[1]);
      });

      // Pass language to service
      const result = await analyzeMedicalImage(base64Data, patientContext, language);
      onAnalysisComplete(result);
    } catch (error) {
      console.error("Analysis failed", error);
      alert("AI Analysis Failed.");
    } finally {
      setIsProcessing(false);
    }
  };

  // 실시간 카메라 시작 (더 유연한 Fallback 로직)
  const startCamera = async () => {
    setShowOptions(false);
    setShowCamera(true);

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      alert("Browser does not support camera or not HTTPS.");
      setShowCamera(false);
      return;
    }

    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = devices.filter(device => device.kind === 'videoinput');
      if (videoDevices.length === 0) {
        alert("No camera device found.");
        setShowCamera(false);
        return;
      }
    } catch (e) {
      console.warn("Could not enumerate devices", e);
    }

    const attempts: MediaStreamConstraints[] = [
      { video: { facingMode: { exact: 'environment' }, width: { ideal: 1920 }, height: { ideal: 1080 } } },
      { video: { facingMode: 'environment' } },
      { video: true }
    ];

    let stream: MediaStream | null = null;
    let lastError: any = null;

    for (const constraints of attempts) {
      try {
        stream = await navigator.mediaDevices.getUserMedia(constraints);
        if (stream) break;
      } catch (err) {
        lastError = err;
      }
    }

    if (stream && videoRef.current) {
      videoRef.current.srcObject = stream;
      videoRef.current.onloadedmetadata = () => {
        videoRef.current?.play().catch(e => console.error("Error playing video:", e));
      };
    } else {
      alert("Camera access failed.");
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setShowCamera(false);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;

      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => {
          if (blob) {
            stopCamera();
            processImage(blob);
          }
        }, 'image/jpeg', 0.85);
      }
    }
  };

  useEffect(() => {
    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  return (
    <div className="mt-4 bg-white rounded-xl shadow-sm border border-slate-200 p-5 relative">
      <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
        <Zap className="w-4 h-4 text-teal-600 fill-teal-600" />
        {t.scan_title}
      </h3>

      <div 
        className={`relative aspect-video rounded-lg border-2 border-dashed border-slate-300 bg-slate-50 flex flex-col items-center justify-center overflow-hidden transition-colors ${!isProcessing && 'hover:bg-slate-100 hover:border-teal-400 cursor-pointer'}`}
        onClick={() => !isProcessing && setShowOptions(true)}
      >
        {preview ? (
            <img src={preview} alt="Scan preview" className="absolute inset-0 w-full h-full object-cover opacity-50" />
        ) : null}

        <div className="relative z-10 flex flex-col items-center">
            {isProcessing ? (
                <>
                    <Loader2 className="w-8 h-8 text-teal-600 animate-spin mb-2" />
                    <span className="text-xs font-semibold text-teal-700">{t.scan_analyzing}</span>
                </>
            ) : (
                <>
                    <div className="flex gap-2 mb-2">
                        <div className="bg-white p-2 rounded-full shadow-sm border border-slate-100">
                            <CameraIcon className="w-5 h-5 text-teal-600" />
                        </div>
                        <div className="bg-white p-2 rounded-full shadow-sm border border-slate-100">
                            <ImageIcon className="w-5 h-5 text-slate-400" />
                        </div>
                    </div>
                    <span className="text-xs text-slate-500 font-bold">{t.scan_placeholder}</span>
                    <span className="text-[10px] text-slate-400 mt-1">{t.scan_subtext}</span>
                </>
            )}
        </div>
      </div>

      {showOptions && !isProcessing && (
          <div className="absolute inset-0 z-20 bg-white/95 backdrop-blur-md rounded-xl p-5 flex flex-col justify-center animate-in fade-in zoom-in duration-200">
              <p className="text-sm font-black text-center text-slate-800 mb-6 tracking-tight">{t.scan_title}</p>
              <div className="grid grid-cols-2 gap-4">
                  <button 
                    onClick={(e) => { e.stopPropagation(); startCamera(); }}
                    className="flex flex-col items-center justify-center gap-3 p-5 bg-teal-600 border border-teal-500 rounded-2xl hover:bg-teal-700 transition-all shadow-md active:scale-95 group"
                  >
                      <CameraIcon className="w-8 h-8 text-white group-hover:scale-110 transition-transform" />
                      <span className="text-sm font-bold text-white">{t.scan_camera}</span>
                  </button>
                  <button 
                    onClick={(e) => { e.stopPropagation(); galleryInputRef.current?.click(); }}
                    className="flex flex-col items-center justify-center gap-3 p-5 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm active:scale-95 group"
                  >
                      <Upload className="w-8 h-8 text-slate-600 group-hover:scale-110 transition-transform" />
                      <span className="text-sm font-bold text-slate-700">{t.scan_upload}</span>
                  </button>
              </div>
              <button 
                onClick={(e) => { e.stopPropagation(); setShowOptions(false); }}
