import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import LicenseVerification from './components/LicenseVerification';
import PatientProfile from './components/PatientProfile';
import DrugScanner from './components/DrugScanner';
import ClinicalDashboard from './components/ClinicalDashboard';
import SmartOutput from './components/SmartOutput';
import { Pharmacist, Patient, AnalysisResult, ViewMode, Language, AlertLevel } from './types';
import { checkLocalDUR } from './services/durEngine';

// Mock Patient Data with Translation Keys
const MOCK_PATIENT: Patient = {
  id: 'p-001',
  name: '김필순',
  birthDate: '1947.05.20',
  age: 78,
  gender: 'F',
  conditions: ['cond_hypertension', 'cond_arthritis', 'cond_kidney'],
  eGFR: 58,
  visitType: 'visit_home' as any // Casting to string for generic type compatibility
};

const App: React.FC = () => {
  // Application State
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.DASHBOARD);
  const [language, setLanguage] = useState<Language>('ko'); // Default Language: Korean

  // 초기 약사 정보를 설정하여 인증 과정을 건너뜁니다.
  const [pharmacist, setPharmacist] = useState<Pharmacist | null>({
      name: '홍길동',
      licenseNumber: '12345',
      isVerified: true
  });

  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);

  // Pharmacist Verification Handler
  const handleVerificationSuccess = () => {
    setPharmacist({
        name: '김약사',
        licenseNumber: '12345',
        isVerified: true
    });
    setViewMode(ViewMode.DASHBOARD);
  };

  const handleLogout = () => {
    setPharmacist(null);
    setAnalysisResult(null);
    setViewMode(ViewMode.VERIFICATION);
  };

  // Effect: When language changes, update the Local DUR alerts dynamically
  useEffect(() => {
    if (analysisResult) {
      // 1. Identify non-local alerts (keep them as is)
      const aiAlerts = analysisResult.alerts.filter(a => !a.isVerifiedByLocalDB);

      // 2. Re-run local DUR check with new language
      const drugNames = analysisResult.medications.map(m => m.name || m.ingredient || "");
      const newLocalAlerts = checkLocalDUR(drugNames, language);

      // 3. Transform to ClinicalAlert format
      const formattedLocalAlerts = newLocalAlerts.map(local => ({
          level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
          title: `[Local DB] ${local.drugA} - ${local.drugB || (language === 'en' ? 'Caution' : language === 'ja' ? '注意' : '주의')} `,
          reason: local.reason,
          action: language === 'en' ? "Consult local guidelines." : language === 'ja' ? "地域のガイドラインを参照してください。" : "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
          drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
          isVerifiedByLocalDB: true 
      }));

      // 4. Merge
      const updatedAlerts = [...aiAlerts];
      // Avoid duplicates if AI already found them, but we want the translated Local ones
      // Since we filtered out `isVerifiedByLocalDB` ones from `aiAlerts`, we can just append.
      // However, if AI found a similar alert that was NOT marked verified (unlikely given the service logic), we might have dupes.
      // But let's assume `isVerifiedByLocalDB` tag is reliable from the service.

      // Optimization: Only add if not already covered by AI alerts (checking titles loosely)
      formattedLocalAlerts.forEach(local => {
         // If AI alert has similar title, skip? No, Local DB is ground truth, we want the translated one.
         updatedAlerts.push(local);
      });

      setAnalysisResult({
        ...analysisResult,
        alerts: updatedAlerts
      });
    }
  }, [language]); // Depend ONLY on language changes

  // Render Verification Screen
  if (viewMode === ViewMode.VERIFICATION) {
    return <LicenseVerification onVerified={handleVerificationSuccess} />;
  }

  // Render Dashboard
  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header 
        pharmacistName={pharmacist?.name || '약사'} 
