import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel } from "../types";
import { checkLocalDUR } from "./durEngine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    const modelId = "gemini-3-pro-preview"; // 복잡한 임상 추론을 위해 Pro 모델 사용

    // 노인 전문 약사(Geriatric Pharmacotherapy Specialist) 페르소나 주입
    // 한국어 출력을 명시적으로 지시
    const prompt = `
      System Instruction:
      You are Dr. PharmGni, a Board-Certified Geriatric Pharmacotherapy Specialist (BCGP). 
      Your expertise lies in optimizing medication use for older adults (65+).

      Your Goal:
      Analyze the provided medication image and patient context to identify potential risks, focusing strictly on:
      1. **2023 AGS Beers Criteria®**: Identify Potentially Inappropriate Medications (PIMs) for older adults.
      2. **DUR (Drug Utilization Review)**: Flag absolute contraindications and serious drug-drug interactions.
      3. **Supplement Interactions**: Identify interactions between prescribed drugs and common health functional foods (e.g., Red Ginseng, Omega-3, Probiotics) if inferred or listed.

      Patient Context:
      ${patientContext}

      Analysis Steps:
      1. **OCR**: Extract all visible medication names (Brand/Generic), dosages, and frequencies from the image.
      2. **Risk Assessment**:
         - Check if the patient's age triggers **Beers Criteria** warnings (e.g., Benzodiazepines, Anticholinergics, long-term PPIs).
         - Check for **Renal Dosing** adjustments based on eGFR (if provided).
         - Check for **Drug-Supplement** interactions (e.g., Warfarin + Red Ginseng/Omega-3 bleeding risk).
      3. **Local Rules**: Integrate the provided local DUR rules if applicable.

      Output Format:
      Return a strictly valid JSON object matching the schema below. 
      **IMPORTANT: All textual explanations (title, reason, action, summary, category) MUST be written in Korean (한국어).** 
      Medication names should be kept as they appear or standard English/Korean names.

      JSON Schema:
      {
        "medications": [
          { "name": "Brand Name", "ingredient": "Generic Name", "dosage": "e.g. 5mg", "frequency": "e.g. 1T qd", "category": "Drug Class (in Korean)" }
        ],
        "alerts": [
          {
            "level": "RED" | "YELLOW" | "GREEN",
            "title": "Short Alert Title (in Korean)",
            "reason": "Detailed clinical reasoning citing guidelines (in Korean)",
            "action": "Specific recommendation (in Korean)",
            "drugsInvolved": ["Drug A", "Drug B"],
            "isVerifiedByLocalDB": boolean
          }
        ],
        "summary": "A professional clinical summary tailored for a pharmacist (in Korean)."
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64Image } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      let parsed: AnalysisResult;
      try {
        parsed = JSON.parse(response.text) as AnalysisResult;
      } catch (e) {
        console.error("JSON Parsing Error", e);
        throw new Error("Invalid JSON response from AI");
      }

      // 안전 장치
      if (!parsed.medications) parsed.medications = [];
      if (!parsed.alerts) parsed.alerts = [];
      if (!parsed.summary) parsed.summary = "요약 정보가 없습니다.";

      // 2단계: 로컬 DUR 엔진 재검증 (Double Check)
      const drugNames = parsed.medications.map(m => m.name || m.ingredient || "");
      const localAlerts = checkLocalDUR(drugNames);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => 
            (a.title && (a.title.includes(local.drugA) || a.title.includes(local.drugB)))
          );

          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB || '주의'} 이슈`,
                  reason: local.reason,
                  action: "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
                  drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
                  isVerifiedByLocalDB: true 
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: "AI 분석 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.",
    };
  }
};

export interface CompactRule {
  drugA: string;
  drugB: string;
  severity: 'CRITICAL' | 'WARNING';
  reason: string;
}

const COMPACT_DUR_RULES_DB: CompactRule[] = [
  {
    drugA: "Clopidogrel",
    drugB: "Omeprazole",
    severity: "WARNING",
    reason: "Omeprazole이 Clopidogrel의 대사를 방해하여 항혈전 효과를 감소시킵니다. (CYP2C19 상호작용)"
  },
  {
    drugA: "Warfarin",
    drugB: "NSAIDs",
    severity: "CRITICAL",
    reason: "위장관 출혈 위험이 급격히 증가합니다. 노인 환자에게 특히 치명적입니다."
  },
  {
      drugA: "Aspirin",
      drugB: "Ibuprofen",
      severity: "WARNING",
      reason: "Ibuprofen이 Aspirin의 심혈관 보호 효과(항혈소판 작용)를 저해할 수 있습니다."
  },
  {
      drugA: "Diazepam",
      drugB: "", 
      severity: "CRITICAL",
      reason: "[Beers Criteria] 장기 작용 벤조디아제핀은 노인에게 낙상, 인지 기능 저하 위험을 높이므로 사용을 피해야 합니다."
  },
  {
      drugA: "Warfarin",
      drugB: "Ginseng",
      severity: "WARNING",
      reason: "[건기식 상호작용] 인삼/홍삼은 와파린의 효과를 감소시켜 혈전 위험을 높일 수 있습니다."
  }
];

export const checkLocalDUR = (medications: string[]): CompactRule[] => {
  const detectedRules: CompactRule[] = [];
  const normalizedMeds = medications.map(m => m.toLowerCase());

  for (const rule of COMPACT_DUR_RULES_DB) {
    // Drug A 체크
    const hasA = normalizedMeds.some(m => m.includes(rule.drugA.toLowerCase()));

    // Drug B 체크 (빈 문자열이면 단일 약물 주의)
    const hasB = rule.drugB === "" || normalizedMeds.some(m => m.includes(rule.drugB.toLowerCase()));

    if (hasA && hasB) {
      detectedRules.push(rule);
    }
  }

  return detectedRules;
};

