import React from 'react';
import { AnalysisResult, AlertLevel } from '../types';
import { AlertTriangle, CheckCircle, Info, ShieldAlert, Database, Search } from 'lucide-react';

interface ClinicalDashboardProps {
  analysis: AnalysisResult | null;
}

const ClinicalDashboard: React.FC<ClinicalDashboardProps> = ({ analysis }) => {
  if (!analysis) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-white rounded-xl border border-slate-200 text-slate-400 p-10 text-center">
        <ShieldAlert className="w-16 h-16 mb-4 text-slate-200" />
        <h3 className="text-lg font-bold text-slate-300">대기 중</h3>
        <p className="text-sm">좌측 패널에서 약물 사진을 스캔해주세요.</p>
      </div>
    );
  }

  return (
    <div className="h-full bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden">
      <div className="p-5 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
            임상 분석 리포트
            <span className="text-[10px] font-bold bg-teal-100 text-teal-700 px-2 py-0.5 rounded-full uppercase">Gemini 3.0 Pro</span>
          </h2>
          <p className="text-sm text-slate-500 mt-1 leading-snug">{analysis.summary}</p>
        </div>
        <div className="flex flex-col items-end min-w-fit ml-4">
            <div className="flex items-center gap-1.5 text-[10px] font-black text-teal-600 bg-white border border-teal-200 px-2 py-1 rounded-md shadow-sm">
                <Database className="w-3 h-3" />
                DUR DB 연결됨
            </div>
            <span className="text-[9px] text-slate-400 mt-1">지식 엔진 v2.0 (Local)</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-4 hide-scrollbar">
        {/* Alerts Section */}
        {analysis.alerts.length > 0 && (
            <div className="space-y-3">
                <h3 className="text-xs font-bold text-slate-400 uppercase flex items-center gap-2">
                    <Search className="w-3 h-3" /> 분석된 임상 위험 요소
                </h3>
                {analysis.alerts.map((alert, idx) => (
                    <div 
                        key={idx} 
                        className={`p-4 rounded-xl border-l-4 shadow-sm transition-all hover:shadow-md ${
                            alert.level === AlertLevel.RED 
                            ? 'bg-red-50 border-red-500' 
                            : alert.level === AlertLevel.YELLOW 
                                ? 'bg-amber-50 border-amber-400'
                                : 'bg-green-50 border-green-500'
                        }`}
                    >
                        <div className="flex items-start justify-between mb-2">
                             <div className="flex items-center gap-2">
                                {alert.level === AlertLevel.RED && <AlertTriangle className="w-5 h-5 text-red-600" />}
                                {alert.level === AlertLevel.YELLOW && <Info className="w-5 h-5 text-amber-600" />}
                                <span className={`font-bold tracking-tight ${
                                    alert.level === AlertLevel.RED ? 'text-red-800' : 'text-amber-800'
                                }`}>
                                    {alert.title}
                                </span>
                             </div>
                             {alert.title.includes('[Local DB]') || alert.isVerifiedByLocalDB ? (
                                 <span className="text-[8px] font-black bg-teal-600 text-white px-1.5 py-0.5 rounded leading-none ml-2">검증됨</span>
                             ) : null}
                        </div>

                        <p className="text-sm text-slate-700 mb-3 leading-relaxed">
                            <span className="font-bold opacity-60">원인:</span> {alert.reason}
                        </p>

                        <div className={`text-sm font-black p-3 rounded-lg flex items-start gap-2 ${
                            alert.level === AlertLevel.RED ? 'bg-red-100 text-red-900' : 'bg-amber-100 text-amber-900'
                        }`}>
                             <span className="shrink-0 bg-white/40 px-1.5 rounded text-[10px] mt-0.5">권고</span>
                             <span>{alert.action}</span>
                        </div>
                    </div>
                ))}
            </div>
        )}

        {/* Medication List Section */}
        <div className="mt-6">
            <h3 className="text-xs font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                <CheckCircle className="w-3 h-3 text-teal-500" /> 인식된 약물 리스트
            </h3>
            <div className="grid grid-cols-1 gap-2">
                {analysis.medications.map((med, idx) => (
                    <div key={idx} className="p-3 bg-white border border-slate-100 rounded-xl flex items-center justify-between hover:border-teal-200 transition-colors shadow-sm">
                        <div className="flex items-center gap-3">
                            <div className="w-8 h-8 bg-slate-50 rounded-lg flex items-center justify-center text-lg">💊</div>
                            <div>
                                <p className="font-bold text-slate-800 text-sm leading-none mb-1">{med.name}</p>
                                <p className="text-[10px] text-slate-500 font-medium">{med.ingredient} | {med.category}</p>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="inline-block px-2 py-1 bg-teal-50 text-teal-700 text-[10px] rounded-md font-black">
                                {med.frequency}
                            </span>
                            <p className="text-[9px] text-slate-400 mt-1">{med.dosage}</p>
                        </div>
                    </div>
                ))}
            </div>
        </div>
      </div>
    </div>
  );
};

export default ClinicalDashboard;

