import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel, Patient } from "../types";
import { checkLocalDUR } from "./durEngine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function cleanJsonString(text: string): string {
  let cleaned = text.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return cleaned;
}

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    const modelId = "gemini-3-pro-preview"; 

    const prompt = `
      System Instruction:
      You are Dr. PharmGni, a Board-Certified Geriatric Pharmacotherapy Specialist (BCGP). 
      Your expertise lies in optimizing medication use for older adults (65+).

      Your Goal:
      Analyze the provided medication image and patient context to identify potential risks.

      Patient Context:
      ${patientContext}

      Task:
      1. **OCR**: Extract all visible medication names (Brand/Generic), dosages, and frequencies.
      2. **Analysis**:
         - **Beers Criteria**: Flag PIMs for older adults.
         - **DUR**: Flag contraindications and interactions.
         - **Supplements**: Check for interactions with common supplements (Ginseng, Omega-3, etc.).

      IMPORTANT: 
      - Return ONLY raw JSON matching the schema.
      - ALL textual explanations (title, reason, action, summary, category) MUST be in **Korean (한국어)**.
      - Ensure 'alerts' include specific clinical reasoning.
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64Image } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      let parsed: AnalysisResult;
      try {
        const cleanedText = cleanJsonString(response.text);
        parsed = JSON.parse(cleanedText) as AnalysisResult;
      } catch (e) {
        console.error("JSON Parsing Error:", e);
        throw new Error("Invalid JSON response from AI");
      }

      if (!parsed.medications) parsed.medications = [];
      if (!parsed.alerts) parsed.alerts = [];
      if (!parsed.summary) parsed.summary = "분석 결과에 대한 요약이 없습니다.";

      const drugNames = parsed.medications.map(m => m.name || m.ingredient || "");
      const localAlerts = checkLocalDUR(drugNames);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => 
            (a.title && (a.title.includes(local.drugA) || a.title.includes(local.drugB)))
          );

          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB || '주의'} 이슈`,
                  reason: local.reason,
                  action: "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
                  drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
                  isVerifiedByLocalDB: true 
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: "AI 분석 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.",
    };
  }
};

export const askClinicalAi = async (
  query: string,
  patient: Patient,
  analysis: AnalysisResult | null
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // De-identification: Pass only clinical data
    const clinicalContext = `
      [Patient Clinical Data]
      - Age: ${patient.age}
      - Gender: ${patient.gender}
      - Conditions: ${patient.conditions.join(", ")}
      - eGFR: ${patient.eGFR || 'Unknown'}

      [Current Medications Analyzed]
      ${analysis ? analysis.medications.map(m => `- ${m.name} (${m.ingredient}) ${m.dosage}`).join("\n") : "None yet scanned."}

      [Current Clinical Alerts]
      ${analysis ? analysis.alerts.map(a => `- ${a.title}: ${a.reason}`).join("\n") : "No alerts recorded."}
    `;

    const systemInstruction = `
      You are a clinical pharmacist AI assistant. 
      Answer the user's question based on the provided clinical context.
      STRICT PRIVACY RULES: Do not ask for or repeat any personal identifiers (Name, DOB, ID, Contact).
      Tone: Professional, clinical, and helpful.
      Language: Korean (한국어).
      Limit your response to clinical facts and recommendations.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: clinicalContext },
        { text: query }
      ],
      config: {
        systemInstruction,
        temperature: 0.7,
      }
    });

    return response.text || "답변을 생성하지 못했습니다.";
  } catch (error) {
    console.error("Clinical AI Error:", error);
    return "임상 상담 중 오류가 발생했습니다. 나중에 다시 시도해주세요.";
  }
};

import React, { useState } from 'react';
import { BrainCircuit, Send, Loader2, ShieldCheck, HelpCircle } from 'lucide-react';
import { askClinicalAi } from '../services/geminiService';
import { Patient, AnalysisResult } from '../types';

interface ClinicalAssistantProps {
  patient: Patient;
  analysis: AnalysisResult | null;
}

const ClinicalAssistant: React.FC<ClinicalAssistantProps> = ({ patient, analysis }) => {
  const [query, setQuery] = useState('');
  const [history, setHistory] = useState<{ role: 'user' | 'ai'; text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSend = async () => {
    if (!query.trim() || isLoading) return;

    const userMsg = query.trim();
    setQuery('');
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const response = await askClinicalAi(userMsg, patient, analysis);
      setHistory(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setHistory(prev => [...prev, { role: 'ai', text: "오류가 발생했습니다." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col mb-4 max-h-[400px]">
      <div className="p-3 bg-indigo-50 border-b border-indigo-100 flex items-center justify-between">
        <h3 className="text-sm font-bold text-indigo-900 flex items-center gap-2">
          <BrainCircuit className="w-4 h-4" />
          임상 AI 어시스턴트
        </h3>
        <div className="flex items-center gap-1.5 px-2 py-0.5 bg-white rounded-full border border-indigo-200">
          <ShieldCheck className="w-3 h-3 text-indigo-600" />
          <span className="text-[10px] font-bold text-indigo-700">개인정보 비식별화됨</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/30 hide-scrollbar min-h-[150px]">
        {history.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full opacity-40 text-center py-4">
             <HelpCircle className="w-8 h-8 mb-2" />
             <p className="text-xs font-medium">환자의 임상 상태나 약물에 대해<br/>무엇이든 물어보세요.</p>
          </div>
        ) : (
          history.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[90%] p-3 rounded-2xl text-sm ${
                msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none shadow-sm'
              }`}>
                {msg.text}
              </div>
            </div>
          ))
        )}
        {isLoading && (
          <div className="flex justify-start">
             <div className="bg-white border border-slate-200 p-3 rounded-2xl rounded-tl-none shadow-sm">
                <Loader2 className="w-4 h-4 text-indigo-600 animate-spin" />
             </div>
          </div>
        )}
      </div>

      <div className="p-2 border-t border-slate-100 bg-white">
        <div className="relative flex items-center">
          <input 
            type="text" 
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="예: 이 환자에게 신기능 주의 약물은?"
            className="w-full pl-3 pr-10 py-2.5 bg-slate-100 border-none rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:outline-none transition-all"
          />
          <button 
            onClick={handleSend}
            disabled={!query.trim() || isLoading}
            className="absolute right-1.5 p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-md transition-colors disabled:opacity-30"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ClinicalAssistant;

