import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel, Patient } from "../types";
import { checkLocalDUR } from "./durEngine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function cleanJsonString(text: string): string {
  let cleaned = text.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return cleaned;
}

/**
 * 시뮬레이션: 전송 전 로컬 환경에서 개인정보 마스킹
 * 실제 구현 시에는 NER(개체명 인식) 라이브러리를 통해 성함 등을 마스킹함.
 */
const simulateLocalMasking = async (base64: string) => {
    // 0.5초간 마스킹 프로세스 시뮬레이션
    return new Promise(resolve => setTimeout(() => resolve(base64), 500));
};

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    // [보완] 전송 전 로컬 마스킹 단계 거침 (Legal Compliance)
    const maskedBase64 = await simulateLocalMasking(base64Image);

    const modelId = "gemini-3-pro-preview"; 

    const prompt = `
      System Instruction:
      You are a Clinical Pharmacist AI (CDSS - Clinical Decision Support System).
      Your output is a 'Suggestion' for a licensed pharmacist.

      STRICT PRIVACY RULE:
      If you see any Names, Resident Registration Numbers (주민번호), or Phone Numbers in the image, 
      IGNORE them and DO NOT include them in your response. 
      Only extract medication names, ingredients, and dosages.

      Patient Clinical Data (Pseudonymized):
      ${patientContext}

      Task:
      1. OCR extraction.
      2. Clinical analysis (Beers Criteria, DUR, Supplements).

      Return ONLY raw JSON matching the schema.
      Language: Korean (한국어).
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: maskedBase64 } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      let parsed: AnalysisResult;
      try {
        const cleanedText = cleanJsonString(response.text);
        parsed = JSON.parse(cleanedText) as AnalysisResult;
      } catch (e) {
        console.error("JSON Parsing Error:", e);
        throw new Error("Invalid JSON response from AI");
      }

      parsed.isVerifiedByPharmacist = false; // Initial state: Not verified

      const drugNames = parsed.medications.map(m => m.name || m.ingredient || "");
      const localAlerts = checkLocalDUR(drugNames);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => 
            (a.title && (a.title.includes(local.drugA) || a.title.includes(local.drugB)))
          );

          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB || '주의'} 이슈`,
                  reason: local.reason,
                  action: "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
                  drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
                  isVerifiedByLocalDB: true 
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: "분석 중 오류가 발생했습니다.",
    };
  }
};

export const askClinicalAi = async (
  query: string,
  patient: Patient,
  analysis: AnalysisResult | null
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Privacy: Only clinical factors
    const clinicalContext = `
      [Clinical Context - No Personal ID]
      - Age: ${patient.age}, Gender: ${patient.gender}
      - Conditions: ${patient.conditions.join(", ")}
      - eGFR: ${patient.eGFR || 'Unknown'}
      - Medications: ${analysis ? analysis.medications.map(m => m.name).join(", ") : "None"}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: clinicalContext },
        { text: query }
      ],
      config: {
        systemInstruction: "You are a BCGP Assistant. Use only Korean. Never ask for Personal IDs.",
        temperature: 0.7,
      }
    });

    return response.text || "답변을 생성하지 못했습니다.";
  } catch (error) {
    return "상담 중 오류가 발생했습니다.";
  }
};

import React, { useRef, useState, useEffect } from 'react';
import { Camera, Image as ImageIcon, Loader2, Upload, CameraIcon, X, Zap, ShieldCheck, Globe } from 'lucide-react';
import { analyzeMedicalImage } from '../services/geminiService';
import { AnalysisResult, Patient } from '../types';

interface DrugScannerProps {
  onAnalysisComplete: (result: AnalysisResult) => void;
  patient: Patient;
}

const DrugScanner: React.FC<DrugScannerProps> = ({ onAnalysisComplete, patient }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [processStep, setProcessStep] = useState<'masking' | 'transferring' | 'analyzing' | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [showOptions, setShowOptions] = useState(false);
  const [showCamera, setShowCamera] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setShowOptions(false);
    processImage(file);
  };

  const processImage = async (fileOrBlob: File | Blob) => {
    const reader = new FileReader();
    reader.onloadend = () => setPreview(reader.result as string);
    reader.readAsDataURL(fileOrBlob);

    setIsProcessing(true);

    // Step 1: Local Masking (Compliance)
    setProcessStep('masking');
    await new Promise(r => setTimeout(r, 800));

    // Step 2: Transfer Notice
    setProcessStep('transferring');
    await new Promise(r => setTimeout(r, 600));

    // Step 3: AI Analysis
    setProcessStep('analyzing');

    try {
      const base64Data = await new Promise<string>((resolve) => {
          const r = new FileReader();
          r.readAsDataURL(fileOrBlob);
          r.onload = () => resolve((r.result as string).split(',')[1]);
      });

      const patientContext = `Age: ${patient.age}, Gender: ${patient.gender}, Conditions: ${patient.conditions.join(', ')}`;
      const result = await analyzeMedicalImage(base64Data, patientContext);
      onAnalysisComplete(result);
    } catch (error) {
      alert("분석 실패");
    } finally {
      setIsProcessing(false);
      setProcessStep(null);
    }
  };

  const startCamera = async () => {
    setShowOptions(false);
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (e) {
      alert("카메라 권한 필요");
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
    setShowCamera(false);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const canvas = canvasRef.current;
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0);
      canvas.toBlob((blob) => { if (blob) { stopCamera(); processImage(blob); } }, 'image/jpeg', 0.8);
    }
  };

  return (
    <div className="mt-4 bg-white rounded-xl shadow-sm border border-slate-200 p-5 relative">
      <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
        <Zap className="w-4 h-4 text-teal-600 fill-teal-600" />
        Snap & Solve (약물 스캔)
      </h3>

      <div 
        className={`relative aspect-video rounded-lg border-2 border-dashed border-slate-300 bg-slate-50 flex flex-col items-center justify-center overflow-hidden transition-colors ${!isProcessing && 'hover:bg-slate-100 hover:border-teal-400 cursor-pointer'}`}
        onClick={() => !isProcessing && setShowOptions(true)}
      >
        {preview && <img src={preview} alt="Scan preview" className="absolute inset-0 w-full h-full object-cover opacity-50" />}

        <div className="relative z-10 flex flex-col items-center text-center px-4">
            {isProcessing ? (
                <>
