interface LicenseVerifyResult {
  score: number;
  passed: boolean;
  logs: string[];
  maskedOcrText?: string;
}

export class LicenseVerifier {
  private PASSING_SCORE = 80;

  /**
   * 주민등록번호 및 민감 정보 마스킹 (Privacy Masking)
   */
  public maskSensitiveData(text: string): string {
    // 주민번호 패턴 (숫자6자리-숫자7자리) 감지하여 뒷자리 마스킹
    const rrnPattern = /(\d{6})[- ]?([1-4]\d{6})/g;
    let masked = text.replace(rrnPattern, '$1-*******');

    // 추가적인 연락처 패턴 마스킹 (010-xxxx-xxxx)
    const phonePattern = /01[016789][- ]?(\d{3,4})[- ]?(\d{4})/g;
    masked = masked.replace(phonePattern, '010-****-****');

    return masked;
  }

  public calculateScore(ocrText: string, userName: string, userBirth: string): LicenseVerifyResult {
    let score = 0;
    const logs: string[] = [];

    // 1. [전처리] 공백 및 줄바꿈 제거 (OCR 인식률 향상을 위한 정문화)
    const cleanText = ocrText.replace(/\s/g, '').replace(/\n/g, '');

    // 2. [로직 1] 본인 확인 (이름/생년월일)
    // 개인정보 보호를 위해 로그에는 매칭 여부만 기록
    if (cleanText.includes(userName.replace(/\s/g, ''))) {
      score += 30;
      logs.push("성명 데이터 일치 확인 (+30)");
    }

    if (cleanText.includes(userBirth)) {
      score += 30;
      logs.push("생년월일 데이터 일치 확인 (+30)");
    }

    // 3. [로직 2] '한약사' 강력 제재 (OCR 오인식 방어)
    if (cleanText.includes("한약사")) {
      score -= 100;
      logs.push("경고: '한약사' 키워드 감지 - 약사 면허 전용 시스템입니다 (-100)");
    }

    // 4. [로직 3] '순수 약사' 판별 (부정 후방 탐색 시뮬레이션)
    // "한약사"가 아닌 "약사" 키워드만 명확히 존재하는지 체크
    const hasYaksa = cleanText.includes("약사");
    const hasHanYaksa = cleanText.includes("한약사");

    if (hasYaksa && !hasHanYaksa) {
      score += 50;
      logs.push("정식 '약사' 면허 키워드 교차 검증 완료 (+50)");
    } else if (hasYaksa && hasHanYaksa) {
      // 이미 위에서 -100 처리됨
    } else {
      logs.push("면허 종별(약사) 키워드를 찾을 수 없음 (0)");
    }

    // 5. [로직 4] 발급기관 및 공신력 확인
    // OCR 오타(보건복지무 등)를 대비하여 핵심 키워드 '장관' 병행 체크
    if (cleanText.includes("보건복지부") || cleanText.includes("장관")) {
      score += 10;
      logs.push("정부 발급 기관인증 인영 확인 (+10)");
    }

    return {
      score,
      passed: score >= this.PASSING_SCORE,
      logs,
      maskedOcrText: this.maskSensitiveData(ocrText)
    };
  }
}

export const verifyLicenseImage = async (file: File, name: string, birth: string): Promise<LicenseVerifyResult> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const verifier = new LicenseVerifier();

      // 시뮬레이션: OCR 엔진이 읽어온 텍스트
      // 실제 구현 시에는 Cloud Vision API 등의 결과를 전달받음
      let mockOcrText = `
        대한민국 정부
        약사면허증
        성명: ${name}
        주민등록번호: ${birth}-1029384
        발급일자: 2015.02.20
        위 사람은 약사법에 따라 약사 면허를 받았음을 증명합니다.
        보건복지부장관 (인)
      `;

      // 실패 시나리오 테스트용
      if (file.name.includes("fail")) {
        mockOcrText = `주민등록증 성명: ${name} 발급: 경찰청장`;
      } else if (file.name.includes("hanyaksa")) {
        mockOcrText = `한약사면허증 성명: ${name} 생년월일: ${birth} 보건복지부`;
      }

      const result = verifier.calculateScore(mockOcrText, name, birth);
      resolve(result);
    }, 1500);
  });
};

import React, { useState } from 'react';
