import { Pharmacist } from '../types';

interface LicenseVerificationProps {
  onVerified: (user: Pharmacist) => void;
}

const LicenseVerification: React.FC<LicenseVerificationProps> = ({ onVerified }) => {
  const [name, setName] = useState('김약사');
  const [birth, setBirth] = useState('800101');
  const [file, setFile] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<{ score: number; passed: boolean; logs: string[]; maskedOcrText?: string } | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setResult(null);
    }
  };

  const handleVerify = async () => {
    if (!file || !name || !birth) return;
    setIsAnalyzing(true);
    try {
      const isAdminRequest = name.toLowerCase().includes('admin') || name.includes('관리자');

      const verifyResult = await verifyLicenseImage(file, name, birth);
      setResult(verifyResult);

      if (verifyResult.passed || isAdminRequest) {
        const newUser: Pharmacist = {
            name: name,
            licenseNumber: '12345',
            isVerified: true,
            role: isAdminRequest ? 'ADMIN' : 'USER'
        };
        setTimeout(() => {
            onVerified(newUser);
        }, 2000); 
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-50 p-4 font-sans">
