}

export class LicenseVerifier {
  private readonly PASSING_SCORE = 80;

  /**
   * [보안] 주민번호 및 민감 정보 마스킹 (Python mask_sensitive_data 로직 이식)
   */
  public maskSensitiveData(text: string): string {
    // 주민번호 뒷자리 패턴 (숫자6자리-숫자7자리) 감지하여 뒷자리 마스킹
    const rrnPattern = /(\d{6})[- ]?([1-4]\d{6})/g;
    let masked = text.replace(rrnPattern, '$1-*******');

    // 연락처 패턴 마스킹 (010-xxxx-xxxx)
    const phonePattern = /01[016789][- ]?(\d{3,4})[- ]?(\d{4})/g;
    masked = masked.replace(phonePattern, '010-****-****');

    return masked;
  }

  /**
   * [로직] 파이썬 calculate_score 로직 정밀 이식
   */
  public calculateScore(ocrText: string, userName: string, userBirth: string): { score: number, logs: string[] } {
    let score = 0;
    const logs: string[] = [];

    // [전처리] 공백 및 줄바꿈 제거
    const cleanText = ocrText.replace(/\s/g, '').replace(/\n/g, '');

    // [로직 1] 본인 확인
    if (cleanText.includes(userName.replace(/\s/g, ''))) {
      score += 30;
      logs.push("본인 성명 일치 확인 (+30)");
    }

    if (cleanText.includes(userBirth)) {
      score += 30;
      logs.push("생년월일 일치 확인 (+30)");
    }

    // [로직 2] '한약사' 강력 제재 (Negative Scoring)
    if (cleanText.includes("한약사")) {
      score -= 100;
      logs.push("경고: '한약사' 키워드 감지 - 약사 전용 서비스입니다 (-100)");
    }

    // [로직 3] '순수 약사' 판별 (Python Regex: (?<!한)약사 대응)
    const hasYaksa = cleanText.includes("약사");
    const hasHanYaksa = cleanText.includes("한약사");

    if (hasYaksa && !hasHanYaksa) {
      score += 50;
      logs.push("유효 키워드 '약사' 감지 (+50)");
    } else if (!hasYaksa) {
      logs.push("유효 키워드 '약사' 미감지 (0)");
    }

    // [로직 4] 발급기관 확인 (OCR 오타 대응 유연성)
    if (cleanText.includes("보건복지부") || cleanText.includes("장관")) {
      score += 10;
      logs.push("발급기관(보건복지부/장관) 확인 (+10)");
    }

    return { score, logs };
  }
}

/**
 * 서버 사이드 인증 프로세스 시뮬레이션
 * (Supabase User Table 업데이트 포함)
 */
export const verifyLicenseImage = async (file: File, name: string, birth: string): Promise<LicenseVerifyResult> => {
  // 서버 처리 시뮬레이션 (1.5초)
  return new Promise((resolve) => {
    setTimeout(() => {
      const verifier = new LicenseVerifier();

      // 실제 구현 시 Google Vision API 혹은 Tesseract OCR 결과가 들어오는 지점
      let mockOcrText = `
        대한민국 보건복지부
        약사면허증
        성명: ${name}
        주민등록번호: ${birth}-1******
        면허번호: 제12345호
        위 사람은 약사법 제7조에 따라 약사의 면허를 받았음을 증명합니다.
        보건복지부장관 (인)
      `;

      // 테스트용 예외 처리
      if (file.name.includes("hanyaksa")) {
        mockOcrText = `한약사면허증 성명: ${name} 보건복지부`;
      } else if (file.name.includes("other")) {
        mockOcrText = `주민등록증 성명: ${name} 경찰청장`;
      }

      const { score, logs } = verifier.calculateScore(mockOcrText, name, birth);
      const passed = score >= 80;

      // ★[보안 필수] DB 저장 전 마스킹 수행
      const safeOcrText = verifier.maskSensitiveData(mockOcrText);

      /**
       * SUPABASE UPDATE SIMULATION
       * const { data, error } = await supabase
       *   .from('users')
       *   .update({ status: 'active', ocr_log: safeOcrText })
       *   .eq('name', name);
       */
      const finalStatus = passed ? 'active' : 'rejected';

      resolve({
        score,
        passed,
        logs,
        maskedOcrText: safeOcrText,
        status: finalStatus
      });
    }, 1500);
  });
};

