import React, { useState } from 'react';
import { requestLicenseApproval } from '../services/licenseService';
import { CheckCircle, Upload, User, Calendar, ShieldCheck, Lock, Database, Loader2, AlertTriangle, Check, Key } from 'lucide-react';
import { Pharmacist } from '../types';

interface LicenseVerificationProps {
  onVerified: (user: Pharmacist) => void;
}

const LicenseVerification: React.FC<LicenseVerificationProps> = ({ onVerified }) => {
  const [name, setName] = useState('');
  const [birth, setBirth] = useState('');
  const [licenseNo, setLicenseNo] = useState('');
  const [password, setPassword] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [step, setStep] = useState<'idle' | 'ocr' | 'ready'>('idle');
  const [agreed, setAgreed] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      handleAutoScan(e.target.files[0]);
    }
  };

  const handleAutoScan = async (selectedFile: File) => {
    setIsAnalyzing(true);
    setStep('ocr');

    try {
      const tempBirth = birth || '800101';
      const res = await requestLicenseApproval(selectedFile, name || '김약사', tempBirth);

      if (!name) setName(res.extractedName || '');
      setLicenseNo(res.extractedLicenseNo || '');
      setStep('ready');
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmitRequest = () => {
    if (!name || !licenseNo || !password || !agreed) return;

    const isSystemAdmin = name.includes('관리자') || name.toLowerCase().includes('admin');

    const newUser: Pharmacist = {
      name,
      licenseNumber: licenseNo,
      isVerified: isSystemAdmin,
      role: isSystemAdmin ? 'ADMIN' : 'USER',
      status: isSystemAdmin ? 'ACTIVE' : 'PENDING',
      requestDate: new Date().toISOString(),
      password: password
    };

    if (isSystemAdmin) {
      onVerified(newUser);
    } else {
      alert("승인 요청이 완료되었습니다! 약사님이 수동 확인 후 24시간 내에 활성화됩니다.");
      window.location.reload();
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4 font-sans" role="main">
      <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-200">
        <div className="bg-slate-900 p-10 text-white relative">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none overflow-hidden" aria-hidden="true">
             <Database className="w-64 h-64 -rotate-12 -ml-20 -mt-20" />
          </div>
          <div className="relative z-10 text-center">
            <h1 className="text-4xl font-black tracking-tighter mb-2">PharmGni</h1>
            <p className="text-teal-400 text-[10px] font-black uppercase tracking-[0.3em]">Pharmacist Network Only</p>
          </div>
        </div>

        <div className="p-8 space-y-6">
          <section className="space-y-4" aria-labelledby="upload-section">
            <h2 id="upload-section" className="sr-only">면허증 업로드</h2>
            <div className="relative border-2 border-dashed border-slate-200 rounded-3xl p-6 text-center hover:bg-slate-50 transition-all cursor-pointer group focus-within:ring-2 focus-within:ring-teal-500">
              <input 
                type="file" 
                onChange={handleFileChange} 
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                aria-label="약사 면허증 사진 업로드"
              />
              {file ? (
                <div className="flex flex-col items-center gap-2">
                  <div className="w-12 h-12 bg-teal-100 text-teal-600 rounded-full flex items-center justify-center" aria-hidden="true">
                    <Check className="w-6 h-6" />
                  </div>
                  <span className="text-sm font-bold text-slate-700 truncate max-w-[200px]">{file.name}</span>
                  <span className="text-[10px] text-teal-600 font-bold uppercase">OCR Scan Complete</span>
                </div>
              ) : (
                <div className="flex flex-col items-center">
                  <Upload className="w-10 h-10 mb-3 text-slate-300 group-hover:scale-110 transition-transform" aria-hidden="true" />
                  <p className="text-sm font-black text-slate-600">면허증 사진 업로드</p>
                  <p className="text-[10px] text-slate-400 mt-1">이름/면허번호가 자동 추출됩니다.</p>
                </div>
              )}
            </div>

            <div className="bg-red-50 rounded-2xl p-4 border border-red-100" role="alert">
              <p className="text-[10px] text-red-600 font-black leading-relaxed flex gap-2">
                <AlertTriangle className="w-4 h-4 shrink-0" aria-hidden="true" />
                <span>주민등록번호 뒷자리는 <u className="decoration-red-300">포스트잇이나 손가락으로 가리고</u> 찍어주세요. PII 보호를 위해 가려지지 않은 정보는 즉시 파기됩니다.</span>
              </p>
            </div>
          </section>

          <section className={`space-y-4 transition-all duration-500 ${step === 'idle' ? 'opacity-30 pointer-events-none blur-sm' : 'opacity-100'}`} aria-labelledby="info-section">
            <h2 id="info-section" className="sr-only">정보 확인 및 가입</h2>
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label htmlFor="user-name" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">성명 (OCR)</label>
                  <input 
                    id="user-name"
                    type="text" 
                    value={name} 
                    onChange={e => setName(e.target.value)} 
                    placeholder="분석 대기"
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                  />
               </div>
               <div>
                  <label htmlFor="license-no" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">면허번호 (OCR)</label>
                  <input 
                    id="license-no"
                    type="text" 
                    value={licenseNo} 
                    onChange={e => setLicenseNo(e.target.value)} 
                    placeholder="분석 대기"
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                  />
               </div>
            </div>

            <div>
                <label htmlFor="set-password" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">비밀번호 설정</label>
                <div className="relative">
                    <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                        id="set-password"
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        placeholder="로그인에 사용할 비밀번호 입력"
                        className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                    />
                </div>
            </div>

            <div 
              className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-100 cursor-pointer focus-within:ring-2 focus-within:ring-slate-900 outline-none" 
              onClick={() => setAgreed(!agreed)}
              role="checkbox"
              aria-checked={agreed}
              tabIndex={0}
              onKeyDown={(e) => (e.key === ' ' || e.key === 'Enter') && setAgreed(!agreed)}
            >
               <div className={`w-5 h-5 rounded-md flex items-center justify-center transition-colors ${agreed ? 'bg-slate-900' : 'bg-white border border-slate-300'}`} aria-hidden="true">
                  {agreed && <Check className="w-3 h-3 text-white" />}
               </div>
               <p className="text-[11px] font-bold text-slate-600">
                 <a href="https://notion.so/..." target="_blank" className="underline text-teal-600 focus:outline-none focus:ring-1 focus:ring-teal-600" onClick={(e) => e.stopPropagation()}>이용약관 및 개인정보 처리방침</a>에 동의합니다.
               </p>
            </div>

            <button 
              disabled={!agreed || !file || isAnalyzing || !password}
              onClick={handleSubmitRequest}
              className={`w-full py-4 rounded-2xl font-black text-white transition-all shadow-xl active:scale-95 flex items-center justify-center gap-2 outline-none focus:ring-2 focus:ring-teal-500
                ${!agreed || !file || isAnalyzing || !password ? 'bg-slate-300 cursor-not-allowed' : 'bg-slate-900 hover:bg-black'}
              `}
              aria-live="polite"
            >
              {isAnalyzing ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" aria-hidden="true" />
                  <span>OCR 분석 중...</span>
                </>
              ) : (
                <>
                  <ShieldCheck className="w-5 h-5" aria-hidden="true" />
                  <span>인증 요청 및 가입</span>
                </>
              )}
            </button>
          </section>

          <div className="text-center">
             <button className="text-[10px] font-black text-slate-400 hover:text-slate-600 transition-colors py-2 focus:underline outline-none">
                인식이 안 되나요? 직접 입력하기
             </button>
          </div>
        </div>
      </div>

      <p className="mt-8 text-[11px] text-slate-400 font-bold uppercase tracking-widest flex items-center gap-2" aria-hidden="true">
        <Lock className="w-3 h-3" /> Secure Verification Powered by Human Middleware
      </p>
    </div>
  );
};

export default LicenseVerification;

