export type Language = 'ko' | 'en' | 'ja';

import React, { useState } from 'react';
import Header from './components/Header';
import LandingPage from './components/LandingPage';
import AuthPage from './components/AuthPage';
import LicenseVerification from './components/LicenseVerification';
import PatientProfile from './components/PatientProfile';
import DrugScanner from './components/DrugScanner';
import ClinicalDashboard from './components/ClinicalDashboard';
import SmartOutput from './components/SmartOutput';
import ClinicalAssistant from './components/ClinicalAssistant';
import AdminPanel from './components/AdminPanel';
import { Pharmacist, Patient, AnalysisResult, ViewMode, UserRole, UserStatus } from './types';

const MOCK_PATIENT: Patient = {
  id: 'p-001',
  name: '김필순',
  birthDate: '1947.05.20',
  age: 78,
  gender: 'F',
  conditions: ['고혈압', '관절염', '신장 질환(eGFR < 60)'],
  eGFR: 58,
  visitType: 'Home'
};

// Initial Mock Database
const INITIAL_USERS: Pharmacist[] = [
  {
    id: 'admin',
    name: '관리자',
    licenseNumber: '00000',
    isVerified: true,
    role: 'ADMIN',
    status: 'ACTIVE',
    requestDate: '2024-01-01',
    password: 'admin'
  },
  {
    id: 'testuser',
    name: '홍길동',
    licenseNumber: '12345',
    isVerified: true,
    role: 'USER',
    status: 'ACTIVE',
    requestDate: '2024-02-15',
    password: '1234'
  }
];

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.LANDING);
  const [pharmacist, setPharmacist] = useState<Pharmacist | null>(null);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);

  // Simulated Database State
  const [userDB, setUserDB] = useState<Pharmacist[]>(INITIAL_USERS);

  const handleGoToAuth = () => setViewMode(ViewMode.AUTH);

  const handleLogin = (id: string, password?: string) => {
    const user = userDB.find(u => u.id === id);

    if (!user) {
      alert("존재하지 않는 아이디입니다.");
      return;
    }

    if (user.password !== password) {
        alert("비밀번호가 일치하지 않습니다.");
        return;
    }

    if (user.status === 'REJECTED') {
      alert("가입이 거절된 계정입니다. 관리자에게 문의하세요.");
      return;
    }

    setPharmacist(user);
    setViewMode(ViewMode.DASHBOARD);
  };

  const handleSignupClick = () => {
    setViewMode(ViewMode.VERIFICATION);
  };

  // Function to check if ID is available (passed to LicenseVerification)
  const checkIdAvailability = (id: string): boolean => {
      return !userDB.some(u => u.id === id);
  };

  const handleVerificationSuccess = (newUser: Pharmacist) => {
    // Check duplicate license just in case
    const licenseExists = userDB.some(u => u.licenseNumber === newUser.licenseNumber);
    if (licenseExists) {
        alert("이미 가입된 면허번호입니다. 관리자에게 문의하세요.");
        return;
    }

    // Add to DB
    setUserDB(prev => [...prev, newUser]);
    setPharmacist(newUser);

    if (newUser.status === 'ACTIVE') {
        setViewMode(ViewMode.DASHBOARD);
    } else {
        alert("가입 요청이 완료되었습니다. 관리자 승인 후 로그인 가능합니다.");
        setViewMode(ViewMode.LANDING);
    }
  };

  const handleEnterDashboard = () => {
      if (pharmacist?.status === 'ACTIVE') {
          setViewMode(ViewMode.DASHBOARD);
      } else {
          alert("아직 가입 승인 대기 중입니다. 약사님의 수동 확인을 기다려주세요!");
      }
  };

  const handleLogout = () => {
    setPharmacist(null);
    setAnalysisResult(null);
    setViewMode(ViewMode.LANDING);
  };

  const toggleAdminPanel = () => {
    setViewMode(prev => prev === ViewMode.ADMIN_PANEL ? ViewMode.DASHBOARD : ViewMode.ADMIN_PANEL);
  };

  if (viewMode === ViewMode.LANDING) {
    return (
      <LandingPage 
        pharmacist={pharmacist}
        onLogin={handleGoToAuth} 
        onLogout={handleLogout}
        onDashboard={handleEnterDashboard} 
      />
    );
  }

  if (viewMode === ViewMode.AUTH) {
    return (
      <AuthPage 
        onLogin={handleLogin}
        onSignupClick={handleSignupClick}
        onBack={() => setViewMode(ViewMode.LANDING)}
      />
    );
  }

  if (viewMode === ViewMode.VERIFICATION) {
    return <LicenseVerification 
        onVerified={handleVerificationSuccess} 
        checkDuplicateId={checkIdAvailability}
    />;
  }

  if (viewMode === ViewMode.ADMIN_PANEL && pharmacist?.role === 'ADMIN') {
      return (
          <div className="min-h-screen flex flex-col">
              <Header 
                  pharmacistName={pharmacist.name} 
                  role={pharmacist.role}
                  onLogout={handleLogout} 
                  onToggleAdmin={toggleAdminPanel}
              />
              <AdminPanel onBack={() => setViewMode(ViewMode.DASHBOARD)} />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header 
        pharmacistName={pharmacist?.name || '약사'} 
        role={pharmacist?.role || 'USER'}
        onLogout={handleLogout} 
        onToggleAdmin={toggleAdminPanel}
      />

      <main className="flex-1 p-4 md:p-6 overflow-hidden h-[calc(100vh-64px)]">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
          <div className="lg:col-span-3 flex flex-col h-full overflow-hidden">
            <div className="flex-none">
              <PatientProfile patient={MOCK_PATIENT} />
            </div>
            <div className="mt-4 flex-1 flex flex-col overflow-hidden">
              <ClinicalAssistant 
                patient={MOCK_PATIENT}
                analysis={analysisResult}
              />
              <DrugScanner 
                  onAnalysisComplete={setAnalysisResult} 
                  patient={MOCK_PATIENT}
              />
            </div>
          </div>
          <div className="lg:col-span-5 h-full overflow-hidden">
             <ClinicalDashboard analysis={analysisResult} />
          </div>
          <div className="lg:col-span-4 h-full overflow-hidden">
             <SmartOutput analysis={analysisResult} />
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { requestLicenseApproval } from '../services/licenseService';
import { CheckCircle, Upload, ShieldCheck, Lock, Database, Loader2, AlertTriangle, Check, Key, User, XCircle } from 'lucide-react';
import { Pharmacist } from '../types';

interface LicenseVerificationProps {
  onVerified: (user: Pharmacist) => void;
  checkDuplicateId?: (id: string) => boolean;
}

const LicenseVerification: React.FC<LicenseVerificationProps> = ({ onVerified, checkDuplicateId }) => {
  const [name, setName] = useState('');
  const [birth, setBirth] = useState('');
  const [licenseNo, setLicenseNo] = useState('');

  // Auth Fields
  const [userId, setUserId] = useState('');
  const [isIdAvailable, setIsIdAvailable] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  const [password, setPassword] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');

  const [file, setFile] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [step, setStep] = useState<'idle' | 'ocr' | 'ready'>('idle');
  const [agreed, setAgreed] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      handleAutoScan(e.target.files[0]);
    }
  };

  const handleAutoScan = async (selectedFile: File) => {
    setIsAnalyzing(true);
    setStep('ocr');

    try {
      const tempBirth = birth || '800101';
      const res = await requestLicenseApproval(selectedFile, name || '김약사', tempBirth);

      if (!name) setName(res.extractedName || '');
      setLicenseNo(res.extractedLicenseNo || '');
      setStep('ready');
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleCheckDuplicate = () => {
      if (!userId || userId.length < 4) {
          alert("아이디는 4자 이상이어야 합니다.");
          return;
      }
      setIsIdAvailable('checking');
      setTimeout(() => {
          if (checkDuplicateId) {
              const available = checkDuplicateId(userId);
              setIsIdAvailable(available ? 'available' : 'taken');
          } else {
              setIsIdAvailable('available'); // Fallback logic
          }
      }, 500);
  };

  const handleIdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setUserId(e.target.value);
      setIsIdAvailable('idle');
  };

  const handleSubmitRequest = () => {
    if (!name || !licenseNo || !userId || !password || !agreed) return;
    if (isIdAvailable !== 'available') {
        alert("아이디 중복 확인을 해주세요.");
        return;
    }
    if (password !== passwordConfirm) {
        alert("비밀번호가 일치하지 않습니다.");
        return;
    }

    const isSystemAdmin = name.includes('관리자') || name.toLowerCase().includes('admin');

    const newUser: Pharmacist = {
      id: userId,
      name,
      licenseNumber: licenseNo,
      isVerified: isSystemAdmin,
      role: isSystemAdmin ? 'ADMIN' : 'USER',
      status: isSystemAdmin ? 'ACTIVE' : 'PENDING',
      requestDate: new Date().toISOString(),
      password: password
    };

    if (isSystemAdmin) {
      onVerified(newUser);
    } else {
      alert("승인 요청이 완료되었습니다! 약사님이 수동 확인 후 24시간 내에 활성화됩니다.");
      window.location.reload();
    }
  };

  const isPasswordMatch = password && passwordConfirm && password === passwordConfirm;
  const isPasswordMismatch = passwordConfirm && password !== passwordConfirm;

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4 font-sans" role="main">
      <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-200">
        <div className="bg-slate-900 p-10 text-white relative">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none overflow-hidden" aria-hidden="true">
             <Database className="w-64 h-64 -rotate-12 -ml-20 -mt-20" />
          </div>
          <div className="relative z-10 text-center">
            <h1 className="text-4xl font-black tracking-tighter mb-2">PharmGni</h1>
            <p className="text-teal-400 text-[10px] font-black uppercase tracking-[0.3em]">Pharmacist Network Only</p>
          </div>
        </div>

        <div className="p-8 space-y-6">
          <section className="space-y-4" aria-labelledby="upload-section">
            <h2 id="upload-section" className="sr-only">면허증 업로드</h2>
            <div className="relative border-2 border-dashed border-slate-200 rounded-3xl p-6 text-center hover:bg-slate-50 transition-all cursor-pointer group focus-within:ring-2 focus-within:ring-teal-500">
              <input 
                type="file" 
                onChange={handleFileChange} 
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                aria-label="약사 면허증 사진 업로드"
              />
              {file ? (
                <div className="flex flex-col items-center gap-2">
                  <div className="w-12 h-12 bg-teal-100 text-teal-600 rounded-full flex items-center justify-center" aria-hidden="true">
                    <Check className="w-6 h-6" />
                  </div>
                  <span className="text-sm font-bold text-slate-700 truncate max-w-[200px]">{file.name}</span>
                  <span className="text-[10px] text-teal-600 font-bold uppercase">OCR Scan Complete</span>
                </div>
              ) : (
                <div className="flex flex-col items-center">
                  <Upload className="w-10 h-10 mb-3 text-slate-300 group-hover:scale-110 transition-transform" aria-hidden="true" />
                  <p className="text-sm font-black text-slate-600">면허증 사진 업로드</p>
                  <p className="text-[10px] text-slate-400 mt-1">이름/면허번호가 자동 추출됩니다.</p>
                </div>
              )}
            </div>

            <div className="bg-red-50 rounded-2xl p-4 border border-red-100" role="alert">
              <p className="text-[10px] text-red-600 font-black leading-relaxed flex gap-2">
                <AlertTriangle className="w-4 h-4 shrink-0" aria-hidden="true" />
                <span>주민등록번호 뒷자리는 <u className="decoration-red-300">포스트잇이나 손가락으로 가리고</u> 찍어주세요. PII 보호를 위해 가려지지 않은 정보는 즉시 파기됩니다.</span>
              </p>
            </div>
          </section>

          <section className={`space-y-4 transition-all duration-500 ${step === 'idle' ? 'opacity-30 pointer-events-none blur-sm' : 'opacity-100'}`} aria-labelledby="info-section">
            <h2 id="info-section" className="sr-only">정보 확인 및 가입</h2>

            {/* ID & Duplicate Check */}
            <div>
                <label htmlFor="user-id" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">아이디 설정</label>
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                            id="user-id"
                            type="text" 
                            value={userId} 
                            onChange={handleIdChange} 
                            placeholder="사용할 아이디 입력"
                            className="w-full pl-9 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                        />
                    </div>
                    <button 
                        onClick={handleCheckDuplicate}
                        disabled={!userId || isIdAvailable === 'checking'}
                        className={`px-3 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${
                            isIdAvailable === 'available' ? 'bg-green-100 text-green-700' :
                            isIdAvailable === 'taken' ? 'bg-red-100 text-red-700' :
                            'bg-slate-900 text-white hover:bg-slate-700'
                        }`}
                    >
                        {isIdAvailable === 'checking' ? <Loader2 className="w-4 h-4 animate-spin"/> : '중복확인'}
                    </button>
                </div>
                {isIdAvailable === 'available' && <p className="text-[10px] text-green-600 font-bold mt-1 ml-1 flex items-center gap-1"><CheckCircle className="w-3 h-3"/> 사용 가능한 아이디입니다.</p>}
                {isIdAvailable === 'taken' && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 flex items-center gap-1"><XCircle className="w-3 h-3"/> 이미 사용 중인 아이디입니다.</p>}
            </div>

            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label htmlFor="user-name" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">성명 (OCR)</label>
                  <input 
                    id="user-name"
                    type="text" 
                    value={name} 
                    onChange={e => setName(e.target.value)} 
                    placeholder="분석 대기"
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                  />
               </div>
               <div>
                  <label htmlFor="license-no" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">면허번호 (OCR)</label>
                  <input 
                    id="license-no"
                    type="text" 
                    value={licenseNo} 
                    onChange={e => setLicenseNo(e.target.value)} 
                    placeholder="분석 대기"
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                  />
               </div>
            </div>

            <div className="space-y-3">
                <div>
                    <label htmlFor="set-password" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">비밀번호 설정</label>
                    <div className="relative">
                        <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                            id="set-password"
                            type="password" 
                            value={password} 
                            onChange={e => setPassword(e.target.value)} 
                            placeholder="비밀번호 입력"
                            className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                        />
                    </div>
                </div>
                <div>
                    <label htmlFor="confirm-password" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">비밀번호 확인</label>
                    <div className="relative">
                        <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                            id="confirm-password"
                            type="password" 
                            value={passwordConfirm} 
                            onChange={e => setPasswordConfirm(e.target.value)} 
                            placeholder="비밀번호 재입력"
                            className={`w-full pl-10 pr-4 py-3 bg-slate-50 border rounded-xl text-sm font-bold focus:ring-2 outline-none transition-all ${
                                isPasswordMismatch ? 'border-red-300 focus:ring-red-200' : 'border-slate-200 focus:ring-slate-900'
                            }`} 
                        />
                         {isPasswordMatch && <CheckCircle className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-green-500" />}
                    </div>
                     {isPasswordMismatch && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1">비밀번호가 일치하지 않습니다.</p>}
                </div>
            </div>

            <div 
              className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-100 cursor-pointer focus-within:ring-2 focus-within:ring-slate-900 outline-none" 
              onClick={() => setAgreed(!agreed)}
              role="checkbox"
              aria-checked={agreed}
              tabIndex={0}
