                        {isIdAvailable === 'available' && <p className="text-[10px] text-green-600 font-bold mt-1 ml-1 flex items-center gap-1"><CheckCircle className="w-3 h-3"/> 사용 가능한 아이디입니다.</p>}
                        {isIdAvailable === 'taken' && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 flex items-center gap-1"><XCircle className="w-3 h-3"/> 이미 사용 중인 아이디입니다.</p>}
