export default LicenseVerification;

import React, { useState } from 'react';
import { requestLicenseApproval } from '../services/licenseService';
import { CheckCircle, Upload, ShieldCheck, Lock, Database, Loader2, Key, User, XCircle, ArrowRight, FileCheck, Clock, Ban, ChevronRight, Camera, X, FileText, ExternalLink } from 'lucide-react';
import { Pharmacist, UserStatus } from '../types';
import { TERMS_OF_SERVICE_TEXT, PRIVACY_POLICY_TEXT } from '../utils/legalText';

interface LicenseVerificationProps {
  onVerified: (user: Pharmacist) => void;
  checkDuplicateId?: (id: string) => boolean;
}

type Step = 'info' | 'upload' | 'result';

// --- Component ---

const LicenseVerification: React.FC<LicenseVerificationProps> = ({ onVerified, checkDuplicateId }) => {
  const [step, setStep] = useState<Step>('info');

  // Form Fields
  const [name, setName] = useState('');
  const [licenseNo, setLicenseNo] = useState('');
  const [userId, setUserId] = useState('');
  const [password, setPassword] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');

  // Agreement States
  const [agreedTerms, setAgreedTerms] = useState(false);
  const [agreedPrivacy, setAgreedPrivacy] = useState(false);
  const [viewingDoc, setViewingDoc] = useState<'terms' | 'privacy' | null>(null);

  // Validation States
  const [isIdAvailable, setIsIdAvailable] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  // Upload & Analysis States
  const [file, setFile] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [ocrScore, setOcrScore] = useState(0);

  // Final Result State
  const [finalUser, setFinalUser] = useState<Pharmacist | null>(null);

  // --- Step 1: Info Input Handlers ---

  const handleCheckDuplicate = () => {
      if (!userId || userId.length < 4) {
          alert("아이디는 4자 이상이어야 합니다.");
          return;
      }
      setIsIdAvailable('checking');
      setTimeout(() => {
          if (checkDuplicateId) {
              const available = checkDuplicateId(userId);
              setIsIdAvailable(available ? 'available' : 'taken');
          } else {
              setIsIdAvailable('available'); 
          }
      }, 500);
  };

  const handleIdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setUserId(e.target.value);
      setIsIdAvailable('idle');
  };

  const isPasswordMatch = password && passwordConfirm && password === passwordConfirm;
  const isPasswordMismatch = passwordConfirm && password !== passwordConfirm;

  // Updated Validation: Requires both checkboxes
  const isInfoStepValid = name && licenseNo && userId && isPasswordMatch && isIdAvailable === 'available' && agreedTerms && agreedPrivacy;

  const handleInfoSubmit = () => {
      if (isInfoStepValid) {
          setStep('upload');
      }
  };

  // --- Step 2: Upload Handlers ---

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0];
      setFile(selectedFile);
      await processVerification(selectedFile);
    }
  };

  const processVerification = async (selectedFile: File) => {
    setIsAnalyzing(true);

    try {
      // Use the name entered in Step 1 for verification
      const res = await requestLicenseApproval(selectedFile, name, '800101'); 
      setOcrScore(res.score);

      // Determine Status Logic
      const isSystemAdmin = name.includes('관리자') || name.toLowerCase().includes('admin');

      let status: UserStatus = 'PENDING';
      let isVerified = false;

      if (isSystemAdmin) {
          status = 'ACTIVE';
          isVerified = true;
      } else if (res.score >= 80) {
          status = 'PENDING'; 
      } else if (res.score < 30) {
          status = 'REJECTED';
      }

      const newUser: Pharmacist = {
        id: userId,
        name: name,
        licenseNumber: licenseNo,
        isVerified: isVerified,
        role: isSystemAdmin ? 'ADMIN' : 'USER',
        status: status,
        requestDate: new Date().toISOString(),
        password: password
      };

      setFinalUser(newUser);

      setTimeout(() => {
          setIsAnalyzing(false);
          setStep('result');
      }, 1500);

    } catch (e) {
      alert("분석 중 오류가 발생했습니다. 다시 시도해주세요.");
      setIsAnalyzing(false);
      setFile(null);
    }
  };

  // --- Step 3: Result Handlers ---

  const handleFinalize = () => {
      if (finalUser && finalUser.status !== 'REJECTED') {
          onVerified(finalUser);
      } else {
          window.location.reload();
      }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4 font-sans" role="main">
      <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-200">

        {/* Header */}
        <div className="bg-slate-900 p-8 text-white relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none" aria-hidden="true">
             <Database className="w-64 h-64 -rotate-12 -ml-20 -mt-20" />
          </div>
          <div className="relative z-10 text-center">
            <h1 className="text-3xl font-black tracking-tighter mb-2">PharmGni</h1>
            <div className="flex justify-center gap-2 mb-4">
