                      </pre>
                  </div>
                  <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end">
                      <button 
                          onClick={() => {
                              if (viewingDoc === 'terms') setAgreedTerms(true);
                              if (viewingDoc === 'privacy') setAgreedPrivacy(true);
                              setViewingDoc(null);
                          }}
