// Helper Component to render friendly legal text
const LegalDocumentViewer: React.FC<{ text: string }> = ({ text }) => {
    // Basic splitting logic to create cards for articles
    const sections = text.split('\n');

    return (
        <div className="space-y-4">
            {sections.map((line, idx) => {
                const trimmed = line.trim();
                if (!trimmed) return <div key={idx} className="h-2"></div>;

                // Title ([...])
                if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
                    return (
                        <div key={idx} className="text-center mb-8">
                            <h2 className="text-2xl font-black text-slate-900 tracking-tight">{trimmed.replace(/[\[\]]/g, '')}</h2>
                        </div>
                    );
                }

                // Articles (제 X 조)
                if (trimmed.match(/^제\s*\d+\s*조/)) {
                    return (
                        <div key={idx} className="mt-8 mb-4 flex items-center gap-3">
                            <div className="h-px bg-slate-300 flex-1"></div>
                            <h3 className="text-lg font-black text-slate-800 bg-slate-200 px-4 py-1.5 rounded-full shrink-0">
                                {trimmed}
                            </h3>
                            <div className="h-px bg-slate-300 flex-1"></div>
                        </div>
                    );
                }

                // Numbered Lists (1., 2.)
                if (trimmed.match(/^\d+\./)) {
                    return (
                        <div key={idx} className="pl-4 flex gap-3 text-sm text-slate-600 leading-relaxed font-medium bg-white p-3 rounded-lg border border-slate-100 shadow-sm ml-2">
                            <span className="font-black text-teal-600 shrink-0">{trimmed.split('.')[0]}.</span>
                            <span>{trimmed.substring(trimmed.indexOf('.') + 1).trim()}</span>
                        </div>
                    );
                }

                // Circled Numbers (①, ②)
                if (trimmed.match(/^[①-⑮]/)) {
                     return (
                        <div key={idx} className="mt-2 text-sm font-bold text-slate-800 leading-relaxed pl-2">
                            {trimmed}
                        </div>
                    );
                }

                // Bullet points
                if (trimmed.startsWith('-') || trimmed.startsWith('●')) {
                    return (
                        <div key={idx} className="pl-8 text-sm text-slate-500 leading-relaxed flex items-start gap-2">
                             <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-slate-400 shrink-0"></span>
                             <span>{trimmed.replace(/^[-●]\s*/, '')}</span>
                        </div>
                    );
                }

                // Normal Text
                return (
                    <p key={idx} className="text-sm text-slate-600 leading-relaxed">
                        {trimmed.split('**').map((part, i) => 
                            i % 2 === 1 ? <strong key={i} className="text-slate-900 font-bold bg-yellow-100 px-1 rounded">{part}</strong> : part
                        )}
                    </p>
                );
            })}
        </div>
    );
}

