                                className={`w-5 h-5 rounded-md flex items-center justify-center shrink-0 mt-0.5 transition-colors ${agreedPrivacy ? 'bg-white' : 'bg-white border border-slate-300'}`} 
                            >
                                {agreedPrivacy && <CheckCircle className="w-3.5 h-3.5 text-slate-900" />}
                            </div>
                            <div className="flex-1 flex justify-between items-center">
                                <span className={`text-[11px] font-bold ${agreedPrivacy ? 'text-white' : 'text-slate-600'}`}>
                                    개인정보 처리방침 동의 (필수)
                                </span>
                                <button 
                                    onClick={(e) => { e.stopPropagation(); openDocument('privacy'); }}
                                    className={`text-[10px] font-bold underline flex items-center gap-1 ${agreedPrivacy ? 'text-slate-300 hover:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                                >
                                    전문보기 <ExternalLink className="w-3 h-3"/>
                                </button>
                            </div>
                        </div>
                    </div>

                    <button 
                        disabled={!isInfoStepValid}
                        onClick={handleInfoSubmit}
                        className={`w-full py-4 rounded-2xl font-black text-white transition-all shadow-xl active:scale-95 flex items-center justify-center gap-2 outline-none focus:ring-2 focus:ring-teal-500
                            ${!isInfoStepValid ? 'bg-slate-300 cursor-not-allowed' : 'bg-slate-900 hover:bg-black'}
                        `}
                    >
                        다음: 면허증 인증 <ArrowRight className="w-5 h-5" />
                    </button>
                </div>
            )}

            {/* STEP 2: Upload */}
            {step === 'upload' && (
                <div className="space-y-6 animate-in slide-in-from-right fade-in duration-300 py-4">
                    <div className="text-center mb-6">
                        <div className="w-16 h-16 bg-teal-50 rounded-2xl mx-auto flex items-center justify-center mb-3">
                            <Camera className="w-8 h-8 text-teal-600" />
                        </div>
                        <h3 className="text-lg font-black text-slate-900">면허증 사진 업로드</h3>
                        <p className="text-xs text-slate-500 font-bold mt-1">입력하신 정보({name}, {licenseNo})와 일치해야 합니다.</p>
                    </div>

                    <div className={`relative border-2 border-dashed rounded-3xl p-8 text-center transition-all group focus-within:ring-2 focus-within:ring-teal-500 ${isAnalyzing ? 'bg-slate-50 border-slate-200' : 'border-slate-300 hover:bg-slate-50 hover:border-teal-400 cursor-pointer'}`}>
                        <input 
                            type="file" 
                            onChange={handleFileChange} 
                            disabled={isAnalyzing}
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed" 
                            aria-label="약사 면허증 사진 업로드 (필수)"
                        />
                        {isAnalyzing ? (
                            <div className="flex flex-col items-center py-4">
                                <Loader2 className="w-10 h-10 animate-spin text-teal-600 mb-4" />
                                <span className="text-sm font-black text-slate-800">OCR 검증 중입니다...</span>
                                <span className="text-xs text-slate-400 mt-2">잠시만 기다려주세요</span>
                            </div>
                        ) : (
                            <div className="flex flex-col items-center py-4">
                                <Upload className="w-10 h-10 mb-4 text-slate-300 group-hover:scale-110 group-hover:text-teal-500 transition-all" aria-hidden="true" />
                                <p className="text-sm font-black text-slate-700">여기를 클릭하여 사진 업로드</p>
                                <p className="text-[10px] text-slate-400 mt-2 font-bold bg-slate-100 px-2 py-1 rounded">필수 절차</p>
                            </div>
                        )}
                    </div>

                    <button 
                        onClick={() => setStep('info')} 
                        disabled={isAnalyzing}
                        className="w-full py-3 text-slate-400 text-xs font-bold hover:text-slate-600 disabled:opacity-50"
                    >
                        이전 단계로 돌아가기
                    </button>
                </div>
            )}

            {/* STEP 3: Result */}
            {step === 'result' && finalUser && (
                <div className="space-y-6 animate-in zoom-in fade-in duration-300 py-4 text-center">

                    {finalUser.status === 'ACTIVE' && (
                        <div className="flex flex-col items-center">
                            <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mb-4 animate-bounce">
                                <FileCheck className="w-10 h-10 text-green-600" />
                            </div>
                            <h3 className="text-2xl font-black text-slate-900 mb-2">가입 승인 완료</h3>
                            <p className="text-sm text-slate-500 font-bold mb-6">
                                면허 정보가 확인되었습니다.<br/>
                                즉시 서비스를 이용하실 수 있습니다.
                            </p>
                            <button onClick={handleFinalize} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black shadow-xl hover:bg-black transition-all active:scale-95">
                                PharmGni 시작하기
                            </button>
                        </div>
                    )}

                    {finalUser.status === 'PENDING' && (
                        <div className="flex flex-col items-center">
                            <div className="w-20 h-20 bg-amber-100 rounded-full flex items-center justify-center mb-4">
                                <Clock className="w-10 h-10 text-amber-600" />
                            </div>
                            <h3 className="text-2xl font-black text-slate-900 mb-2">승인 심사 대기</h3>
                            <p className="text-sm text-slate-500 font-bold mb-6">
                                가입 요청이 접수되었습니다.<br/>
                                관리자 수동 승인 후(약 24시간 소요) 이용 가능합니다.
                            </p>
                            <div className="w-full bg-slate-50 p-4 rounded-2xl border border-slate-100 mb-6 text-left">
                                <p className="text-[10px] text-slate-400 font-black uppercase mb-1">OCR Verification Score</p>
                                <div className="w-full bg-slate-200 h-2 rounded-full overflow-hidden">
                                    <div className="h-full bg-amber-500" style={{ width: `${ocrScore}%` }}></div>
                                </div>
                                <p className="text-right text-xs font-bold text-slate-600 mt-1">{ocrScore} / 100</p>
                            </div>
                            <button onClick={handleFinalize} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black shadow-xl hover:bg-black transition-all active:scale-95">
                                메인으로 돌아가기
                            </button>
                        </div>
                    )}

                    {finalUser.status === 'REJECTED' && (
                        <div className="flex flex-col items-center">
                            <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mb-4">
                                <Ban className="w-10 h-10 text-red-600" />
                            </div>
                            <h3 className="text-2xl font-black text-slate-900 mb-2">가입 승인 거절</h3>
                            <p className="text-sm text-slate-500 font-bold mb-6">
                                제출하신 면허증 정보가 일치하지 않습니다.<br/>
                                입력 정보를 확인 후 다시 시도해주세요.
                            </p>
                            <button onClick={handleFinalize} className="w-full py-4 bg-slate-200 text-slate-600 rounded-2xl font-black hover:bg-slate-300 transition-all">
                                처음으로 돌아가기
                            </button>
                        </div>
                    )}

                </div>
            )}
        </div>
      </div>

      <p className="mt-8 text-[11px] text-slate-400 font-bold uppercase tracking-widest flex items-center gap-2" aria-hidden="true">
        <Lock className="w-3 h-3" /> Secure Verification Powered by Human Middleware
      </p>

      {/* Document Viewer Modal */}
      {viewingDoc && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
              <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
                  <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50">
                      <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
                          <FileText className="w-5 h-5 text-teal-600"/>
                          {viewingDoc === 'terms' ? '이용약관' : '개인정보 처리방침'}
                      </h3>
                      <button 
                          onClick={() => setViewingDoc(null)}
                          className="p-2 hover:bg-slate-200 rounded-full transition-colors"
                      >
                          <X className="w-5 h-5 text-slate-500" />
                      </button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-8 bg-white">
                      <pre className="whitespace-pre-wrap font-sans text-sm text-slate-600 leading-relaxed">
                          {viewingDoc === 'terms' ? TERMS_OF_SERVICE_TEXT : PRIVACY_POLICY_TEXT}
                      </pre>
                  </div>
                  <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end">
                      <button 
                          onClick={() => {
                              if (viewingDoc === 'terms') {
                                setHasViewedTerms(true);
                                setAgreedTerms(true);
                              }
                              if (viewingDoc === 'privacy') {
                                setHasViewedPrivacy(true);
                                setAgreedPrivacy(true);
                              }
                              setViewingDoc(null);
                          }}
                          className="px-6 py-3 bg-slate-900 text-white rounded-xl font-bold text-sm hover:bg-black transition-colors"
                      >
                          확인 및 동의
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default LicenseVerification;

import React, { useState } from 'react';
import { requestLicenseApproval } from '../services/licenseService';
import { CheckCircle, Upload, ShieldCheck, Lock, Database, Loader2, Key, User, XCircle, ArrowRight, FileCheck, Clock, Ban, ChevronRight, Camera, X, FileText, ExternalLink, AlertTriangle } from 'lucide-react';
import { Pharmacist, UserStatus } from '../types';
import { TERMS_OF_SERVICE_TEXT, PRIVACY_POLICY_TEXT } from '../utils/legalText';

interface LicenseVerificationProps {
  onVerified: (user: Pharmacist) => void;
  checkDuplicateId?: (id: string) => boolean;
}

type Step = 'info' | 'upload' | 'result';

// --- Component ---

const LicenseVerification: React.FC<LicenseVerificationProps> = ({ onVerified, checkDuplicateId }) => {
  const [step, setStep] = useState<Step>('info');

  // Form Fields
  const [name, setName] = useState('');
  const [licenseNo, setLicenseNo] = useState('');
  const [userId, setUserId] = useState('');
  const [password, setPassword] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');

  // Agreement States
  const [agreedTerms, setAgreedTerms] = useState(false);
  const [agreedPrivacy, setAgreedPrivacy] = useState(false);

  // View States to enforce reading
  const [hasViewedTerms, setHasViewedTerms] = useState(false);
  const [hasViewedPrivacy, setHasViewedPrivacy] = useState(false);

  // UI States
  const [viewingDoc, setViewingDoc] = useState<'terms' | 'privacy' | null>(null);
  const [warning, setWarning] = useState<{show: boolean, type: 'terms' | 'privacy' | null}>({ show: false, type: null });

  // Validation States
  const [isIdAvailable, setIsIdAvailable] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  // Upload & Analysis States
  const [file, setFile] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [ocrScore, setOcrScore] = useState(0);

  // Final Result State
  const [finalUser, setFinalUser] = useState<Pharmacist | null>(null);

  // --- Step 1: Info Input Handlers ---

  const handleCheckDuplicate = () => {
      if (!userId || userId.length < 4) {
          alert("아이디는 4자 이상이어야 합니다.");
          return;
      }
      setIsIdAvailable('checking');
      setTimeout(() => {
          if (checkDuplicateId) {
              const available = checkDuplicateId(userId);
              setIsIdAvailable(available ? 'available' : 'taken');
          } else {
              setIsIdAvailable('available'); 
          }
      }, 500);
  };

  const handleIdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setUserId(e.target.value);
      setIsIdAvailable('idle');
  };

  const isPasswordMatch = password && passwordConfirm && password === passwordConfirm;
  const isPasswordMismatch = passwordConfirm && password !== passwordConfirm;

  // Updated Validation: Requires both checkboxes
  const isInfoStepValid = name && licenseNo && userId && isPasswordMatch && isIdAvailable === 'available' && agreedTerms && agreedPrivacy;

  const handleInfoSubmit = () => {
      if (isInfoStepValid) {
          setStep('upload');
      }
  };

  const handleTermsClick = () => {
      if (agreedTerms) {
          setAgreedTerms(false);
          return;
      }
      if (!hasViewedTerms) {
          setWarning({ show: true, type: 'terms' });
          return;
      }
      setAgreedTerms(true);
  };

  const handlePrivacyClick = () => {
      if (agreedPrivacy) {
          setAgreedPrivacy(false);
          return;
      }
      if (!hasViewedPrivacy) {
          setWarning({ show: true, type: 'privacy' });
          return;
      }
      setAgreedPrivacy(true);
  };

  const openDocument = (type: 'terms' | 'privacy') => {
      setViewingDoc(type);
      if (type === 'terms') setHasViewedTerms(true);
      if (type === 'privacy') setHasViewedPrivacy(true);
  };

  // --- Step 2: Upload Handlers ---

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0];
      setFile(selectedFile);
      await processVerification(selectedFile);
    }
  };

  const processVerification = async (selectedFile: File) => {
    setIsAnalyzing(true);

    try {
      // Use the name entered in Step 1 for verification
      const res = await requestLicenseApproval(selectedFile, name, '800101'); 
      setOcrScore(res.score);

      // Determine Status Logic
      const isSystemAdmin = name.includes('관리자') || name.toLowerCase().includes('admin');

      let status: UserStatus = 'PENDING';
      let isVerified = false;

      if (isSystemAdmin) {
          status = 'ACTIVE';
          isVerified = true;
      } else if (res.score >= 80) {
          status = 'PENDING'; 
      } else if (res.score < 30) {
          status = 'REJECTED';
      }

      const newUser: Pharmacist = {
        id: userId,
        name: name,
        licenseNumber: licenseNo,
        isVerified: isVerified,
        role: isSystemAdmin ? 'ADMIN' : 'USER',
        status: status,
        requestDate: new Date().toISOString(),
        password: password
      };

      setFinalUser(newUser);

      setTimeout(() => {
          setIsAnalyzing(false);
          setStep('result');
      }, 1500);

    } catch (e) {
      alert("분석 중 오류가 발생했습니다. 다시 시도해주세요.");
      setIsAnalyzing(false);
      setFile(null);
    }
  };

  // --- Step 3: Result Handlers ---

  const handleFinalize = () => {
      if (finalUser && finalUser.status !== 'REJECTED') {
          onVerified(finalUser);
      } else {
          window.location.reload();
      }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4 font-sans" role="main">
      <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-200">

        {/* Header */}
        <div className="bg-slate-900 p-8 text-white relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none" aria-hidden="true">
             <Database className="w-64 h-64 -rotate-12 -ml-20 -mt-20" />
          </div>
          <div className="relative z-10 text-center">
            <h1 className="text-3xl font-black tracking-tighter mb-2">PharmGni</h1>
            <div className="flex justify-center gap-2 mb-4">
                <div className={`h-1.5 w-8 rounded-full transition-all ${step === 'info' ? 'bg-teal-400' : 'bg-slate-700'}`}></div>
                <div className={`h-1.5 w-8 rounded-full transition-all ${step === 'upload' ? 'bg-teal-400' : 'bg-slate-700'}`}></div>
                <div className={`h-1.5 w-8 rounded-full transition-all ${step === 'result' ? 'bg-teal-400' : 'bg-slate-700'}`}></div>
            </div>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">
                {step === 'info' && "Step 1. 기본 정보 입력"}
                {step === 'upload' && "Step 2. 면허증 검증"}
                {step === 'result' && "Step 3. 최종 결과"}
            </p>
          </div>
        </div>

        <div className="p-8">
            {/* STEP 1: Info Input */}
            {step === 'info' && (
                <div className="space-y-6 animate-in slide-in-from-right fade-in duration-300">
                     {/* ID & Duplicate Check */}
                    <div>
                        <label htmlFor="user-id" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">아이디 설정 <span className="text-red-500">*</span></label>
                        <div className="flex gap-2">
                            <div className="relative flex-1">
                                <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                <input 
                                    id="user-id"
                                    type="text" 
                                    value={userId} 
                                    onChange={handleIdChange} 
                                    placeholder="사용할 아이디 입력"
                                    className="w-full pl-9 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                                />
                            </div>
                            <button 
                                onClick={handleCheckDuplicate}
                                disabled={!userId || isIdAvailable === 'checking'}
                                className={`px-3 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${
                                    isIdAvailable === 'available' ? 'bg-green-100 text-green-700' :
                                    isIdAvailable === 'taken' ? 'bg-red-100 text-red-700' :
                                    'bg-slate-900 text-white hover:bg-slate-700'
                                }`}
                            >
                                {isIdAvailable === 'checking' ? <Loader2 className="w-4 h-4 animate-spin"/> : '중복확인'}
                            </button>
                        </div>
                        {isIdAvailable === 'available' && <p className="text-[10px] text-green-600 font-bold mt-1 ml-1 flex items-center gap-1"><CheckCircle className="w-3 h-3"/> 사용 가능한 아이디입니다.</p>}
                        {isIdAvailable === 'taken' && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 flex items-center gap-1"><XCircle className="w-3 h-3"/> 이미 사용 중인 아이디입니다.</p>}
                    </div>

                    <div className="space-y-3">
                        <div>
                            <label htmlFor="set-password" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">비밀번호 설정 <span className="text-red-500">*</span></label>
                            <div className="relative">
                                <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                <input 
                                    id="set-password"
                                    type="password" 
                                    value={password} 
                                    onChange={e => setPassword(e.target.value)} 
                                    placeholder="비밀번호 입력"
                                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                                />
                            </div>
                        </div>
                        <div>
                            <label htmlFor="confirm-password" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">비밀번호 확인 <span className="text-red-500">*</span></label>
                            <div className="relative">
                                <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                <input 
                                    id="confirm-password"
                                    type="password" 
                                    value={passwordConfirm} 
                                    onChange={e => setPasswordConfirm(e.target.value)} 
                                    placeholder="비밀번호 재입력"
                                    className={`w-full pl-10 pr-4 py-3 bg-slate-50 border rounded-xl text-sm font-bold focus:ring-2 outline-none transition-all ${
                                        isPasswordMismatch ? 'border-red-300 focus:ring-red-200' : 'border-slate-200 focus:ring-slate-900'
                                    }`} 
                                />
                                {isPasswordMatch && <CheckCircle className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-green-500" />}
                            </div>
                            {isPasswordMismatch && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1">비밀번호가 일치하지 않습니다.</p>}
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label htmlFor="user-name" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">성명 <span className="text-red-500">*</span></label>
                            <input 
                                id="user-name"
                                type="text" 
                                value={name} 
                                onChange={e => setName(e.target.value)} 
                                placeholder="홍길동"
                                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                            />
                        </div>
                        <div>
                            <label htmlFor="license-no" className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block ml-1">면허번호 <span className="text-red-500">*</span></label>
                            <input 
                                id="license-no"
                                type="text" 
                                value={licenseNo} 
                                onChange={e => setLicenseNo(e.target.value)} 
                                placeholder="숫자만 입력"
                                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-slate-900 outline-none transition-all" 
                            />
                        </div>
                    </div>

                    {/* Terms & Conditions */}
                    <div className="space-y-3 pt-2">
                        {/* Terms of Service */}
                        <div 
                            className={`flex items-start gap-3 p-3 rounded-2xl border cursor-pointer transition-all ${agreedTerms ? 'bg-slate-900 border-slate-900' : 'bg-slate-50 border-slate-200'}`}
                            onClick={handleTermsClick}
                        >
                            <div 
                                className={`w-5 h-5 rounded-md flex items-center justify-center shrink-0 mt-0.5 transition-colors ${agreedTerms ? 'bg-white' : 'bg-white border border-slate-300'}`} 
                            >
                                {agreedTerms && <CheckCircle className="w-3.5 h-3.5 text-slate-900" />}
                            </div>
                            <div className="flex-1 flex justify-between items-center">
                                <span className={`text-[11px] font-bold ${agreedTerms ? 'text-white' : 'text-slate-600'}`}>
                                    이용약관 동의 (필수)
                                </span>
                                <button 
                                    onClick={(e) => { e.stopPropagation(); openDocument('terms'); }}
