                            <div className="flex-1 flex justify-between items-center">
                                <span className={`text-[11px] font-bold ${agreedPrivacy ? 'text-white' : 'text-slate-600'}`}>
                                    개인정보 처리방침 동의 (필수)
                                </span>
                                <button 
                                    onClick={(e) => { e.stopPropagation(); openDocument('privacy'); }}
                                    className={`text-[10px] font-bold underline flex items-center gap-1 ${agreedPrivacy ? 'text-slate-300 hover:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                                >
                                    전문보기 <ExternalLink className="w-3 h-3"/>
                                </button>
                            </div>
                        </div>
                    </div>

                    <button 
                        disabled={!isInfoStepValid}
                        onClick={handleInfoSubmit}
                        className={`w-full py-4 rounded-2xl font-black text-white transition-all shadow-xl active:scale-95 flex items-center justify-center gap-2 outline-none focus:ring-2 focus:ring-teal-500
                            ${!isInfoStepValid ? 'bg-slate-300 cursor-not-allowed' : 'bg-slate-900 hover:bg-black'}
                        `}
                    >
                        다음: 면허증 인증 <ArrowRight className="w-5 h-5" />
                    </button>
                </div>
            )}

            {/* STEP 2: Upload */}
            {step === 'upload' && (
                <div className="space-y-6 animate-in slide-in-from-right fade-in duration-300 py-4">
                    <div className="text-center mb-6">
                        <div className="w-16 h-16 bg-teal-50 rounded-2xl mx-auto flex items-center justify-center mb-3">
                            <Camera className="w-8 h-8 text-teal-600" />
                        </div>
                        <h3 className="text-lg font-black text-slate-900">면허증 사진 업로드</h3>
                        <p className="text-xs text-slate-500 font-bold mt-1">입력하신 정보({name}, {licenseNo})와 일치해야 합니다.</p>
                    </div>

                    <div className={`relative border-2 border-dashed rounded-3xl p-8 text-center transition-all group focus-within:ring-2 focus-within:ring-teal-500 ${isAnalyzing ? 'bg-slate-50 border-slate-200' : 'border-slate-300 hover:bg-slate-50 hover:border-teal-400 cursor-pointer'}`}>
                        <input 
                            type="file" 
                            onChange={handleFileChange} 
                            disabled={isAnalyzing}
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed" 
                            aria-label="약사 면허증 사진 업로드 (필수)"
                        />
                        {isAnalyzing ? (
                            <div className="flex flex-col items-center py-4">
                                <Loader2 className="w-10 h-10 animate-spin text-teal-600 mb-4" />
                                <span className="text-sm font-black text-slate-800">OCR 검증 중입니다...</span>
                                <span className="text-xs text-slate-400 mt-2">잠시만 기다려주세요</span>
