import SmartOutput from './components/SmartOutput';
import ClinicalAssistant from './components/ClinicalAssistant';
import AdminPanel from './components/AdminPanel';
import { Pharmacist, Patient, AnalysisResult, ViewMode, UserRole, UserStatus } from './types';

const DEFAULT_PATIENT: Patient = {
  id: 'p-001',
  name: '김필순',
  birthDate: '1947.05.20',
  age: 78,
  gender: 'F',
  conditions: ['고혈압', '관절염', '신장 질환(eGFR < 60)'],
  eGFR: 58,
  visitType: 'Home'
};

// Initial Mock Database
const INITIAL_USERS: Pharmacist[] = [
  {
    id: 'admin',
    name: '관리자',
    licenseNumber: '00000',
    isVerified: true,
    role: 'ADMIN',
    status: 'ACTIVE',
    requestDate: '2024-01-01',
    password: 'admin'
  },
  {
    id: 'testuser',
    name: '홍길동',
    licenseNumber: '12345',
    isVerified: true,
    role: 'USER',
    status: 'ACTIVE',
    requestDate: '2024-02-15',
    password: '1234'
  }
];

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.LANDING);
  const [pharmacist, setPharmacist] = useState<Pharmacist | null>(null);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);

  // Patient State (Editable)
  const [patient, setPatient] = useState<Patient>(DEFAULT_PATIENT);

  // Simulated Database State
  const [userDB, setUserDB] = useState<Pharmacist[]>(INITIAL_USERS);

  const handleGoToAuth = () => setViewMode(ViewMode.AUTH);

  const handleLogin = (id: string, password?: string) => {
    const user = userDB.find(u => u.id === id);

    if (!user) {
      alert("존재하지 않는 아이디입니다.");
      return;
    }

    if (user.password !== password) {
        alert("비밀번호가 일치하지 않습니다.");
        return;
    }

    if (user.status === 'REJECTED') {
      alert("가입이 거절된 계정입니다. 관리자에게 문의하세요.");
      return;
    }

    setPharmacist(user);
    setViewMode(ViewMode.DASHBOARD);
  };

  const handleSignupClick = () => {
    setViewMode(ViewMode.VERIFICATION);
  };

  // Function to check if ID is available (passed to LicenseVerification)
  const checkIdAvailability = (id: string): boolean => {
      return !userDB.some(u => u.id === id);
  };

  const handleVerificationSuccess = (newUser: Pharmacist) => {
    // Check duplicate license just in case
    const licenseExists = userDB.some(u => u.licenseNumber === newUser.licenseNumber);
    if (licenseExists) {
        alert("이미 가입된 면허번호입니다. 관리자에게 문의하세요.");
        return;
    }

    // Add to DB
    setUserDB(prev => [...prev, newUser]);
    setPharmacist(newUser);

    if (newUser.status === 'ACTIVE') {
        setViewMode(ViewMode.DASHBOARD);
    } else {
        alert("가입 요청이 완료되었습니다. 관리자 승인 후 로그인 가능합니다.");
        setViewMode(ViewMode.LANDING);
    }
  };

  const handleEnterDashboard = () => {
      if (pharmacist?.status === 'ACTIVE') {
          setViewMode(ViewMode.DASHBOARD);
      } else {
          alert("아직 가입 승인 대기 중입니다. 약사님의 수동 확인을 기다려주세요!");
      }
  };

  const handleLogout = () => {
    setPharmacist(null);
    setAnalysisResult(null);
    setViewMode(ViewMode.LANDING);
  };

  const toggleAdminPanel = () => {
    setViewMode(prev => prev === ViewMode.ADMIN_PANEL ? ViewMode.DASHBOARD : ViewMode.ADMIN_PANEL);
  };

  // Admin Actions
  const handleAdminApprove = (id: string) => {
      setUserDB(prev => prev.map(u => u.id === id ? { ...u, status: 'ACTIVE', isVerified: true } : u));
  };

  const handleAdminReject = (id: string) => {
      setUserDB(prev => prev.map(u => u.id === id ? { ...u, status: 'REJECTED', isVerified: false } : u));
  };

  if (viewMode === ViewMode.LANDING) {
    return (
      <LandingPage 
        pharmacist={pharmacist}
        onLogin={handleGoToAuth} 
        onLogout={handleLogout}
        onDashboard={handleEnterDashboard} 
      />
    );
  }

  if (viewMode === ViewMode.AUTH) {
    return (
      <AuthPage 
        onLogin={handleLogin}
        onSignupClick={handleSignupClick}
        onBack={() => setViewMode(ViewMode.LANDING)}
      />
    );
  }

  if (viewMode === ViewMode.VERIFICATION) {
    return <LicenseVerification 
        onVerified={handleVerificationSuccess} 
        checkDuplicateId={checkIdAvailability}
    />;
  }

  if (viewMode === ViewMode.ADMIN_PANEL && pharmacist?.role === 'ADMIN') {
      return (
          <div className="min-h-screen flex flex-col">
              <Header 
                  pharmacistName={pharmacist.name} 
                  role={pharmacist.role}
                  onLogout={handleLogout} 
                  onToggleAdmin={toggleAdminPanel}
              />
              <AdminPanel 
                  onBack={() => setViewMode(ViewMode.DASHBOARD)} 
                  users={userDB}
                  onApprove={handleAdminApprove}
                  onReject={handleAdminReject}
              />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header 
        pharmacistName={pharmacist?.name || '약사'} 
        role={pharmacist?.role || 'USER'}
        onLogout={handleLogout} 
        onToggleAdmin={toggleAdminPanel}
      />

      <main className="flex-1 p-4 md:p-6 overflow-hidden h-[calc(100vh-64px)]">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
          <div className="lg:col-span-3 flex flex-col h-full overflow-hidden">
            <div className="flex-none">
              <PatientProfile 
                patient={patient} 
                onUpdate={setPatient}
              />
            </div>
            <div className="mt-4 flex-1 flex flex-col overflow-hidden">
              <ClinicalAssistant 
                patient={patient}
                analysis={analysisResult}
              />
              <DrugScanner 
                  onAnalysisComplete={setAnalysisResult} 
                  patient={patient}
              />
            </div>
          </div>
          <div className="lg:col-span-5 h-full overflow-hidden">
             <ClinicalDashboard analysis={analysisResult} />
          </div>
          <div className="lg:col-span-4 h-full overflow-hidden">
             <SmartOutput analysis={analysisResult} />
