/**
 * 환자의 약물 목록과 호소 증상을 기반으로 DB를 검색합니다.
 */
export const searchWhoDb = (medications: string[], symptomQuery: string): WhoAdverseEntry[] => {
  // 약물명이나 증상 키워드가 포함된 DB 항목 추출
  return WHO_ADVERSE_DB.filter(entry => {
    const medMatch = medications.some(m => m.toLowerCase().includes(entry.drugName.toLowerCase()));
    // 증상 쿼리가 없으면 해당 약물의 모든 부작용 반환, 있으면 해당 증상만 필터링
    const symptomMatch = symptomQuery 
      ? entry.symptom.includes(symptomQuery) || symptomQuery.includes(entry.symptom)
      : true;

    return medMatch && symptomMatch;
  });
};

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel, Patient } from "../types";
import { checkLocalDUR } from "./durEngine";
import { searchWhoDb, WHO_ADVERSE_DB } from "./whoAdverseDb";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function cleanJsonString(text: string): string {
  let cleaned = text.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return cleaned;
}

/**
 * 시뮬레이션: 전송 전 로컬 환경에서 개인정보 마스킹
 * 실제 구현 시에는 NER(개체명 인식) 라이브러리를 통해 성함 등을 마스킹함.
 */
const simulateLocalMasking = async (base64: string) => {
    // 0.5초간 마스킹 프로세스 시뮬레이션
    return new Promise(resolve => setTimeout(() => resolve(base64), 500));
};

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    // [보완] 전송 전 로컬 마스킹 단계 거침 (Legal Compliance)
    const maskedBase64 = await simulateLocalMasking(base64Image);

    const modelId = "gemini-3-pro-preview"; 

    const prompt = `
      System Instruction:
      You are a Clinical Pharmacist AI (CDSS - Clinical Decision Support System).
      Your output is a 'Suggestion' for a licensed pharmacist.

      STRICT PRIVACY RULE:
      If you see any Names, Resident Registration Numbers (주민번호), or Phone Numbers in the image, 
      IGNORE them and DO NOT include them in your response. 
      Only extract medication names, ingredients, and dosages.

      Patient Clinical Data (Pseudonymized):
      ${patientContext}

      Task:
      1. OCR extraction: Extract all visible medication names.
      2. Condition Inference: Based ONLY on the identified medications, infer the probable medical conditions (Indications). e.g., Metformin -> Diabetes, Amlodipine -> Hypertension.
      3. Clinical analysis: Check for Beers Criteria, DUR, and drug-drug interactions.
      4. Provide clinical references or guidelines (e.g. 'AGS Beers Criteria 2023') in 'reference' field if available.

      Return ONLY raw JSON matching the schema.
      Language: Korean (한국어).
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: maskedBase64 } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                inferredConditions: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING },
                    description: "List of inferred medical conditions based on the drugs found (e.g., 고혈압, 당뇨)."
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN },
                            reference: { type: Type.STRING }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      let parsed: AnalysisResult;
      try {
        const cleanedText = cleanJsonString(response.text);
        parsed = JSON.parse(cleanedText) as AnalysisResult;
      } catch (e) {
        console.error("JSON Parsing Error:", e);
        throw new Error("Invalid JSON response from AI");
      }

      parsed.isVerifiedByPharmacist = false; // Initial state: Not verified

      const drugNames = parsed.medications.map(m => m.name || m.ingredient || "");
      const localAlerts = checkLocalDUR(drugNames);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => 
            (a.title && (a.title.includes(local.drugA) || a.title.includes(local.drugB)))
          );

          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB || '주의'} 이슈`,
                  reason: local.reason,
                  action: "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
                  drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
                  isVerifiedByLocalDB: true,
                  reference: local.reference
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: "분석 중 오류가 발생했습니다.",
    };
  }
};

export const askClinicalAi = async (
  query: string,
  patient: Patient,
  analysis: AnalysisResult | null
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // 1. 환자의 현재 약물 리스트 추출
    const currentMeds = analysis ? analysis.medications.map(m => m.name || m.ingredient).filter(Boolean) as string[] : [];

    // 2. WHO DB에서 관련 정보 검색 (Grounding)
    // 쿼리나 약물 리스트와 연관된 DB 항목을 찾아 컨텍스트에 주입합니다.
    const relevantWhoData = searchWhoDb(currentMeds, query);

    const whoContextData = relevantWhoData.length > 0 
        ? JSON.stringify(relevantWhoData, null, 2)
        : "No direct match in Local WHO DB. Use general pharmacological knowledge based on WHO criteria.";

    // 3. Prompt Engineering
    const clinicalContext = `
      [Clinical Context - No Personal ID]
      - Age: ${patient.age}, Gender: ${patient.gender}
      - Conditions: ${patient.conditions.join(", ")}
      - eGFR: ${patient.eGFR || 'Unknown'}
      - Medications: ${currentMeds.join(", ")}

      [WHO Adverse Reaction Database (Local Knowledge)]
      ${whoContextData}

      [Task Definition]
      You are a specialized expert in 'Adverse Drug Reaction (ADR) Causality Assessment'.
      The user is asking about a symptom. You must evaluate if any of the patient's medications could be the cause based on the WHO-UMC Causality Categories (Certain, Probable, Possible, Unlikely).

      [Output Requirements]
      1. If the user reports a symptom (e.g., dizziness, edema, pain), you MUST output the analysis in a MARKDOWN TABLE format exactly as below:

      | 호소 증상 | 의심되는 원인약물 | 인과정도 (WHO Criteria) | 근거 및 평가 (Mechanism) |
      |---|---|---|---|
      | (Symptom) | (Drug Name) | (Certain/Probable/Possible/Unlikely) | (Explain mechanism & WHO criteria logic) |

      2. If multiple drugs are suspected, list them in separate rows.
      3. If no specific drug is suspected but the symptom is concerning, state that in the table with 'Unknown' drug.
      4. After the table, provide a brief clinical recommendation in Korean.
      5. If a 'reference' URL is available in the WHO DB entry, please include it at the bottom of the response labeled as '[Reference]'.
      6. Use the provided [WHO Adverse Reaction Database] as the primary source of truth. If the drug is in the DB, use that data. If not, infer based on general medical knowledge.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: clinicalContext },
        { text: query }
      ],
      config: {
        systemInstruction: "You are a BCGP Assistant. Use only Korean for the final explanation, but keep WHO Criteria terms (Certain, Probable etc) in English/Korean mix for clarity. Never ask for Personal IDs.",
        temperature: 0.4, // 낮춤 (사실 기반 답변 유도)
      }
    });

    return response.text || "답변을 생성하지 못했습니다.";
  } catch (error) {
    return "상담 중 오류가 발생했습니다.";
  }
};

import React, { useState } from 'react';
import { BrainCircuit, Send, Loader2, ShieldCheck, HelpCircle } from 'lucide-react';
import { askClinicalAi } from '../services/geminiService';
import { Patient, AnalysisResult } from '../types';

interface ClinicalAssistantProps {
  patient: Patient;
  analysis: AnalysisResult | null;
}

const ClinicalAssistant: React.FC<ClinicalAssistantProps> = ({ patient, analysis }) => {
  const [query, setQuery] = useState('');
  const [history, setHistory] = useState<{ role: 'user' | 'ai'; text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSend = async () => {
    if (!query.trim() || isLoading) return;

    const userMsg = query.trim();
    setQuery('');
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const response = await askClinicalAi(userMsg, patient, analysis);
      setHistory(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setHistory(prev => [...prev, { role: 'ai', text: "오류가 발생했습니다." }]);
    } finally {
      setIsLoading(false);
    }
  };

  // Helper function to render text with clickable links
  const renderMessageWithLinks = (text: string) => {
    // Regex to match URLs (http or https)
    const urlRegex = /(https?:\/\/[^\s]+)/g;
    const parts = text.split(urlRegex);

    return parts.map((part, index) => {
      if (part.match(urlRegex)) {
        return (
          <a 
            key={index} 
            href={part} 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-blue-600 hover:underline break-all"
            onClick={(e) => e.stopPropagation()}
          >
            {part}
          </a>
        );
      }
      return part;
    });
  };

  return (
    <section className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col mb-4 max-h-[400px]" aria-labelledby="assistant-title">
      <div className="p-3 bg-indigo-50 border-b border-indigo-100 flex items-center justify-between">
        <h3 id="assistant-title" className="text-sm font-bold text-indigo-900 flex items-center gap-2">
          <BrainCircuit className="w-4 h-4" aria-hidden="true" />
          임상 AI 어시스턴트
        </h3>
        <div className="flex items-center gap-1.5 px-2 py-0.5 bg-white rounded-full border border-indigo-200">
          <ShieldCheck className="w-3 h-3 text-indigo-600" aria-hidden="true" />
          <span className="text-[10px] font-bold text-indigo-700">개인정보 비식별화됨</span>
        </div>
      </div>

      <div 
        className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/30 hide-scrollbar min-h-[150px]" 
        aria-live="polite"
      >
        {history.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full opacity-40 text-center py-4">
             <HelpCircle className="w-8 h-8 mb-2" aria-hidden="true" />
             <p className="text-xs font-medium">환자의 임상 상태나 약물에 대해<br/>무엇이든 물어보세요.</p>
          </div>
        ) : (
          history.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div 
                className={`max-w-[90%] p-3 rounded-2xl text-xs sm:text-sm ${
                  msg.role === 'user' 
                  ? 'bg-indigo-600 text-white rounded-tr-none font-sans' 
                  : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none shadow-sm font-mono whitespace-pre-wrap leading-relaxed'
                }`}
                aria-label={msg.role === 'user' ? "사용자 메시지" : "AI 답변"}
              >
                {/* AI 답변일 경우 표 형식을 위해 font-mono 및 pre-wrap 적용, URL 렌더링 */}
                {renderMessageWithLinks(msg.text)}
              </div>
            </div>
          ))
        )}
        {isLoading && (
          <div className="flex justify-start">
             <div className="bg-white border border-slate-200 p-3 rounded-2xl rounded-tl-none shadow-sm" aria-label="답변 생성 중">
                <Loader2 className="w-4 h-4 text-indigo-600 animate-spin" aria-hidden="true" />
             </div>
          </div>
        )}
      </div>

      <div className="p-2 border-t border-slate-100 bg-white">
        <div className="relative flex items-center">
          <input 
            type="text" 
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="예: 어지러움 증상이 있는데 약 때문일까?"
            className="w-full pl-3 pr-10 py-2.5 bg-slate-100 border-none rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:outline-none transition-all"
            aria-label="임상 질문 입력"
          />
          <button 
            onClick={handleSend}
            disabled={!query.trim() || isLoading}
            className="absolute right-1.5 p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-md transition-colors disabled:opacity-30 focus:ring-2 focus:ring-indigo-500 outline-none"
            aria-label="질문 보내기"
          >
            <Send className="w-4 h-4" aria-hidden="true" />
          </button>
        </div>
      </div>
    </section>
  );
};

