  // Map to store feedback state for each alert by index (or unique ID if available)
  const [feedbackMap, setFeedbackMap] = useState<Record<string, FeedbackState>>({});

  React.useEffect(() => {
    setAnalysis(initialAnalysis);
    setExpandedIndex(null);
    setSearchTerm('');
    setFeedbackMap({});
  }, [initialAnalysis]);

  const handleVerify = () => {
    if (analysis) {
        setAnalysis({ ...analysis, isVerifiedByPharmacist: true });
    }
  };

  const toggleAlert = (idx: number) => {
    setExpandedIndex(expandedIndex === idx ? null : idx);
  };

  const initFeedback = (key: string, rating: FeedbackRating) => {
    setFeedbackMap(prev => ({
      ...prev,
      [key]: { isRateMode: true, rating, comment: '', submitted: false }
    }));
  };

  const updateFeedbackComment = (key: string, comment: string) => {
    setFeedbackMap(prev => ({
      ...prev,
      [key]: { ...prev[key], comment }
    }));
  };

  const sendFeedback = async (key: string, targetTitle: string, category: 'ALERT' | 'OVERALL_ANALYSIS') => {
    const state = feedbackMap[key];
    if (!state || !state.rating) return;

    await submitFeedback({
      targetId: targetTitle,
      category: category,
      rating: state.rating,
      comment: state.comment,
      timestamp: new Date().toISOString()
    });

    setFeedbackMap(prev => ({
      ...prev,
      [key]: { ...prev[key], submitted: true, isRateMode: false }
    }));
  };

  const FeedbackControl = ({ idKey, targetTitle, category }: { idKey: string, targetTitle: string, category: 'ALERT' | 'OVERALL_ANALYSIS' }) => {
    const state = feedbackMap[idKey] || { isRateMode: false, rating: null, submitted: false };

    if (state.submitted) {
      return (
        <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold bg-slate-50 px-2 py-1 rounded border border-slate-100 animate-in fade-in">
          <CheckCircle className="w-3 h-3 text-teal-500" />
          피드백이 반영되었습니다.
        </div>
      );
    }

    if (state.isRateMode) {
      return (
        <div className="flex flex-col gap-2 bg-slate-50 p-3 rounded-lg border border-slate-200 animate-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between">
             <span className="text-xs font-bold text-slate-600">이 분석이 도움이 되었나요?</span>
             <div className="flex gap-2">
                <button 
                  onClick={() => initFeedback(idKey, 'POSITIVE')} 
                  className={`p-1.5 rounded hover:bg-white transition-colors ${state.rating === 'POSITIVE' ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400'}`}
                >
                  <ThumbsUp className="w-4 h-4" />
                </button>
                <button 
                  onClick={() => initFeedback(idKey, 'NEGATIVE')}
                  className={`p-1.5 rounded hover:bg-white transition-colors ${state.rating === 'NEGATIVE' ? 'text-red-500 bg-white shadow-sm' : 'text-slate-400'}`}
                >
                  <ThumbsDown className="w-4 h-4" />
                </button>
             </div>
          </div>
          <input 
            type="text" 
            placeholder="추가 의견을 남겨주세요 (선택사항)"
            value={state.comment}
            onChange={(e) => updateFeedbackComment(idKey, e.target.value)}
            className="w-full text-xs p-2 rounded border border-slate-200 focus:outline-none focus:border-teal-400"
            onKeyDown={(e) => e.key === 'Enter' && sendFeedback(idKey, targetTitle, category)}
          />
          <div className="flex justify-end gap-2">
             <button 
                onClick={() => setFeedbackMap(prev => ({ ...prev, [idKey]: { ...prev[idKey], isRateMode: false } }))}
                className="text-[10px] text-slate-400 hover:text-slate-600 px-2 py-1"
             >
               취소
             </button>
             <button 
                onClick={() => sendFeedback(idKey, targetTitle, category)}
                className="text-[10px] bg-slate-800 text-white px-3 py-1.5 rounded font-bold hover:bg-black transition-colors"
             >
               피드백 보내기
             </button>
          </div>
        </div>
      );
    }

    return (
      <div className="flex items-center gap-1">
         <button 
            onClick={(e) => { e.stopPropagation(); initFeedback(idKey, 'POSITIVE'); }}
            className="p-1.5 text-slate-300 hover:text-teal-600 hover:bg-teal-50 rounded transition-all"
            title="유용함"
         >
            <ThumbsUp className="w-3.5 h-3.5" />
         </button>
         <button 
            onClick={(e) => { e.stopPropagation(); initFeedback(idKey, 'NEGATIVE'); }}
            className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded transition-all"
            title="부정확함"
         >
            <ThumbsDown className="w-3.5 h-3.5" />
         </button>
      </div>
    );
  };

  if (!analysis) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-white rounded-xl border border-slate-200 text-slate-400 p-10 text-center" role="status">
        <ShieldAlert className="w-16 h-16 mb-4 text-slate-200" aria-hidden="true" />
        <h3 className="text-lg font-bold text-slate-300">대기 중</h3>
        <p className="text-sm">좌측 패널에서 약물 사진을 스캔해주세요.</p>
      </div>
    );
  }

  // Filter alerts based on search term
  const filteredAlerts = analysis.alerts.filter(alert => {
    const term = searchTerm.toLowerCase();
    return (
        alert.title.toLowerCase().includes(term) ||
        alert.reason.toLowerCase().includes(term) ||
        alert.drugsInvolved.some(drug => drug.toLowerCase().includes(term))
    );
  });

  return (
    <article className="h-full bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden relative" aria-labelledby="dashboard-title">
      <div 
        className={`px-5 py-2 flex items-center justify-between transition-colors ${analysis.isVerifiedByPharmacist ? 'bg-green-600 text-white' : 'bg-amber-500 text-white'}`}
        role="status"
      >
         <div className="flex items-center gap-2 text-xs font-black uppercase tracking-tight">
            {analysis.isVerifiedByPharmacist ? (
                <><ShieldCheck className="w-4 h-4" aria-hidden="true" /> 약사 최종 검토 완료 (CDSS Verified)</>
            ) : (
                <><Info className="w-4 h-4" aria-hidden="true" /> 약사 검토 대기 중 (AI Suggestion Only)</>
            )}
         </div>
         {!analysis.isVerifiedByPharmacist && (
            <button 
                onClick={handleVerify}
                className="bg-white text-amber-600 px-3 py-1 rounded-md text-[10px] font-black hover:bg-slate-50 transition-all shadow-sm focus:ring-2 focus:ring-white outline-none"
                aria-label="모든 분석 결과 승인"
            >
                전체 결과 승인
            </button>
         )}
      </div>

      <div className="p-5 border-b border-slate-100 bg-slate-50/50 flex items-start justify-between">
        <div className="max-w-[70%]">
          <h2 id="dashboard-title" className="text-lg font-bold text-slate-900 flex items-center gap-2">
            임상 분석 리포트
            <span className="text-[10px] font-bold bg-teal-100 text-teal-700 px-2 py-0.5 rounded-full uppercase" aria-label="AI 모델: Gemini 3.0 Pro">Gemini 3.0 Pro</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1 leading-snug mb-2">{analysis.summary}</p>
          {/* Overall Analysis Feedback */}
          <div className="flex items-center gap-2 mt-2">
            <span className="text-[10px] font-bold text-slate-400">분석 결과 평가:</span>
            <FeedbackControl idKey="overall" targetTitle="Overall Clinical Analysis" category="OVERALL_ANALYSIS" />
          </div>
        </div>
        <div className="flex flex-col items-end min-w-fit ml-4" aria-hidden="true">
            <div className="flex items-center gap-1.5 text-[10px] font-black text-teal-600 bg-white border border-teal-200 px-2 py-1 rounded-md shadow-sm">
                <Database className="w-3 h-3" />
                DUR DB 연동
            </div>
            <span className="text-[9px] text-slate-400 mt-1">v2.0 Pseudonymized</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-6 hide-scrollbar">
        {analysis.alerts.length > 0 && (
            <section className="space-y-3" aria-labelledby="alerts-heading">
                <div className="flex items-center justify-between mb-3">
                    <h3 id="alerts-heading" className="text-xs font-bold text-slate-400 uppercase flex items-center gap-2">
                        <Search className="w-3 h-3" aria-hidden="true" /> AI 제안 위험 요소
                    </h3>
                    <div className="relative group w-full max-w-[200px]">
                        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" />
                        <input 
                            type="text" 
                            placeholder="약물명 검색..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-8 pr-8 py-1.5 bg-slate-100 border-none rounded-lg text-xs font-bold focus:ring-2 focus:ring-slate-900 focus:outline-none transition-all placeholder:text-slate-400"
                            aria-label="위험 요소 검색"
                        />
                        {searchTerm && (
                            <button 
                                onClick={() => setSearchTerm('')}
                                className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 text-slate-400 hover:text-slate-600 rounded-full"
                                aria-label="검색어 지우기"
                            >
                                <X className="w-3 h-3" />
                            </button>
                        )}
                    </div>
                </div>

                <div role="list" className="space-y-3">
                    {filteredAlerts.length > 0 ? (
                        filteredAlerts.map((alert, idx) => {
                        const isExpanded = expandedIndex === idx;
                        const alertIdKey = `alert-${idx}`;

                        return (
                        <div 
                            key={idx} 
                            role="listitem"
                            className={`rounded-xl border-l-4 shadow-sm transition-all relative overflow-hidden cursor-pointer group focus-within:ring-2 focus-within:ring-teal-500 focus-within:ring-offset-2 ${
                                alert.level === AlertLevel.RED 
                                ? 'bg-red-50 border-red-500 hover:shadow-red-100' 
                                : alert.level === AlertLevel.YELLOW 
                                    ? 'bg-amber-50 border-amber-400 hover:shadow-amber-100'
                                    : 'bg-green-50 border-green-500 hover:shadow-green-100'
                            }`}
                            onClick={() => toggleAlert(idx)}
                            onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && toggleAlert(idx)}
                            tabIndex={0}
                            aria-expanded={isExpanded}
                        >
                            <div className="p-4 flex items-start justify-between">
                                 <div className="flex items-center gap-3">
                                    <div className={`p-2 rounded-full ${
                                        alert.level === AlertLevel.RED ? 'bg-red-100' : 
                                        alert.level === AlertLevel.YELLOW ? 'bg-amber-100' : 'bg-green-100'
                                    }`}>
                                        {alert.level === AlertLevel.RED && <AlertTriangle className="w-5 h-5 text-red-600" aria-hidden="true" />}
                                        {alert.level === AlertLevel.YELLOW && <Info className="w-5 h-5 text-amber-600" aria-hidden="true" />}
                                        {alert.level === AlertLevel.GREEN && <CheckCircle className="w-5 h-5 text-green-600" aria-hidden="true" />}
                                    </div>
                                    <div>
                                        <h4 className={`font-black tracking-tight text-sm ${
                                            alert.level === AlertLevel.RED ? 'text-red-900' : 
                                            alert.level === AlertLevel.YELLOW ? 'text-amber-900' : 'text-green-900'
                                        }`}>
                                            {alert.title}
                                        </h4>
                                        {!isExpanded && (
                                            <p className="text-xs text-slate-500 truncate max-w-[200px] mt-0.5">
                                                {alert.reason}
                                            </p>
                                        )}
                                    </div>
                                 </div>

                                 <div className="flex items-center gap-2">
                                     {analysis.isVerifiedByPharmacist && (
                                        <CheckCircle className="w-4 h-4 text-green-600" aria-label="검토 완료됨" />
                                     )}
                                     {isExpanded ? (
                                         <ChevronUp className="w-5 h-5 text-slate-400" />
                                     ) : (
                                         <ChevronDown className="w-5 h-5 text-slate-400 group-hover:text-slate-600" />
                                     )}
                                 </div>
                            </div>

                            {isExpanded && (
                                <div 
                                    className="px-4 pb-4 animate-in slide-in-from-top-1 fade-in duration-200"
                                    onClick={(e) => e.stopPropagation()} // Prevent closing when interacting with content
                                    onKeyDown={(e) => e.stopPropagation()}
                                >
                                    <div className="pt-3 border-t border-black/5 space-y-4">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <p className="text-[10px] font-black uppercase opacity-50 mb-1">Severity & Level</p>
                                                <div className={`inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-bold ${
                                                    alert.level === AlertLevel.RED ? 'bg-red-100 text-red-800' :
                                                    alert.level === AlertLevel.YELLOW ? 'bg-amber-100 text-amber-800' :
                                                    'bg-green-100 text-green-800'
                                                }`}>
                                                    <Activity className="w-3.5 h-3.5" />
                                                    {alert.level} PRIORITY
                                                </div>
                                            </div>
                                            {alert.drugsInvolved && alert.drugsInvolved.length > 0 && (
                                                <div>
                                                    <p className="text-[10px] font-black uppercase opacity-50 mb-1">Related Drugs</p>
                                                    <div className="flex flex-wrap gap-1">
                                                        {alert.drugsInvolved.map((drug, i) => (
                                                            <span key={i} className="inline-flex items-center gap-1 px-2 py-0.5 bg-white border border-slate-200 rounded text-[10px] font-bold text-slate-600">
                                                                <Pill className="w-2.5 h-2.5" /> {drug}
                                                            </span>
                                                        ))}
                                                    </div>
                                                </div>
                                            )}
                                        </div>

                                        <div>
                                            <p className="text-[10px] font-black uppercase opacity-50 mb-1">Mechanism / Reason</p>
                                            <div className="bg-white/50 p-3 rounded-lg border border-black/5">
                                                <p className="text-sm text-slate-800 leading-relaxed font-medium">
                                                    {alert.reason}
                                                </p>
                                            </div>
                                        </div>

                                        <div>
                                            <p className="text-[10px] font-black uppercase opacity-50 mb-1">Clinical Recommendation</p>
                                            <div className={`text-sm font-black p-3 rounded-lg flex items-start gap-2 ${
                                                alert.level === AlertLevel.RED ? 'bg-red-100 text-red-900' : 
                                                alert.level === AlertLevel.YELLOW ? 'bg-amber-100 text-amber-900' : 
                                                'bg-green-100 text-green-900'
                                            }`} role="alert">
                                                <span className="shrink-0 bg-white/40 px-1.5 rounded text-[10px] mt-0.5">Action</span>
                                                <span>{alert.action}</span>
                                            </div>
                                        </div>

                                        {alert.reference && (
                                            <div>
                                                <p className="text-[10px] font-black uppercase opacity-50 mb-1">Reference / Citation</p>
                                                <a 
                                                    href={alert.reference.startsWith('http') ? alert.reference : `https://scholar.google.com/scholar?q=${encodeURIComponent(alert.reference)}`}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="flex items-center gap-2 p-3 bg-slate-50 border border-slate-100 rounded-lg hover:bg-slate-100 transition-colors group/ref"
                                                    aria-label={`Open reference: ${alert.reference}`}
                                                >
                                                    <ExternalLink className="w-4 h-4 text-slate-400 group-hover/ref:text-teal-600" />
                                                    <span className="text-xs font-medium text-slate-600 group-hover/ref:text-teal-700 truncate">{alert.reference}</span>
                                                </a>
                                            </div>
                                        )}

                                        {/* Feedback Section for specific alert */}
                                        <div className="border-t border-dashed border-slate-200 pt-3 flex items-center justify-between">
                                           <span className="text-[10px] text-slate-400 font-bold">AI 정확도 평가:</span>
                                           <FeedbackControl idKey={alertIdKey} targetTitle={alert.title} category="ALERT" />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )})
                    ) : (
                        <div className="py-8 text-center text-slate-400">
                            <p className="text-xs font-bold">검색 결과가 없습니다.</p>
                        </div>
                    )}
                </div>
            </section>
        )}

        <section className="mt-6" aria-labelledby="medications-heading">
            <h3 id="medications-heading" className="text-xs font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                <CheckCircle className="w-3 h-3 text-teal-500" aria-hidden="true" /> 인식된 약물 (가명화)
            </h3>
            <div className="grid grid-cols-1 gap-2" role="list">
                {analysis.medications.map((med, idx) => (
                    <div key={idx} role="listitem" className="p-3 bg-white border border-slate-100 rounded-xl flex items-center justify-between hover:border-teal-200 transition-colors shadow-sm">
                        <div className="flex items-center gap-3">
                            <div className="w-8 h-8 bg-slate-50 rounded-lg flex items-center justify-center text-lg" aria-hidden="true">💊</div>
                            <div>
                                <p className="font-bold text-slate-800 text-sm leading-none mb-1">{med.name}</p>
                                <p className="text-[10px] text-slate-500 font-medium">{med.ingredient}</p>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="inline-block px-2 py-1 bg-teal-50 text-teal-700 text-[10px] rounded-md font-black">
                                {med.frequency}
                            </span>
                        </div>
                    </div>
                ))}
            </div>
        </section>
      </div>

      <footer className="p-3 bg-slate-900 text-[9px] text-slate-500 text-center font-bold">
         AI 분석은 임상 보조 수단이며, 법적 책임은 최종 승인한 약사에게 있습니다. (의료법 제27조 준수)
      </footer>
    </article>
  );
};

export default ClinicalDashboard;

import React, { useState } from 'react';
import { BrainCircuit, Send, Loader2, ShieldCheck, HelpCircle, ThumbsUp, ThumbsDown, Check } from 'lucide-react';
import { askClinicalAi } from '../services/geminiService';
import { Patient, AnalysisResult, FeedbackRating } from '../types';
import { submitFeedback } from '../services/feedbackService';

interface ClinicalAssistantProps {
  patient: Patient;
  analysis: AnalysisResult | null;
}

interface ChatMessage {
    id: string;
    role: 'user' | 'ai';
    text: string;
    feedback?: FeedbackRating;
}

const ClinicalAssistant: React.FC<ClinicalAssistantProps> = ({ patient, analysis }) => {
  const [query, setQuery] = useState('');
  const [history, setHistory] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSend = async () => {
    if (!query.trim() || isLoading) return;

    const userMsgText = query.trim();
    const tempId = Date.now().toString();

    setQuery('');
    setHistory(prev => [...prev, { id: tempId, role: 'user', text: userMsgText }]);
    setIsLoading(true);

    try {
      const response = await askClinicalAi(userMsgText, patient, analysis);
      const aiMsgId = (Date.now() + 1).toString();
      setHistory(prev => [...prev, { id: aiMsgId, role: 'ai', text: response }]);
    } catch (e) {
      setHistory(prev => [...prev, { id: Date.now().toString(), role: 'ai', text: "오류가 발생했습니다." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleFeedback = async (msgId: string, rating: FeedbackRating) => {
    const msgIndex = history.findIndex(m => m.id === msgId);
    if (msgIndex === -1) return;

    // Update local state immediately
    const updatedHistory = [...history];
    updatedHistory[msgIndex].feedback = rating;
    setHistory(updatedHistory);

    // Submit to service
    await submitFeedback({
        targetId: msgId, // In real app, this would be a message UUID
        category: 'CHAT',
        rating: rating,
        comment: '', // Optional: Add comment modal later if needed
        timestamp: new Date().toISOString()
    });
  };

  // Helper function to render text with clickable links
  const renderMessageWithLinks = (text: string) => {
    // Regex to match URLs (http or https)
    const urlRegex = /(https?:\/\/[^\s]+)/g;
    const parts = text.split(urlRegex);

    return parts.map((part, index) => {
      if (part.match(urlRegex)) {
        return (
          <a 
            key={index} 
            href={part} 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-blue-600 hover:underline break-all"
            onClick={(e) => e.stopPropagation()}
          >
            {part}
          </a>
        );
      }
      return part;
    });
  };

  return (
    <section className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col mb-4 max-h-[400px]" aria-labelledby="assistant-title">
      <div className="p-3 bg-indigo-50 border-b border-indigo-100 flex items-center justify-between">
        <h3 id="assistant-title" className="text-sm font-bold text-indigo-900 flex items-center gap-2">
          <BrainCircuit className="w-4 h-4" aria-hidden="true" />
          임상 AI 어시스턴트
        </h3>
        <div className="flex items-center gap-1.5 px-2 py-0.5 bg-white rounded-full border border-indigo-200">
          <ShieldCheck className="w-3 h-3 text-indigo-600" aria-hidden="true" />
          <span className="text-[10px] font-bold text-indigo-700">개인정보 비식별화됨</span>
        </div>
      </div>

      <div 
        className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/30 hide-scrollbar min-h-[150px]" 
        aria-live="polite"
      >
        {history.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full opacity-40 text-center py-4">
             <HelpCircle className="w-8 h-8 mb-2" aria-hidden="true" />
             <p className="text-xs font-medium">환자의 임상 상태나 약물에 대해<br/>무엇이든 물어보세요.</p>
          </div>
        ) : (
          history.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div 
                className={`max-w-[90%] p-3 rounded-2xl text-xs sm:text-sm ${
                  msg.role === 'user' 
                  ? 'bg-indigo-600 text-white rounded-tr-none font-sans' 
                  : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none shadow-sm font-mono whitespace-pre-wrap leading-relaxed'
                }`}
                aria-label={msg.role === 'user' ? "사용자 메시지" : "AI 답변"}
              >
                {renderMessageWithLinks(msg.text)}
              </div>

              {/* Feedback Controls for AI messages */}
              {msg.role === 'ai' && (
                  <div className="flex items-center gap-2 mt-1 ml-1">
                      {msg.feedback ? (
                          <span className="text-[10px] text-indigo-400 font-bold flex items-center gap-1">
                             <Check className="w-3 h-3" /> Feedback sent
                          </span>
                      ) : (
                          <>
                            <button 
                                onClick={() => handleFeedback(msg.id, 'POSITIVE')}
                                className="p-1 text-slate-300 hover:text-teal-600 hover:bg-white rounded transition-colors"
                                title="유용함"
                            >
                                <ThumbsUp className="w-3 h-3" />
                            </button>
                            <button 
                                onClick={() => handleFeedback(msg.id, 'NEGATIVE')}
                                className="p-1 text-slate-300 hover:text-red-500 hover:bg-white rounded transition-colors"
                                title="부정확함"
                            >
                                <ThumbsDown className="w-3 h-3" />
                            </button>
                          </>
                      )}
                  </div>
              )}
            </div>
          ))
        )}
        {isLoading && (
          <div className="flex justify-start">
             <div className="bg-white border border-slate-200 p-3 rounded-2xl rounded-tl-none shadow-sm" aria-label="답변 생성 중">
                <Loader2 className="w-4 h-4 text-indigo-600 animate-spin" aria-hidden="true" />
             </div>
          </div>
        )}
      </div>

      <div className="p-2 border-t border-slate-100 bg-white">
        <div className="relative flex items-center">
          <input 
            type="text" 
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="예: 어지러움 증상이 있는데 약 때문일까?"
            className="w-full pl-3 pr-10 py-2.5 bg-slate-100 border-none rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:outline-none transition-all"
            aria-label="임상 질문 입력"
          />
          <button 
            onClick={handleSend}
            disabled={!query.trim() || isLoading}
            className="absolute right-1.5 p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-md transition-colors disabled:opacity-30 focus:ring-2 focus:ring-indigo-500 outline-none"
            aria-label="질문 보내기"
          >
            <Send className="w-4 h-4" aria-hidden="true" />
          </button>
        </div>
      </div>
    </section>
  );
};

export default ClinicalAssistant;

import React, { useState } from 'react';
import { AnalysisResult, AlertLevel, FeedbackRating } from '../types';
import { AlertTriangle, CheckCircle, Info, ShieldAlert, Database, Search, ShieldCheck, ChevronDown, ChevronUp, Activity, Pill, ExternalLink, X, ThumbsUp, ThumbsDown, MessageSquare } from 'lucide-react';
import { submitFeedback } from '../services/feedbackService';

interface ClinicalDashboardProps {
  analysis: AnalysisResult | null;
}

// Local state interface for feedback UI
interface FeedbackState {
  isRateMode: boolean;
  rating: FeedbackRating | null;
  comment: string;
  submitted: boolean;
}

const ClinicalDashboard: React.FC<ClinicalDashboardProps> = ({ analysis: initialAnalysis }) => {
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(initialAnalysis);
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Map to store feedback state for each alert by index (or unique ID if available)
  const [feedbackMap, setFeedbackMap] = useState<Record<string, FeedbackState>>({});

  React.useEffect(() => {
    setAnalysis(initialAnalysis);
    setExpandedIndex(null);
    setSearchTerm('');
    setFeedbackMap({});
  }, [initialAnalysis]);

  const handleVerify = () => {
    if (analysis) {
        setAnalysis({ ...analysis, isVerifiedByPharmacist: true });
    }
  };

  const toggleAlert = (idx: number) => {
    setExpandedIndex(expandedIndex === idx ? null : idx);
  };

  const initFeedback = (key: string, rating: FeedbackRating) => {
    setFeedbackMap(prev => ({
      ...prev,
      [key]: { isRateMode: true, rating, comment: '', submitted: false }
    }));
  };

  const updateFeedbackComment = (key: string, comment: string) => {
    setFeedbackMap(prev => ({
      ...prev,
      [key]: { ...prev[key], comment }
    }));
  };

  const sendFeedback = async (key: string, targetTitle: string, category: 'ALERT' | 'OVERALL_ANALYSIS') => {
    const state = feedbackMap[key];
    if (!state || !state.rating) return;

    await submitFeedback({
      targetId: targetTitle,
      category: category,
      rating: state.rating,
      comment: state.comment,
      timestamp: new Date().toISOString()
    });

    setFeedbackMap(prev => ({
      ...prev,
      [key]: { ...prev[key], submitted: true, isRateMode: false }
    }));
  };

  const FeedbackControl = ({ idKey, targetTitle, category }: { idKey: string, targetTitle: string, category: 'ALERT' | 'OVERALL_ANALYSIS' }) => {
    const state = feedbackMap[idKey] || { isRateMode: false, rating: null, submitted: false };

    if (state.submitted) {
      return (
        <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold bg-slate-50 px-2 py-1 rounded border border-slate-100 animate-in fade-in">
          <CheckCircle className="w-3 h-3 text-teal-500" />
          피드백이 반영되었습니다.
        </div>
      );
    }

    if (state.isRateMode) {
      return (
        <div className="flex flex-col gap-2 bg-slate-50 p-3 rounded-lg border border-slate-200 animate-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between">
             <span className="text-xs font-bold text-slate-600">이 분석이 도움이 되었나요?</span>
             <div className="flex gap-2">
                <button 
                  onClick={() => initFeedback(idKey, 'POSITIVE')} 
                  className={`p-1.5 rounded hover:bg-white transition-colors ${state.rating === 'POSITIVE' ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400'}`}
                >
                  <ThumbsUp className="w-4 h-4" />
                </button>
                <button 
                  onClick={() => initFeedback(idKey, 'NEGATIVE')}
                  className={`p-1.5 rounded hover:bg-white transition-colors ${state.rating === 'NEGATIVE' ? 'text-red-500 bg-white shadow-sm' : 'text-slate-400'}`}
                >
                  <ThumbsDown className="w-4 h-4" />
                </button>
             </div>
          </div>
          <input 
            type="text" 
            placeholder="추가 의견을 남겨주세요 (선택사항)"
            value={state.comment}
            onChange={(e) => updateFeedbackComment(idKey, e.target.value)}
            className="w-full text-xs p-2 rounded border border-slate-200 focus:outline-none focus:border-teal-400"
            onKeyDown={(e) => e.key === 'Enter' && sendFeedback(idKey, targetTitle, category)}
          />
          <div className="flex justify-end gap-2">
             <button 
                onClick={() => setFeedbackMap(prev => ({ ...prev, [idKey]: { ...prev[idKey], isRateMode: false } }))}
                className="text-[10px] text-slate-400 hover:text-slate-600 px-2 py-1"
             >
               취소
             </button>
             <button 
                onClick={() => sendFeedback(idKey, targetTitle, category)}
                className="text-[10px] bg-slate-800 text-white px-3 py-1.5 rounded font-bold hover:bg-black transition-colors"
             >
               피드백 보내기
             </button>
          </div>
        </div>
      );
    }

    return (
      <div className="flex items-center gap-1">
         <button 
            onClick={(e) => { e.stopPropagation(); initFeedback(idKey, 'POSITIVE'); }}
            className="p-1.5 text-slate-300 hover:text-teal-600 hover:bg-teal-50 rounded transition-all"
            title="유용함"
         >
            <ThumbsUp className="w-3.5 h-3.5" />
         </button>
         <button 
            onClick={(e) => { e.stopPropagation(); initFeedback(idKey, 'NEGATIVE'); }}
            className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded transition-all"
            title="부정확함"
         >
            <ThumbsDown className="w-3.5 h-3.5" />
         </button>
      </div>
    );
  };

  if (!analysis) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-white rounded-xl border border-slate-200 text-slate-400 p-10 text-center" role="status">
        <ShieldAlert className="w-16 h-16 mb-4 text-slate-200" aria-hidden="true" />
        <h3 className="text-lg font-bold text-slate-300">대기 중</h3>
        <p className="text-sm">좌측 패널에서 약물 사진을 스캔해주세요.</p>
      </div>
    );
  }

  // Filter alerts based on search term
  const filteredAlerts = analysis.alerts.filter(alert => {
    const term = searchTerm.toLowerCase();
    return (
        alert.title.toLowerCase().includes(term) ||
        alert.reason.toLowerCase().includes(term) ||
        alert.drugsInvolved.some(drug => drug.toLowerCase().includes(term))
    );
  });

  return (
    <article className="h-full bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden relative" aria-labelledby="dashboard-title">
      <div 
        className={`px-5 py-2 flex items-center justify-between transition-colors ${analysis.isVerifiedByPharmacist ? 'bg-green-600 text-white' : 'bg-amber-500 text-white'}`}
        role="status"
      >
         <div className="flex items-center gap-2 text-xs font-black uppercase tracking-tight">
            {analysis.isVerifiedByPharmacist ? (
                <><ShieldCheck className="w-4 h-4" aria-hidden="true" /> 약사 최종 검토 완료 (CDSS Verified)</>
            ) : (
                <><Info className="w-4 h-4" aria-hidden="true" /> 약사 검토 대기 중 (AI Suggestion Only)</>
            )}
         </div>
         {!analysis.isVerifiedByPharmacist && (
            <button 
                onClick={handleVerify}
                className="bg-white text-amber-600 px-3 py-1 rounded-md text-[10px] font-black hover:bg-slate-50 transition-all shadow-sm focus:ring-2 focus:ring-white outline-none"
                aria-label="모든 분석 결과 승인"
            >
                전체 결과 승인
            </button>
         )}
      </div>

      <div className="p-5 border-b border-slate-100 bg-slate-50/50 flex items-start justify-between">
        <div className="max-w-[70%]">
          <h2 id="dashboard-title" className="text-lg font-bold text-slate-900 flex items-center gap-2">
            임상 분석 리포트
            <span className="text-[10px] font-bold bg-teal-100 text-teal-700 px-2 py-0.5 rounded-full uppercase" aria-label="AI 모델: Gemini 3.0 Pro">Gemini 3.0 Pro</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1 leading-snug mb-2">{analysis.summary}</p>
          {/* Overall Analysis Feedback */}
          <div className="flex items-center gap-2 mt-2">
            <span className="text-[10px] font-bold text-slate-400">분석 결과 평가:</span>
            <FeedbackControl idKey="overall" targetTitle="Overall Clinical Analysis" category="OVERALL_ANALYSIS" />
          </div>
        </div>
        <div className="flex flex-col items-end min-w-fit ml-4" aria-hidden="true">
            <div className="flex items-center gap-1.5 text-[10px] font-black text-teal-600 bg-white border border-teal-200 px-2 py-1 rounded-md shadow-sm">
                <Database className="w-3 h-3" />
                DUR DB 연동
            </div>
            <span className="text-[9px] text-slate-400 mt-1">v2.0 Pseudonymized</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-6 hide-scrollbar">
        {analysis.alerts.length > 0 && (
            <section className="space-y-3" aria-labelledby="alerts-heading">
                <div className="flex items-center justify-between mb-3">
                    <h3 id="alerts-heading" className="text-xs font-bold text-slate-400 uppercase flex items-center gap-2">
                        <Search className="w-3 h-3" aria-hidden="true" /> AI 제안 위험 요소
                    </h3>
                    <div className="relative group w-full max-w-[200px]">
                        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" />
                        <input 
                            type="text" 
                            placeholder="약물명 검색..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-8 pr-8 py-1.5 bg-slate-100 border-none rounded-lg text-xs font-bold focus:ring-2 focus:ring-slate-900 focus:outline-none transition-all placeholder:text-slate-400"
                            aria-label="위험 요소 검색"
                        />
                        {searchTerm && (
                            <button 
                                onClick={() => setSearchTerm('')}
                                className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 text-slate-400 hover:text-slate-600 rounded-full"
                                aria-label="검색어 지우기"
                            >
                                <X className="w-3 h-3" />
                            </button>
                        )}
                    </div>
                </div>

                <div role="list" className="space-y-3">
                    {filteredAlerts.length > 0 ? (
                        filteredAlerts.map((alert, idx) => {
                        const isExpanded = expandedIndex === idx;
                        const alertIdKey = `alert-${idx}`;

                        return (
                        <div 
                            key={idx} 
                            role="listitem"
                            className={`rounded-xl border-l-4 shadow-sm transition-all relative overflow-hidden cursor-pointer group focus-within:ring-2 focus-within:ring-teal-500 focus-within:ring-offset-2 ${
                                alert.level === AlertLevel.RED 
                                ? 'bg-red-50 border-red-500 hover:shadow-red-100' 
                                : alert.level === AlertLevel.YELLOW 
                                    ? 'bg-amber-50 border-amber-400 hover:shadow-amber-100'
                                    : 'bg-green-50 border-green-500 hover:shadow-green-100'
                            }`}
                            onClick={() => toggleAlert(idx)}
                            onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && toggleAlert(idx)}
                            tabIndex={0}
                            aria-expanded={isExpanded}
                        >
                            <div className="p-4 flex items-start justify-between">
                                 <div className="flex items-center gap-3">
                                    <div className={`p-2 rounded-full ${
                                        alert.level === AlertLevel.RED ? 'bg-red-100' : 
                                        alert.level === AlertLevel.YELLOW ? 'bg-amber-100' : 'bg-green-100'
                                    }`}>
                                        {alert.level === AlertLevel.RED && <AlertTriangle className="w-5 h-5 text-red-600" aria-hidden="true" />}
                                        {alert.level === AlertLevel.YELLOW && <Info className="w-5 h-5 text-amber-600" aria-hidden="true" />}
                                        {alert.level === AlertLevel.GREEN && <CheckCircle className="w-5 h-5 text-green-600" aria-hidden="true" />}
                                    </div>
                                    <div>
                                        <h4 className={`font-black tracking-tight text-sm ${
                                            alert.level === AlertLevel.RED ? 'text-red-900' : 
                                            alert.level === AlertLevel.YELLOW ? 'text-amber-900' : 'text-green-900'
                                        }`}>
                                            {alert.title}
                                        </h4>
                                        {!isExpanded && (
                                            <p className="text-xs text-slate-500 truncate max-w-[200px] mt-0.5">
                                                {alert.reason}
                                            </p>
                                        )}
                                    </div>
                                 </div>

                                 <div className="flex items-center gap-2">
                                     {analysis.isVerifiedByPharmacist && (
                                        <CheckCircle className="w-4 h-4 text-green-600" aria-label="검토 완료됨" />
                                     )}
                                     {isExpanded ? (
                                         <ChevronUp className="w-5 h-5 text-slate-400" />
                                     ) : (
                                         <ChevronDown className="w-5 h-5 text-slate-400 group-hover:text-slate-600" />
                                     )}
                                 </div>
                            </div>

                            {isExpanded && (
                                <div 
                                    className="px-4 pb-4 animate-in slide-in-from-top-1 fade-in duration-200"
                                    onClick={(e) => e.stopPropagation()} // Prevent closing when interacting with content
                                    onKeyDown={(e) => e.stopPropagation()}
                                >
                                    <div className="pt-3 border-t border-black/5 space-y-4">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <p className="text-[10px] font-black uppercase opacity-50 mb-1">Severity & Level</p>
                                                <div className={`inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-bold ${
                                                    alert.level === AlertLevel.RED ? 'bg-red-100 text-red-800' :
                                                    alert.level === AlertLevel.YELLOW ? 'bg-amber-100 text-amber-800' :
                                                    'bg-green-100 text-green-800'
                                                }`}>
                                                    <Activity className="w-3.5 h-3.5" />
                                                    {alert.level} PRIORITY
                                                </div>
                                            </div>
                                            {alert.drugsInvolved && alert.drugsInvolved.length > 0 && (
                                                <div>
                                                    <p className="text-[10px] font-black uppercase opacity-50 mb-1">Related Drugs</p>
                                                    <div className="flex flex-wrap gap-1">
                                                        {alert.drugsInvolved.map((drug, i) => (
                                                            <span key={i} className="inline-flex items-center gap-1 px-2 py-0.5 bg-white border border-slate-200 rounded text-[10px] font-bold text-slate-600">
                                                                <Pill className="w-2.5 h-2.5" /> {drug}
                                                            </span>
                                                        ))}
                                                    </div>
                                                </div>
                                            )}
                                        </div>

                                        <div>
                                            <p className="text-[10px] font-black uppercase opacity-50 mb-1">Mechanism / Reason</p>
                                            <div className="bg-white/50 p-3 rounded-lg border border-black/5">
                                                <p className="text-sm text-slate-800 leading-relaxed font-medium">
                                                    {alert.reason}
                                                </p>
                                            </div>
                                        </div>

                                        <div>
                                            <p className="text-[10px] font-black uppercase opacity-50 mb-1">Clinical Recommendation</p>
                                            <div className={`text-sm font-black p-3 rounded-lg flex items-start gap-2 ${
                                                alert.level === AlertLevel.RED ? 'bg-red-100 text-red-900' : 
                                                alert.level === AlertLevel.YELLOW ? 'bg-amber-100 text-amber-900' : 
                                                'bg-green-100 text-green-900'
                                            }`} role="alert">
                                                <span className="shrink-0 bg-white/40 px-1.5 rounded text-[10px] mt-0.5">Action</span>
                                                <span>{alert.action}</span>
                                            </div>
                                        </div>

                                        {alert.reference && (
                                            <div>
                                                <p className="text-[10px] font-black uppercase opacity-50 mb-1">Reference / Citation</p>
                                                <a 
                                                    href={alert.reference.startsWith('http') ? alert.reference : `https://scholar.google.com/scholar?q=${encodeURIComponent(alert.reference)}`}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    title="Opens in a new tab"
                                                    className="flex items-center gap-2 p-3 bg-slate-50 border border-slate-100 rounded-lg hover:bg-slate-100 transition-colors group/ref"
                                                    aria-label={`Open reference: ${alert.reference}`}
                                                >
                                                    <ExternalLink className="w-4 h-4 text-slate-400 group-hover/ref:text-teal-600" />
                                                    <span className="text-xs font-medium text-slate-600 group-hover/ref:text-teal-700 truncate">{alert.reference}</span>
                                                </a>
                                            </div>
                                        )}

                                        {/* Feedback Section for specific alert */}
                                        <div className="border-t border-dashed border-slate-200 pt-3 flex items-center justify-between">
                                           <span className="text-[10px] text-slate-400 font-bold">AI 정확도 평가:</span>
                                           <FeedbackControl idKey={alertIdKey} targetTitle={alert.title} category="ALERT" />
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )})
                    ) : (
                        <div className="py-8 text-center text-slate-400">
                            <p className="text-xs font-bold">검색 결과가 없습니다.</p>
                        </div>
                    )}
                </div>
            </section>
        )}

        <section className="mt-6" aria-labelledby="medications-heading">
            <h3 id="medications-heading" className="text-xs font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                <CheckCircle className="w-3 h-3 text-teal-500" aria-hidden="true" /> 인식된 약물 (가명화)
            </h3>
            <div className="grid grid-cols-1 gap-2" role="list">
                {analysis.medications.map((med, idx) => (
                    <div key={idx} role="listitem" className="p-3 bg-white border border-slate-100 rounded-xl flex items-center justify-between hover:border-teal-200 transition-colors shadow-sm">
                        <div className="flex items-center gap-3">
                            <div className="w-8 h-8 bg-slate-50 rounded-lg flex items-center justify-center text-lg" aria-hidden="true">💊</div>
                            <div>
                                <p className="font-bold text-slate-800 text-sm leading-none mb-1">{med.name}</p>
                                <p className="text-[10px] text-slate-500 font-medium">{med.ingredient}</p>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="inline-block px-2 py-1 bg-teal-50 text-teal-700 text-[10px] rounded-md font-black">
                                {med.frequency}
                            </span>
                        </div>
                    </div>
                ))}
            </div>
        </section>
      </div>

      <footer className="p-3 bg-slate-900 text-[9px] text-slate-500 text-center font-bold">
         AI 분석은 임상 보조 수단이며, 법적 책임은 최종 승인한 약사에게 있습니다. (의료법 제27조 준수)
      </footer>
    </article>
  );
};

export default ClinicalDashboard;

export interface Diagnosis {
  code: string; // 상병코드 (ICD-10 등)
  name: string; // 병명
}

export interface Patient {
  id: string;
  name: string;
  birthDate: string;
  age: number;
  gender: 'M' | 'F';
  conditions: string[]; // 환자가 구두로 호소한 만성/기저질환 (수동 입력)
  diagnosisCodes: Diagnosis[]; // 처방전 스캔을 통해 입력된 금번 상병/진단 (자동 추출)
  eGFR?: number;
  visitType: 'Home' | 'Pharmacy';
}

export enum AlertLevel {
  RED = 'RED',
  YELLOW = 'YELLOW',
  GREEN = 'GREEN'
}

export interface ClinicalAlert {
  level: AlertLevel;
  title: string;
  reason: string;
  action: string;
  drugsInvolved: string[];
  isVerifiedByLocalDB?: boolean;
  reference?: string;
}

export interface Medication {
  name: string;
  ingredient: string;
  dosage: string;
  frequency: string;
  category?: string;
}

export interface ExtractedPatientInfo {
  name?: string;
  age?: number;
  gender?: 'M' | 'F';
  birthDate?: string;
}

export interface AnalysisResult {
  medications: Medication[];
  alerts: ClinicalAlert[];
  summary: string;
  extractedPatientInfo?: ExtractedPatientInfo; // 스캔된 환자 정보 (명시된 경우만)
  diagnoses?: Diagnosis[]; // 스캔된 상병코드 및 병명
  isVerifiedByPharmacist?: boolean;
}

export type UserRole = 'USER' | 'ADMIN';
export type UserStatus = 'PENDING' | 'ACTIVE' | 'REJECTED';

