import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, AlertLevel, Patient } from "../types";
import { checkLocalDUR } from "./durEngine";
import { searchWhoDb, WHO_ADVERSE_DB } from "./whoAdverseDb";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function cleanJsonString(text: string): string {
  let cleaned = text.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return cleaned;
}

/**
 * 시뮬레이션: 전송 전 로컬 환경에서 개인정보 마스킹
 * 실제 구현 시에는 NER(개체명 인식) 라이브러리를 통해 성함 등을 마스킹함.
 */
const simulateLocalMasking = async (base64: string) => {
    // 0.5초간 마스킹 프로세스 시뮬레이션
    return new Promise(resolve => setTimeout(() => resolve(base64), 500));
};

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    // [보완] 전송 전 로컬 마스킹 단계 거침 (Legal Compliance)
    const maskedBase64 = await simulateLocalMasking(base64Image);

    const modelId = "gemini-3-pro-preview"; 

    const prompt = `
      System Instruction:
      You are a Clinical Pharmacist AI Assistant.

      TASK 1: TEXT EXTRACTION (Strictly based on visible text)
      - Analyze the prescription or medication bag image.
      - **Patient Information**: Extract 'Name', 'Age', 'Gender', or 'Birth Date' ONLY IF explicitly written on the document. Do NOT guess or infer. If not found, leave fields null.
      - **Diagnosis/Disease Codes**: Extract any ICD-10 codes (e.g., J20.9, I10) and Disease Names (e.g., Acute Bronchitis, Essential Hypertension) explicitly written.
        - **CRITICAL**: Do NOT infer diseases from the medication list. Only extract what is printed as a diagnosis.
      - **Medications**: Extract all visible medication names, dosages, and instructions.

      TASK 2: CLINICAL ANALYSIS
      - Based on the extracted medications and the provided patient context (below), check for:
        1. Drug-Drug Interactions
        2. Beers Criteria (for elderly patients)
        3. Dosage warnings
      - Provide clinical references or guidelines (e.g. 'AGS Beers Criteria 2023') in 'reference' field if available.

      Patient Clinical Data (Context):
      ${patientContext}

      Return ONLY raw JSON matching the schema.
      Language: Korean (한국어).
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: maskedBase64 } },
          { text: prompt },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                extractedPatientInfo: {
                    type: Type.OBJECT,
                    properties: {
                        name: { type: Type.STRING },
                        age: { type: Type.NUMBER },
                        gender: { type: Type.STRING, enum: ["M", "F"] },
                        birthDate: { type: Type.STRING }
                    },
                    description: "Extract ONLY if explicitly printed on the document."
                },
                diagnoses: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            code: { type: Type.STRING, description: "ICD-10 Code (e.g. J20.9)" },
                            name: { type: Type.STRING, description: "Disease Name (e.g. 급성 기관지염)" }
                        }
                    },
                    description: "Extract explicitly printed diagnosis codes and names. DO NOT INFER from drugs."
                },
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING },
                            reason: { type: Type.STRING },
                            action: { type: Type.STRING },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN },
                            reference: { type: Type.STRING }
                        }
                    }
                },
                summary: { type: Type.STRING }
            }
        }
      },
    });

    if (response.text) {
      let parsed: AnalysisResult;
      try {
        const cleanedText = cleanJsonString(response.text);
        parsed = JSON.parse(cleanedText) as AnalysisResult;

        // Ensure arrays are initialized to avoid UI errors
        parsed.medications = parsed.medications || [];
        parsed.alerts = parsed.alerts || [];
        parsed.diagnoses = parsed.diagnoses || [];

      } catch (e) {
        console.error("JSON Parsing Error:", e);
        throw new Error("Invalid JSON response from AI");
      }

      parsed.isVerifiedByPharmacist = false; // Initial state: Not verified

      const drugNames = parsed.medications.map(m => m.name || m.ingredient || "");
      const localAlerts = checkLocalDUR(drugNames);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => 
            (a.title && (a.title.includes(local.drugA) || a.title.includes(local.drugB)))
          );

          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB || '주의'} 이슈`,
                  reason: local.reason,
                  action: "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
                  drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
                  isVerifiedByLocalDB: true,
                  reference: local.reference
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: "분석 중 오류가 발생했습니다.",
    };
  }
};

export const askClinicalAi = async (
  query: string,
  patient: Patient,
  analysis: AnalysisResult | null
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // 1. 환자의 현재 약물 리스트 추출
    const currentMeds = analysis && analysis.medications 
      ? analysis.medications.map(m => m.name || m.ingredient).filter(Boolean) as string[] 
      : [];

    // 2. WHO DB에서 관련 정보 검색 (Grounding)
    // 쿼리나 약물 리스트와 연관된 DB 항목을 찾아 컨텍스트에 주입합니다.
    const relevantWhoData = searchWhoDb(currentMeds, query);

    const whoContextData = relevantWhoData.length > 0 
        ? JSON.stringify(relevantWhoData, null, 2)
        : "No direct match in Local WHO DB. Use general pharmacological knowledge based on WHO criteria.";

    // 3. Prompt Engineering
    const clinicalContext = `
      [Clinical Context - No Personal ID]
      - Age: ${patient.age}, Gender: ${patient.gender}
      - Conditions: ${patient.conditions.join(", ")}
      - Current Diagnosis (Scan): ${patient.diagnosisCodes.map(d => `${d.code}:${d.name}`).join(", ")}
      - eGFR: ${patient.eGFR || 'Unknown'}
      - Medications: ${currentMeds.join(", ")}

      [WHO Adverse Reaction Database (Local Knowledge)]
      ${whoContextData}

      [Task Definition]
      You are a specialized expert in 'Adverse Drug Reaction (ADR) Causality Assessment'.
      The user is asking about a symptom. You must evaluate if any of the patient's medications could be the cause based on the WHO-UMC Causality Categories (Certain, Probable, Possible, Unlikely).

      [Output Requirements]
      1. If the user reports a symptom (e.g., dizziness, edema, pain), you MUST output the analysis in a MARKDOWN TABLE format exactly as below:

      | 호소 증상 | 의심되는 원인약물 | 인과정도 (WHO Criteria) | 근거 및 평가 (Mechanism) |
      |---|---|---|---|
      | (Symptom) | (Drug Name) | (Certain/Probable/Possible/Unlikely) | (Explain mechanism & WHO criteria logic) |

      2. If multiple drugs are suspected, list them in separate rows.
      3. If no specific drug is suspected but the symptom is concerning, state that in the table with 'Unknown' drug.
      4. After the table, provide a brief clinical recommendation in Korean.
      5. If a 'reference' URL is available in the WHO DB entry, please include it at the bottom of the response labeled as '[Reference]'.
      6. Use the provided [WHO Adverse Reaction Database] as the primary source of truth. If the drug is in the DB, use that data. If not, infer based on general medical knowledge.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: clinicalContext },
        { text: query }
      ],
      config: {
        systemInstruction: "You are a BCGP Assistant. Use only Korean for the final explanation, but keep WHO Criteria terms (Certain, Probable etc) in English/Korean mix for clarity. Never ask for Personal IDs.",
        temperature: 0.4, // 낮춤 (사실 기반 답변 유도)
      }
    });

    return response.text || "답변을 생성하지 못했습니다.";
  } catch (error) {
    return "상담 중 오류가 발생했습니다.";
  }
};

import React, { useState } from 'react';
import { AnalysisResult, AlertLevel, FeedbackRating } from '../types';
import { AlertTriangle, CheckCircle, Info, ShieldAlert, Database, Search, ShieldCheck, ChevronDown, ChevronUp, Activity, Pill, ExternalLink, X, ThumbsUp, ThumbsDown, MessageSquare } from 'lucide-react';
import { submitFeedback } from '../services/feedbackService';

interface ClinicalDashboardProps {
  analysis: AnalysisResult | null;
}

// Local state interface for feedback UI
interface FeedbackState {
  isRateMode: boolean;
  rating: FeedbackRating | null;
  comment: string;
  submitted: boolean;
}

const ClinicalDashboard: React.FC<ClinicalDashboardProps> = ({ analysis: initialAnalysis }) => {
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(initialAnalysis);
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Map to store feedback state for each alert by index (or unique ID if available)
  const [feedbackMap, setFeedbackMap] = useState<Record<string, FeedbackState>>({});

  React.useEffect(() => {
    setAnalysis(initialAnalysis);
    setExpandedIndex(null);
    setSearchTerm('');
    setFeedbackMap({});
  }, [initialAnalysis]);

  const handleVerify = () => {
    if (analysis) {
        setAnalysis({ ...analysis, isVerifiedByPharmacist: true });
    }
  };

  const toggleAlert = (idx: number) => {
    setExpandedIndex(expandedIndex === idx ? null : idx);
  };

  const initFeedback = (key: string, rating: FeedbackRating) => {
    setFeedbackMap(prev => ({
      ...prev,
      [key]: { isRateMode: true, rating, comment: '', submitted: false }
    }));
  };

  const updateFeedbackComment = (key: string, comment: string) => {
    setFeedbackMap(prev => ({
      ...prev,
      [key]: { ...prev[key], comment }
    }));
  };

  const sendFeedback = async (key: string, targetTitle: string, category: 'ALERT' | 'OVERALL_ANALYSIS') => {
    const state = feedbackMap[key];
    if (!state || !state.rating) return;

    await submitFeedback({
      targetId: targetTitle,
      category: category,
      rating: state.rating,
      comment: state.comment,
      timestamp: new Date().toISOString()
    });

    setFeedbackMap(prev => ({
      ...prev,
      [key]: { ...prev[key], submitted: true, isRateMode: false }
    }));
  };

  const FeedbackControl = ({ idKey, targetTitle, category }: { idKey: string, targetTitle: string, category: 'ALERT' | 'OVERALL_ANALYSIS' }) => {
    const state = feedbackMap[idKey] || { isRateMode: false, rating: null, submitted: false };

    if (state.submitted) {
      return (
        <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold bg-slate-50 px-2 py-1 rounded border border-slate-100 animate-in fade-in">
          <CheckCircle className="w-3 h-3 text-teal-500" />
          피드백이 반영되었습니다.
        </div>
      );
    }

    if (state.isRateMode) {
      return (
        <div className="flex flex-col gap-2 bg-slate-50 p-3 rounded-lg border border-slate-200 animate-in zoom-in-95 duration-200">
          <div className="flex items-center justify-between">
             <span className="text-xs font-bold text-slate-600">이 분석이 도움이 되었나요?</span>
             <div className="flex gap-2">
                <button 
                  onClick={() => initFeedback(idKey, 'POSITIVE')} 
                  className={`p-1.5 rounded hover:bg-white transition-colors ${state.rating === 'POSITIVE' ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400'}`}
                >
                  <ThumbsUp className="w-4 h-4" />
                </button>
                <button 
                  onClick={() => initFeedback(idKey, 'NEGATIVE')}
                  className={`p-1.5 rounded hover:bg-white transition-colors ${state.rating === 'NEGATIVE' ? 'text-red-500 bg-white shadow-sm' : 'text-slate-400'}`}
                >
                  <ThumbsDown className="w-4 h-4" />
                </button>
             </div>
          </div>
          <input 
            type="text" 
            placeholder="추가 의견을 남겨주세요 (선택사항)"
            value={state.comment}
            onChange={(e) => updateFeedbackComment(idKey, e.target.value)}
            className="w-full text-xs p-2 rounded border border-slate-200 focus:outline-none focus:border-teal-400"
            onKeyDown={(e) => e.key === 'Enter' && sendFeedback(idKey, targetTitle, category)}
          />
          <div className="flex justify-end gap-2">
             <button 
                onClick={() => setFeedbackMap(prev => ({ ...prev, [idKey]: { ...prev[idKey], isRateMode: false } }))}
                className="text-[10px] text-slate-400 hover:text-slate-600 px-2 py-1"
             >
               취소
             </button>
             <button 
                onClick={() => sendFeedback(idKey, targetTitle, category)}
                className="text-[10px] bg-slate-800 text-white px-3 py-1.5 rounded font-bold hover:bg-black transition-colors"
             >
               피드백 보내기
             </button>
          </div>
        </div>
      );
    }

    return (
      <div className="flex items-center gap-1">
         <button 
            onClick={(e) => { e.stopPropagation(); initFeedback(idKey, 'POSITIVE'); }}
            className="p-1.5 text-slate-300 hover:text-teal-600 hover:bg-teal-50 rounded transition-all"
            title="유용함"
         >
            <ThumbsUp className="w-3.5 h-3.5" />
         </button>
         <button 
            onClick={(e) => { e.stopPropagation(); initFeedback(idKey, 'NEGATIVE'); }}
            className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded transition-all"
            title="부정확함"
         >
            <ThumbsDown className="w-3.5 h-3.5" />
         </button>
      </div>
    );
  };

