const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function cleanJsonString(text: string): string {
  let cleaned = text.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return cleaned;
}

/**
 * 시뮬레이션: 전송 전 로컬 환경에서 개인정보 마스킹
 * 실제 구현 시에는 NER(개체명 인식) 라이브러리를 통해 성함 등을 마스킹함.
 */
const simulateLocalMasking = async (base64: string) => {
    // 0.5초간 마스킹 프로세스 시뮬레이션
    return new Promise(resolve => setTimeout(() => resolve(base64), 500));
};

export const analyzeMedicalImage = async (
  base64Image: string,
  patientContext: string
): Promise<AnalysisResult> => {
  try {
    // [보완] 전송 전 로컬 마스킹 단계 거침 (Legal Compliance)
    const maskedBase64 = await simulateLocalMasking(base64Image);

    const modelId = "gemini-3-pro-preview"; 

    const prompt = `
      System Instruction:
      You are a Clinical Pharmacist AI Assistant (Korean Language).

      [CRITICAL RULES]
      1. **PURE JSON ONLY**: Do not output any reasoning, internal monologue, or notes inside the JSON fields.
      2. **LANGUAGE**: All generated text (summary, reasons, actions) MUST be in **Korean (한국어)**.
      3. **DATA INTEGRITY**: 
         - If the extracted patient info differs from the provided context, prioritize the info VISIBLE in the image for the 'extractedPatientInfo' field.
         - Do NOT explain discrepancies in the data fields (e.g., 'name' should be just "김철수", not "김철수 (differs from context)").

      TASK 1: TEXT EXTRACTION
      - Analyze the prescription or medication bag image.
      - **Patient Information**: Extract 'Name', 'Age', 'Gender', or 'Birth Date' visible on the document. 
      - **Diagnosis/Disease Codes**: Extract ICD-10 codes (e.g., J20.9) and Disease Names explicitly written.
      - **Medications**: Extract all visible medication names, dosages, and instructions.

      TASK 2: CLINICAL ANALYSIS
      - Based on the extracted medications and the provided patient context (below), check for:
        1. Drug-Drug Interactions
        2. Beers Criteria (for elderly patients)
        3. Dosage warnings
      - Provide clinical references (e.g. 'AGS Beers Criteria 2023').

      Patient Clinical Data (Context):
      ${patientContext}
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: maskedBase64 } },
          { text: prompt },
        ],
      },
      config: {
        // Disable thinking to prevent Chain-of-Thought from leaking into JSON fields
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                extractedPatientInfo: {
                    type: Type.OBJECT,
                    properties: {
                        name: { type: Type.STRING, description: "Patient name (e.g. '홍길동')" },
                        age: { type: Type.NUMBER },
                        gender: { type: Type.STRING, enum: ["M", "F"] },
                        birthDate: { type: Type.STRING }
                    },
                    description: "Extract ONLY if explicitly printed on the document."
                },
                diagnoses: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            code: { type: Type.STRING, description: "ICD-10 Code (e.g. J20.9)" },
                            name: { type: Type.STRING, description: "Disease Name (e.g. 급성 기관지염)" }
                        }
                    },
                    description: "Extract explicitly printed diagnosis codes and names."
                },
                medications: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            ingredient: { type: Type.STRING },
                            dosage: { type: Type.STRING },
                            frequency: { type: Type.STRING },
                            category: { type: Type.STRING }
                        }
                    }
                },
                alerts: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            level: { type: Type.STRING, enum: ["RED", "YELLOW", "GREEN"] },
                            title: { type: Type.STRING, description: "In Korean" },
                            reason: { type: Type.STRING, description: "In Korean" },
                            action: { type: Type.STRING, description: "In Korean" },
                            drugsInvolved: { type: Type.ARRAY, items: { type: Type.STRING } },
                            isVerifiedByLocalDB: { type: Type.BOOLEAN },
                            reference: { type: Type.STRING }
                        }
                    }
                },
                summary: { type: Type.STRING, description: "Clinical summary in Korean" }
            }
        }
      },
    });

    if (response.text) {
      let parsed: AnalysisResult;
      try {
        const cleanedText = cleanJsonString(response.text);
        parsed = JSON.parse(cleanedText) as AnalysisResult;

        // Ensure arrays are initialized to avoid UI errors
        parsed.medications = parsed.medications || [];
        parsed.alerts = parsed.alerts || [];
        parsed.diagnoses = parsed.diagnoses || [];

      } catch (e) {
        console.error("JSON Parsing Error:", e);
        throw new Error("Invalid JSON response from AI");
      }

      parsed.isVerifiedByPharmacist = false; // Initial state: Not verified

      const drugNames = parsed.medications.map(m => m.name || m.ingredient || "");
      const localAlerts = checkLocalDUR(drugNames);

      localAlerts.forEach(local => {
          const alreadyExists = parsed.alerts.some(a => 
            (a.title && (a.title.includes(local.drugA) || a.title.includes(local.drugB)))
          );

          if (!alreadyExists) {
              parsed.alerts.push({
                  level: local.severity === 'CRITICAL' ? AlertLevel.RED : AlertLevel.YELLOW,
                  title: `[Local DB] ${local.drugA} - ${local.drugB || '주의'} 이슈`,
                  reason: local.reason,
                  action: "로컬 데이터베이스 규칙에 따른 주의가 필요합니다.",
                  drugsInvolved: [local.drugA, local.drugB].filter(Boolean) as string[],
                  isVerifiedByLocalDB: true,
                  reference: local.reference
              });
          }
      });

      return parsed;
    }

    throw new Error("No response from AI");
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      medications: [],
      alerts: [],
      summary: "분석 중 오류가 발생했습니다.",
    };
  }
};

export const askClinicalAi = async (
  query: string,
  patient: Patient,
  analysis: AnalysisResult | null
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // 1. 환자의 현재 약물 리스트 추출
    const currentMeds = analysis && analysis.medications 
      ? analysis.medications.map(m => m.name || m.ingredient).filter(Boolean) as string[] 
      : [];

    // 2. WHO DB에서 관련 정보 검색 (Grounding)
    // 쿼리나 약물 리스트와 연관된 DB 항목을 찾아 컨텍스트에 주입합니다.
    const relevantWhoData = searchWhoDb(currentMeds, query);

    const whoContextData = relevantWhoData.length > 0 
        ? JSON.stringify(relevantWhoData, null, 2)
        : "No direct match in Local WHO DB. Use general pharmacological knowledge based on WHO criteria.";

    // 3. Prompt Engineering
    const clinicalContext = `
      [Clinical Context - No Personal ID]
      - Age: ${patient.age}, Gender: ${patient.gender}
      - Conditions: ${patient.conditions.join(", ")}
      - Current Diagnosis (Scan): ${patient.diagnosisCodes.map(d => `${d.code}:${d.name}`).join(", ")}
      - eGFR: ${patient.eGFR || 'Unknown'}
      - Medications: ${currentMeds.join(", ")}

      [WHO Adverse Reaction Database (Local Knowledge)]
      ${whoContextData}

      [Task Definition]
      You are a specialized expert in 'Adverse Drug Reaction (ADR) Causality Assessment'.
      The user is asking about a symptom. You must evaluate if any of the patient's medications could be the cause based on the WHO-UMC Causality Categories (Certain, Probable, Possible, Unlikely).

      [Output Requirements]
      1. If the user reports a symptom (e.g., dizziness, edema, pain), you MUST output the analysis in a MARKDOWN TABLE format exactly as below:

      | 호소 증상 | 의심되는 원인약물 | 인과정도 (WHO Criteria) | 근거 및 평가 (Mechanism) |
      |---|---|---|---|
      | (Symptom) | (Drug Name) | (Certain/Probable/Possible/Unlikely) | (Explain mechanism & WHO criteria logic) |

      2. If multiple drugs are suspected, list them in separate rows.
      3. If no specific drug is suspected but the symptom is concerning, state that in the table with 'Unknown' drug.
      4. After the table, provide a brief clinical recommendation in Korean.
      5. If a 'reference' URL is available in the WHO DB entry, please include it at the bottom of the response labeled as '[Reference]'.
      6. Use the provided [WHO Adverse Reaction Database] as the primary source of truth. If the drug is in the DB, use that data. If not, infer based on general medical knowledge.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: clinicalContext },
        { text: query }
      ],
      config: {
        systemInstruction: "You are a BCGP Assistant. Use only Korean for the final explanation, but keep WHO Criteria terms (Certain, Probable etc) in English/Korean mix for clarity. Never ask for Personal IDs.",
        temperature: 0.4, // 낮춤 (사실 기반 답변 유도)
      }
    });

    return response.text || "답변을 생성하지 못했습니다.";
  } catch (error) {
    return "상담 중 오류가 발생했습니다.";
  }
};

import React, { useState } from 'react';
import Header from './components/Header';
import LandingPage from './components/LandingPage';
import AuthPage from './components/AuthPage';
import LicenseVerification from './components/LicenseVerification';
import PatientProfile from './components/PatientProfile';
import DrugScanner from './components/DrugScanner';
import ClinicalDashboard from './components/ClinicalDashboard';
import SmartOutput from './components/SmartOutput';
import ClinicalAssistant from './components/ClinicalAssistant';
import AdminPanel from './components/AdminPanel';
import { Pharmacist, Patient, AnalysisResult, ViewMode, UserRole, UserStatus } from './types';

const DEFAULT_PATIENT: Patient = {
  id: 'p-001',
  name: '김필순',
  birthDate: '1947.05.20',
  age: 78,
  gender: 'F',
  conditions: ['고혈압', '관절염', '신장 질환(eGFR < 60)'], // 환자 구두 정보 (수동)
  diagnosisCodes: [], // 처방전 스캔 정보 (자동)
  eGFR: 58,
  visitType: 'Home'
};

// Initial Mock Database
const INITIAL_USERS: Pharmacist[] = [
  {
    id: 'admin',
    name: '관리자',
    licenseNumber: '00000',
    isVerified: true,
    role: 'ADMIN',
    status: 'ACTIVE',
    requestDate: '2024-01-01',
    password: 'admin'
  },
  {
    id: 'testuser',
    name: '홍길동',
    licenseNumber: '12345',
    isVerified: true,
    role: 'USER',
    status: 'ACTIVE',
    requestDate: '2024-02-15',
    password: '1234'
  }
];

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.LANDING);
  const [pharmacist, setPharmacist] = useState<Pharmacist | null>(null);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);

  // Patient State (Editable)
  const [patient, setPatient] = useState<Patient>(DEFAULT_PATIENT);

  // Simulated Database State
  const [userDB, setUserDB] = useState<Pharmacist[]>(INITIAL_USERS);

  const handleGoToAuth = () => setViewMode(ViewMode.AUTH);

  const handleLogin = (id: string, password?: string) => {
    const user = userDB.find(u => u.id === id);

    if (!user) {
      alert("존재하지 않는 아이디입니다.");
      return;
    }

    if (user.password !== password) {
        alert("비밀번호가 일치하지 않습니다.");
        return;
    }

    if (user.status === 'REJECTED') {
      alert("가입이 거절된 계정입니다. 관리자에게 문의하세요.");
      return;
    }

    setPharmacist(user);
    setViewMode(ViewMode.DASHBOARD);
  };

  const handleSignupClick = () => {
    setViewMode(ViewMode.VERIFICATION);
  };

  // Function to check if ID is available (passed to LicenseVerification)
  const checkIdAvailability = (id: string): boolean => {
      return !userDB.some(u => u.id === id);
  };

  const handleVerificationSuccess = (newUser: Pharmacist) => {
    // Check duplicate license just in case
    const licenseExists = userDB.some(u => u.licenseNumber === newUser.licenseNumber);
    if (licenseExists) {
        alert("이미 가입된 면허번호입니다. 관리자에게 문의하세요.");
        return;
    }

    // Add to DB
    setUserDB(prev => [...prev, newUser]);
    setPharmacist(newUser);

    if (newUser.status === 'ACTIVE') {
        setViewMode(ViewMode.DASHBOARD);
    } else {
        alert("가입 요청이 완료되었습니다. 관리자 승인 후 로그인 가능합니다.");
        setViewMode(ViewMode.LANDING);
    }
  };

  const handleEnterDashboard = () => {
      if (pharmacist?.status === 'ACTIVE') {
          setViewMode(ViewMode.DASHBOARD);
      } else {
          alert("아직 가입 승인 대기 중입니다. 약사님의 수동 확인을 기다려주세요!");
      }
  };

  const handleLogout = () => {
    setPharmacist(null);
    setAnalysisResult(null);
    setViewMode(ViewMode.LANDING);
  };

  const toggleAdminPanel = () => {
    setViewMode(prev => prev === ViewMode.ADMIN_PANEL ? ViewMode.DASHBOARD : ViewMode.ADMIN_PANEL);
  };

  // Admin Actions
  const handleAdminApprove = (id: string) => {
      setUserDB(prev => prev.map(u => u.id === id ? { ...u, status: 'ACTIVE', isVerified: true } : u));
  };

  const handleAdminReject = (id: string) => {
      setUserDB(prev => prev.map(u => u.id === id ? { ...u, status: 'REJECTED', isVerified: false } : u));
  };

  // New handler for scan completion
  const handleScanComplete = (result: AnalysisResult) => {
    setAnalysisResult(result);

    setPatient(prev => {
        const updated = { ...prev };

        // 1. 환자 기본 정보 업데이트 (스캔 결과에 명시된 경우만)
        if (result.extractedPatientInfo) {
            // Safety Check: Avoid setting name if AI returned a long reasoning string
            const safeName = result.extractedPatientInfo.name;
            if (safeName && safeName.length < 20) {
                updated.name = safeName;
            }

            if (result.extractedPatientInfo.age) updated.age = result.extractedPatientInfo.age;
            if (result.extractedPatientInfo.gender) updated.gender = result.extractedPatientInfo.gender;
            if (result.extractedPatientInfo.birthDate) updated.birthDate = result.extractedPatientInfo.birthDate;
        }

        // 2. 상병코드(Diagnoses) 업데이트 (스캔 결과에 명시된 경우만)
        // 기존 Manual Conditions는 건드리지 않고, DiagnosisCodes만 새로 덮어씁니다.
        if (result.diagnoses && result.diagnoses.length > 0) {
            updated.diagnosisCodes = result.diagnoses;
        }

        return updated;
    });
  };

  if (viewMode === ViewMode.LANDING) {
    return (
      <LandingPage 
        pharmacist={pharmacist}
        onLogin={handleGoToAuth} 
        onLogout={handleLogout}
        onDashboard={handleEnterDashboard} 
      />
    );
  }

  if (viewMode === ViewMode.AUTH) {
    return (
      <AuthPage 
        onLogin={handleLogin}
        onSignupClick={handleSignupClick}
        onBack={() => setViewMode(ViewMode.LANDING)}
      />
    );
  }

  if (viewMode === ViewMode.VERIFICATION) {
    return <LicenseVerification 
        onVerified={handleVerificationSuccess} 
        checkDuplicateId={checkIdAvailability}
    />;
  }

  if (viewMode === ViewMode.ADMIN_PANEL && pharmacist?.role === 'ADMIN') {
      return (
          <div className="min-h-screen flex flex-col">
              <Header 
                  pharmacistName={pharmacist.name} 
                  role={pharmacist.role}
                  onLogout={handleLogout} 
                  onToggleAdmin={toggleAdminPanel}
              />
              <AdminPanel 
                  onBack={() => setViewMode(ViewMode.DASHBOARD)} 
                  users={userDB}
                  onApprove={handleAdminApprove}
                  onReject={handleAdminReject}
              />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header 
        pharmacistName={pharmacist?.name || '약사'} 
        role={pharmacist?.role || 'USER'}
        onLogout={handleLogout} 
        onToggleAdmin={toggleAdminPanel}
      />

      <main className="flex-1 p-4 md:p-6 overflow-hidden h-[calc(100vh-64px)]">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
          <div className="lg:col-span-3 flex flex-col h-full overflow-hidden">
            <div className="flex-none">
              <PatientProfile 
                patient={patient} 
                onUpdate={setPatient}
              />
            </div>
            <div className="mt-4 flex-1 flex flex-col overflow-hidden">
              <ClinicalAssistant 
                patient={patient}
                analysis={analysisResult}
              />
              <DrugScanner 
                  onAnalysisComplete={handleScanComplete} 
                  patient={patient}
              />
            </div>
          </div>
          <div className="lg:col-span-5 h-full overflow-hidden">
             <ClinicalDashboard analysis={analysisResult} />
          </div>
          <div className="lg:col-span-4 h-full overflow-hidden">
             <SmartOutput analysis={analysisResult} />
          </div>
        </div>
      </main>
    </div>
  );
};

